LoginSARMedix/Views/Home/AccesoDenegado..text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "AccesoDenegado"; ViewData["SmFamily"] = "access"; }
@{
    Layout = null;

    string nombreCompleto =
        ViewBag.Nombre + " " + ViewBag.Apellido;

    string inicial =
        !string.IsNullOrEmpty(ViewBag.Nombre?.ToString())
        ? ViewBag.Nombre.ToString().Substring(0, 1).ToUpper()
        : "U";
}

<!DOCTYPE html>

<html lang="es">

<head>

    <meta charset="utf-8" />

    <meta name="viewport"
          content="width=device-width, initial-scale=1.0" />

    <title>Acceso Denegado - SARMedix</title>


    <style>

        * {
            box-sizing: border-box;
        }


        body {
            margin: 0;

            font-family:
                "Segoe UI",
                Arial,
                sans-serif;

            color: #17324d;

            background:
                linear-gradient(
                    rgba(235, 247, 252, 0.82),
                    rgba(235, 247, 252, 0.82)
                ),
                url('/images/fondo-clinico.png');

            background-size: cover;

            background-position: center;

            background-attachment: fixed;

            min-height: 100vh;
        }



        /* BARRA SUPERIOR */

        .barra-superior {
            height: 82px;

            display: grid;

            grid-template-columns:
                1fr
                1fr
                1fr;

            align-items: center;

            padding:
                0 60px;

            background: #0f5278;

            color: white;

            box-shadow:
                0 3px 10px
                rgba(0, 0, 0, 0.15);
        }



        /* LOGO */

        .logo {
            display: flex;

            align-items: center;

            gap: 14px;
        }


        .logo-cruz-medica {
            width: 48px;
            height: 48px;

            background: white;

            border-radius: 12px;

            display: flex;

            align-items: center;

            justify-content: center;
        }


        .cruz {
            position: relative;

            width: 22px;
            height: 22px;

            display: block;
        }


        .cruz::before,
        .cruz::after {
            content: "";

            position: absolute;

            background: #0b6fb8;

            border-radius: 3px;
        }


        .cruz::before {
            width: 8px;
            height: 22px;

            left: 7px;
            top: 0;
        }


        .cruz::after {
            width: 22px;
            height: 8px;

            left: 0;
            top: 7px;
        }


        .logo-texto {
            font-size: 25px;

            font-weight: 700;

            white-space: nowrap;
        }



        /* TITULO SUPERIOR */

        .titulo-superior {
            text-align: center;

            font-size: 25px;

            font-weight: 600;
        }



        /* USUARIO */

        .usuario-superior {
            display: flex;

            justify-content: flex-end;

            align-items: center;

            gap: 16px;
        }


        .usuario-datos {
            text-align: right;
        }


        .usuario-nombre {
            display: block;

            font-size: 16px;

            font-weight: 600;
        }


        .usuario-rol {
            display: block;

            margin-top: 2px;

            font-size: 13px;

            opacity: 0.85;
        }


        .usuario-circulo {
            width: 48px;
            height: 48px;

            display: flex;

            align-items: center;

            justify-content: center;

            border-radius: 50%;

            background:
                rgba(255, 255, 255, 0.22);

            font-size: 20px;

            font-weight: 600;
        }



        /* CONTENIDO */

        .contenedor {
            width: 90%;

            max-width: 600px;

            margin:
                80px auto;

            text-align: center;
        }


        .tarjeta {
            padding: 45px;

            background:
                rgba(255, 255, 255, 0.96);

            border-radius: 14px;

            box-shadow:
                0 7px 20px
                rgba(28, 65, 95, 0.15);
        }


        .icono {
            width: 75px;
            height: 75px;

            margin:
                0 auto 20px;

            display: flex;

            align-items: center;

            justify-content: center;

            border-radius: 50%;

            background: #fdecec;

            color: #b43d3d;

            font-size: 34px;

            font-weight: bold;
        }


        .titulo {
            margin-bottom: 12px;

            color: #17324d;

            font-size: 30px;
        }


        .descripcion {
            margin-bottom: 30px;

            color: #687b89;

            font-size: 16px;

            line-height: 1.5;
        }


        .btn-volver {
            display: inline-block;

            padding:
                12px 22px;

            background: #0b8f9c;

            color: white;

            text-decoration: none;

            border-radius: 7px;

            font-weight: 600;
        }


        .btn-volver:hover {
            background: #087580;

            color: white;
        }



        @@media (max-width: 900px) {

            .barra-superior {
                grid-template-columns:
                    1fr
                    1fr;

                height: auto;

                min-height: 82px;

                padding:
                    15px 25px;
            }


            .titulo-superior {
                display: none;
            }


            .logo-texto {
                font-size: 20px;
            }
        }

    </style>

<!-- SM-ORBITA-STANDALONE -->
<link rel="stylesheet" href="~/css/sarmedix-system.css" asp-append-version="true" />
</head>


<body class="sm-standalone" data-sm-family="access" data-sm-screen="AccesoDenegado">


    <header class="barra-superior">


        <div class="logo">


            <div class="logo-cruz-medica">

                <span class="cruz"></span>

            </div>


            <div class="logo-texto">

                SARMedix | SAR de Chiguay

            </div>


        </div>



        <div class="titulo-superior">

            Acceso Restringido

        </div>



        <div class="usuario-superior">


            <div class="usuario-datos">


                <span class="usuario-nombre">

                    @nombreCompleto

                </span>


                <span class="usuario-rol">

                    @ViewBag.Rol

                </span>


            </div>


            <div class="usuario-circulo">

                @inicial

            </div>


        </div>


    </header>



    <main class="contenedor">


        <div class="tarjeta">


            <div class="icono">

                !

            </div>


            <h1 class="titulo">

                Acceso denegado

            </h1>


            <p class="descripcion">

                Su rol no posee los permisos necesarios
                para acceder a esta función de SARMedix.

            </p>


            <a asp-controller="Home"
               asp-action="Modulos"
               class="btn-volver" data-orbit-action="secondary">

                ← Volver a los módulos

            </a>


        </div>


    </main>


<link rel="stylesheet" href="~/css/sarmedix-global.css" asp-append-version="true" />
</body>

</html>

LoginSARMedix/Views/Home/BajaInventario..text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "BajaInventario"; ViewData["SmFamily"] = "movements"; }
@using LoginSARMedix.Models
@model BajaInventario

@{
    ViewData["Title"] = "Baja / merma";
    ViewData["TituloBarra"] = "Baja / merma";

    var lotes =
        ViewBag.LotesBodega as List<Lote>
        ?? new List<Lote>();

    var unidades =
        ViewBag.UnidadesProductos as Dictionary<int, string>
        ?? new Dictionary<int, string>();

    string mensaje =
        TempData["Mensaje"]?.ToString()
        ?? "";

    string tipoMensaje =
        TempData["TipoMensaje"]?.ToString()
        ?? "";
}

<style>
    .salida-pagina{width:min(1040px,94%);margin:34px auto 48px}
    .salida-titulo{margin-bottom:18px}
    .salida-titulo h1{margin:0 0 6px;color:#123451;font-size:30px;font-weight:850}
    .salida-titulo p{margin:0;color:#5f788c}
    .aviso{padding:14px 16px;border:1px solid #f0c9a7;border-radius:10px;background:#fff7ed;color:#815025;margin-bottom:18px}
    .mensaje{padding:13px 16px;border-radius:10px;margin-bottom:18px;font-weight:750}
    .ok{background:#eaf8ef;border:1px solid #b8dfc5;color:#21633a}
    .error{background:#fff0f0;border:1px solid #efc1c1;color:#9d2f2f}
    .panel{background:rgba(255,255,255,.96);border-radius:16px;padding:24px;box-shadow:0 12px 30px rgba(30,72,103,.14)}
    .grid{display:grid;grid-template-columns:1.25fr .85fr;gap:22px}
    .bloque{border:1px solid #dae7ef;border-radius:13px;padding:20px;background:#fbfdff}
    label{display:block;margin:0 0 7px;color:#29465d;font-weight:750;font-size:14px}
    select,input,textarea{width:100%;padding:11px 12px;border:1px solid #c7d8e4;border-radius:9px;background:white;color:#17324d;font-size:14px}
    textarea{min-height:105px;resize:vertical}
    .campo{margin-bottom:17px}
    .resumen{border-radius:13px;padding:21px;background:linear-gradient(145deg,#8d4d22,#bb6b32);color:white}
    .fila{padding:10px 0;border-bottom:1px solid rgba(255,255,255,.2);display:flex;justify-content:space-between;gap:16px}
    .acciones{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}
    .btn{padding:10px 18px;border-radius:9px;font-weight:800;text-decoration:none;cursor:pointer}
    .volver{border:1px solid #cad9e4;background:white;color:#435f72}
    .confirmar{border:0;background:#a94f24;color:white}
    .confirmar:disabled{opacity:.45;cursor:not-allowed}
    @@media(max-width:800px){.grid{grid-template-columns:1fr}}
</style>

<section class="salida-pagina">

    <div class="salida-titulo">
        <h1>Baja / merma de inventario</h1>
        <p>Registra stock que debe salir definitivamente de una Bodega.</p>
    </div>

    <div class="aviso">
        ⚠ Esta acción <strong>no elimina el producto del catálogo</strong>.
        Descuenta stock de un lote y deja trazabilidad. Solo Enfermera o Administrador.
        Los medicamentos controlados continúan en su módulo restringido.
    </div>

    @if (!string.IsNullOrWhiteSpace(mensaje))
    {
        <div class="mensaje @(tipoMensaje == "exito" ? "ok" : "error")">
            @mensaje
        </div>
    }

    <form asp-controller="Home"
          asp-action="RegistrarBajaInventario"
          method="post"
          id="formBaja" data-orbit-form="BajaInventario">

        @Html.AntiForgeryToken()

        <div class="panel">
            <div class="grid">

                <section class="orbit-movement-input"><span class="orbit-eyebrow">BAJA / TRAZABILIDAD</span><div class="bloque">

                    <div class="campo">
                        <label asp-for="id_lote">Lote en Bodega</label>

                        <select asp-for="id_lote"
                                id="loteBaja"
                                required>
                            <option value="">Seleccione producto y lote...</option>

                            @foreach (var lote in lotes)
                            {
                                string unidad =
                                    unidades.ContainsKey(lote.id_producto)
                                        ? unidades[lote.id_producto]
                                        : "unidades";

                                <option value="@lote.id_lote"
                                        data-producto="@lote.nombre_producto"
                                        data-lote="@lote.numero_lote"
                                        data-sector="@lote.nombre_ubicacion"
                                        data-stock="@lote.cantidad_actual"
                                        data-unidad="@unidad"
                                        data-vencimiento="@(lote.fecha_vencimiento?.ToString("dd/MM/yyyy") ?? "-")">
                                    @lote.nombre_producto — Lote @lote.numero_lote — @lote.nombre_ubicacion — @lote.cantidad_actual @unidad
                                </option>
                            }
                        </select>
                    </div>

                    <div class="campo">
                        <label asp-for="cantidad">Cantidad a dar de baja</label>
                        <input asp-for="cantidad"
                               id="cantidadBaja"
                               type="number"
                               min="1"
                               placeholder="Ej.: 10"
                               required />
                    </div>

                    <div class="campo">
                        <label asp-for="motivo">Motivo</label>
                        <textarea asp-for="motivo"
                                  maxlength="150"
                                  placeholder="Ej.: vencimiento, envase dañado, pérdida de integridad..."
                                  required></textarea>
                    </div>

                </div></section>

                <aside class="resumen">
                    <h2 style="margin-top:0;font-size:19px;">Resumen</h2>

                    <div class="fila">
                        <span>Producto</span>
                        <strong id="rProducto">—</strong>
                    </div>

                    <div class="fila">
                        <span>Lote</span>
                        <strong id="rLote">—</strong>
                    </div>

                    <div class="fila">
                        <span>Bodega</span>
                        <strong id="rSector">—</strong>
                    </div>

                    <div class="fila">
                        <span>Vencimiento</span>
                        <strong id="rVence">—</strong>
                    </div>

                    <div class="fila">
                        <span>Stock disponible</span>
                        <strong id="rStock">—</strong>
                    </div>

                    <div class="fila">
                        <span>Baja</span>
                        <strong id="rCantidad">0</strong>
                    </div>
                </aside>

            </div>

            <div class="acciones">
                <a asp-controller="Home"
                   asp-action="MovimientoHistorial"
                   class="btn volver" data-orbit-action="secondary">Volver</a>

                <button type="submit"
                        id="btnBaja"
                        class="btn confirmar"
                        disabled data-orbit-action="danger">
                    Registrar baja
                </button>
            </div>
        </div>
    </form>
</section>

<script>
    const lote = document.getElementById("loteBaja");
    const cantidad = document.getElementById("cantidadBaja");
    const boton = document.getElementById("btnBaja");

    function actualizarBaja() {
        const op = lote.options[lote.selectedIndex];
        const stock = parseInt(op?.dataset?.stock || "0");
        const cant = parseInt(cantidad.value || "0");
        const unidad = op?.dataset?.unidad || "unidades";

        document.getElementById("rProducto").textContent = op?.dataset?.producto || "—";
        document.getElementById("rLote").textContent = op?.dataset?.lote || "—";
        document.getElementById("rSector").textContent = op?.dataset?.sector || "—";
        document.getElementById("rVence").textContent = op?.dataset?.vencimiento || "—";
        document.getElementById("rStock").textContent = lote.value ? `${stock} ${unidad}` : "—";
        document.getElementById("rCantidad").textContent = cant > 0 ? `${cant} ${unidad}` : `0 ${unidad}`;

        boton.disabled = !(lote.value && cant > 0 && cant <= stock);
    }

    lote.addEventListener("change", actualizarBaja);
    cantidad.addEventListener("input", actualizarBaja);

    document.getElementById("formBaja").addEventListener("submit", function(e) {
        if (!confirm("¿Confirma la baja definitiva de este stock?")) {
            e.preventDefault();
        }
    });

    actualizarBaja();
</script>

LoginSARMedix/Views/Home/Bienvenida.csht.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "Bienvenida"; ViewData["SmFamily"] = "home"; }
@{
    ViewData["Title"] = "Seleccione Módulo";

    ViewData["TituloBarra"] =
        "Seleccione Módulo";


    var permisos =
        ViewBag.Permisos as List<string>
        ?? new List<string>();



    bool permisoUsuarios =
        permisos.Any(
            p => p.Equals(
                "Crear usuario",
                StringComparison.OrdinalIgnoreCase
            )
        )
        ||
        permisos.Any(
            p => p.Equals(
                "Gestionar usuarios y permisos",
                StringComparison.OrdinalIgnoreCase
            )
        );



    bool permisoProductos =
        permisos.Any(
            p => p.Equals(
                "Consultar productos",
                StringComparison.OrdinalIgnoreCase
            )
        )
        ||
        permisos.Any(
            p => p.Equals(
                "Registrar productos",
                StringComparison.OrdinalIgnoreCase
            )
        )
        ||
        permisos.Any(
            p => p.Equals(
                "Gestionar productos",
                StringComparison.OrdinalIgnoreCase
            )
        );



    bool permisoMovimientos =
        permisos.Any(
            p => p.Equals(
                "Registrar movimientos",
                StringComparison.OrdinalIgnoreCase
            )
        )
        ||
        permisos.Any(
            p => p.Equals(
                "Consultar historial",
                StringComparison.OrdinalIgnoreCase
            )
        )
        ||
        permisos.Any(
            p => p.Equals(
                "Gestionar movimientos",
                StringComparison.OrdinalIgnoreCase
            )
        );



    bool permisoControlados =
        permisos.Any(
            p => p.Equals(
                "Gestionar medicamentos controlados",
                StringComparison.OrdinalIgnoreCase
            )
        );
}



<style>

    /* AJUSTE DE ESTA PANTALLA */

    main[role="main"] {
        padding:
            0 !important;

        justify-content:
            flex-start;

        align-items:
            stretch;
    }



    /* FONDO DE MODULOS */

    .pagina-modulos {
        width: 100%;

        min-height:
            calc(100vh - 144px);

        display: flex;

        flex-direction: column;

        background:
            #f1f5fb;
    }



    /* MENSAJE DE NAVEGACION */

    .contenedor-advertencia {
        width: 100%;

        display: flex;

        justify-content: center;

        position: relative;

        z-index: 20;
    }


    .mensaje-advertencia {
        width:
            calc(100% - 80px);

        max-width: 1160px;

        margin-top: 18px;

        padding:
            13px 18px;

        display: none;

        align-items: center;

        justify-content: center;

        gap: 11px;

        background:
            #fff3cd;

        border:
            1px solid
            #ffda6a;

        border-radius: 9px;

        color: #664d03;

        font-size: 15px;

        font-weight: 600;

        text-align: center;

        box-shadow:
            0 4px 12px
            rgba(120, 90, 0, 0.10);

        opacity: 1;

        transition:
            opacity 0.5s ease;
    }


    .advertencia-icono {
        width: 25px;

        height: 25px;

        flex-shrink: 0;

        display: flex;

        align-items: center;

        justify-content: center;

        border-radius: 50%;

        background:
            #ffc107;

        color:
            #5c4500;

        font-size: 16px;

        font-weight: 800;
    }



    /* CONTENIDO */

    .contenido-modulos {
        width: 100%;

        max-width: 1240px;

        margin:
            0 auto;

        padding:
            55px 40px 70px;

        flex: 1;
    }



    /* GRILLA */

    .modulos {
        display: grid;

        grid-template-columns:
            repeat(2, 1fr);

        gap: 34px;
    }



    /* TARJETAS */

    .modulo {
        position: relative;

        height: 300px;

        overflow: hidden;

        border-radius: 14px;

        background:
            white;

        box-shadow:
            0 7px 20px
            rgba(28, 65, 95, 0.13);

        transition:
            transform 0.22s ease,
            box-shadow 0.22s ease;

        text-decoration: none;

        color: inherit;
    }


    .modulo.habilitado:hover {
        transform:
            scale(1.035);

        box-shadow:
            0 15px 32px
            rgba(15, 91, 150, 0.25);

        z-index: 5;

        cursor: pointer;
    }


    .modulo-titulo {
        display: none;
    }



    /* IMAGENES */

    .modulo-imagen {
        position: relative;

        width: 100%;

        height: 100%;

        background-size:
            cover;

        background-position:
            center center;

        background-repeat:
            no-repeat;
    }


    .imagen-movimientos {
        background-position:
            center 78%;
    }


    .imagen-controlados {
        background-position:
            center 78%;
    }



    /* RESPONSIVE */

    @@media (max-width: 1200px) {

        .modulos {
            grid-template-columns:
                1fr;
        }


        .contenido-modulos {
            padding:
                35px 20px;
        }


        .modulo-imagen,
        .imagen-movimientos,
        .imagen-controlados {
            background-position:
                center top;
        }


        .mensaje-advertencia {
            width:
                calc(100% - 40px);
        }

    }



    @@media (max-width: 600px) {

        .contenido-modulos {
            padding:
                25px 15px;
        }


        .modulo {
            height: 230px;
        }


        .modulos {
            gap: 20px;
        }

    }

</style>



<div class="pagina-modulos">


    <!-- MENSAJE AL INTENTAR VOLVER -->

    <div class="contenedor-advertencia">


        <div id="mensajeNavegacion"
             class="mensaje-advertencia">


            <span class="advertencia-icono">

                !

            </span>


            <span>

                Debe cerrar sesión para volver
                a la pantalla de inicio de sesión.

            </span>


        </div>


    </div>



    <!-- MODULOS -->

    <section class="contenido-modulos">
        <div class="sm-intro-line">
            <span class="sm-eyebrow">TU ESPACIO DE TRABAJO</span>
            <span class="sm-context-label">Gestión farmacéutica / Inicio</span>
        </div>
        <section class="sm-hero" aria-labelledby="sm-welcome-title">
            <div class="sm-aurora" aria-hidden="true"><i></i><i></i><i></i></div>
            <div class="sm-hero-copy">
                <span class="sm-hero-label"><span></span> SARMedix · Conectados al cuidado</span>
                <h1 id="sm-welcome-title">Todo conectado.<br /><em>Mejor cuidado.</em></h1>
                <p>Personas, medicamentos y movimientos.<br />Un mismo espacio para cuidar cada detalle.</p>
                <div class="sm-hero-foot"><span class="sm-line"></span> Precisión en cada paso.</div>
                <div class="sm-principles" aria-label="Principios de SARMedix"><span>01 <strong>Conectar</strong></span><span>02 <strong>Controlar</strong></span><span>03 <strong>Cuidar</strong></span></div>
            </div>
            <partial name="_OrbitalMark" />
            <button class="sm-motion-toggle" type="button" aria-pressed="false" aria-label="Pausar efectos ambientales" data-orbit-action="secondary">Pausar efectos</button>
        </section>
        <div class="sm-section-heading"><div><span class="sm-eyebrow">EXPLORA SARMedix</span><h2>¿Por dónde empezamos?</h2></div><p>Selecciona un módulo para continuar.</p></div>


        <div class="modulos">



            <!-- USUARIOS Y PERMISOS -->

            @if (permisoUsuarios)
            {
                <a asp-controller="Home"
                   asp-action="UsuariosPermisos"
                   class="modulo habilitado sm-module-people" data-orbit-action="navigation">
                    <div class="sm-module-top" aria-hidden="true"><span class="sm-module-icon"><svg class="sm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#sm-icon-users" /></svg></span><span>01 / EQUIPO</span><span class="sm-module-arrow">↗</span></div>


                    <div class="modulo-titulo">

                        Usuarios y Permisos
                        <span class="sm-module-description">Personas y accesos, en perfecta sintonía.</span>

                    </div>


                    <div class="modulo-imagen"
                         style="
                            background-image:
                            url('/images/modulos/usuarios-permisos.jpg');
                         ">

                    </div>


                </a>
            }



            <!-- PRODUCTOS -->

            @if (permisoProductos)
            {
                <a asp-controller="Home"
                   asp-action="Productos"
                   class="modulo habilitado sm-module-products" data-orbit-action="navigation">
                    <div class="sm-module-top" aria-hidden="true"><span class="sm-module-icon"><svg class="sm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#sm-icon-products" /></svg></span><span>02 / EXISTENCIAS</span><span class="sm-module-arrow">↗</span></div>


                    <div class="modulo-titulo">

                        Productos
                        <span class="sm-module-description">Cada producto. Cada lote. Todo en su lugar.</span>

                    </div>


                    <div class="modulo-imagen"
                         style="
                            background-image:
                            url('/images/modulos/productos.jpg');
                         ">

                    </div>


                </a>
            }



            <!-- MOVIMIENTOS E HISTORIAL -->

            @if (permisoMovimientos)
            {
                <a asp-controller="Home"
                   asp-action="MovimientoHistorial"
                   class="modulo habilitado sm-module-movements" data-orbit-action="navigation">
                    <div class="sm-module-top" aria-hidden="true"><span class="sm-module-icon"><svg class="sm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#sm-icon-movements" /></svg></span><span>03 / TRAZABILIDAD</span><span class="sm-module-arrow">↗</span></div>


                    <div class="modulo-titulo">

                        Movimientos e Historial
                        <span class="sm-module-description">La historia completa de cada movimiento.</span>

                    </div>


                    <div class="
                        modulo-imagen
                        imagen-movimientos"
                         style="
                            background-image:
                            url('/images/modulos/movimientos.jpg');
                         ">

                    </div>


                </a>
            }



            <!-- MEDICAMENTOS CONTROLADOS -->

            @if (permisoControlados)
            {
                <a asp-controller="Home"
                   asp-action="MedicamentosControlados"
                   class="modulo habilitado sm-module-controlled" data-orbit-action="navigation">
                    <div class="sm-module-top" aria-hidden="true"><span class="sm-module-icon"><svg class="sm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#sm-icon-controlled" /></svg></span><span>04 / CONTROL</span><span class="sm-module-arrow">↗</span></div>


                    <div class="modulo-titulo">

                        Medicamentos Controlados
                        <span class="sm-module-description">Control dedicado para un cuidado preciso.</span>

                    </div>


                    <div class="
                        modulo-imagen
                        imagen-controlados"
                         style="
                            background-image:
                            url('/images/modulos/controlados.jpg');
                         ">

                    </div>


                </a>
            }


        </div>


        <div class="sm-workspace-note"><span aria-hidden="true">✧</span> Tu espacio se adapta a los permisos de tu perfil.</div>
    </section>


</div>



<script>

    let temporizadorAdvertencia;



    // MOSTRAR MENSAJE AMARILLO

    function mostrarAdvertenciaNavegacion() {

        const mensaje =
            document.getElementById(
                "mensajeNavegacion"
            );


        if (!mensaje) {

            return;

        }


        mensaje.style.display =
            "flex";


        mensaje.style.opacity =
            "1";


        clearTimeout(
            temporizadorAdvertencia
        );


        temporizadorAdvertencia =
            setTimeout(
                function () {

                    mensaje.style.opacity =
                        "0";


                    setTimeout(
                        function () {

                            mensaje.style.display =
                                "none";

                        },
                        500
                    );

                },
                4000
            );

    }



    // IMPEDIR VOLVER AL LOGIN

    history.pushState(
        null,
        "",
        window.location.href
    );


    window.addEventListener(
        "popstate",
        function () {

            history.pushState(
                null,
                "",
                window.location.href
            );


            mostrarAdvertenciaNavegacion();

        }
    );



    // CONTROL DE CACHE DEL NAVEGADOR

    window.addEventListener(
        "pageshow",
        function (evento) {

            if (evento.persisted) {

                window.location.reload();

            }

        }
    );

</script>

LoginSARMedix/Views/Home/CrearProducto.c.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "CrearProducto"; ViewData["SmFamily"] = "products"; }
@model LoginSARMedix.Models.Producto

@{
    ViewData["Title"] = "Registrar Producto";
    ViewData["TituloBarra"] = "Registrar Producto";

    string mensaje = ViewBag.Mensaje as string ?? "";

    bool mensajeExito =
        mensaje.Equals(
            "Producto registrado correctamente",
            StringComparison.OrdinalIgnoreCase
        );
}

<header class="orbit-editor-heading"><span class="orbit-eyebrow">ÓRBITA / CATÁLOGO</span><h1>Registrar producto</h1></header>

<form asp-controller="Home"
      asp-action="NuevoProducto"
      method="post"
      enctype="multipart/form-data"
      class="formulario-principal"
      id="formCrearProducto"
      onsubmit="return validarYConfirmar()"
      novalidate data-orbit-form="CrearProducto">

    <!-- MENSAJE -->
    <div class="espacio-mensaje">
        @if (!string.IsNullOrEmpty(mensaje))
        {
            if (mensajeExito)
            {
                <div class="mensaje mensaje-exito" id="mensajeFormulario">
                    @mensaje
                </div>
            }
            else
            {
                <div class="mensaje mensaje-error" id="mensajeFormulario">
                    @mensaje
                </div>
            }
        }
        else
        {
            <div class="mensaje mensaje-error mensaje-oculto"
                 id="mensajeFormulario">
            </div>
        }
    </div>


    <!-- TIPO -->
    <div class="orbit-product-grid"><fieldset class="orbit-product-identity"><legend>01 · Identificación y presentación</legend><div>
        <label for="tipoProducto">Tipo de producto</label>

        <select asp-for="tipo"
                id="tipoProducto"
                onchange="cambiarTipo()">
            <option value="">Seleccione</option>
            <option value="Medicamento">Medicamento</option>
            <option value="Insumo">Insumo</option>
        </select>
    </div>


    <!-- CODIGO INTERNO OCULTO -->
    <!-- SARMedix lo genera automáticamente. El usuario no necesita verlo. -->
    <input type="hidden"
           name="codigo_interno"
           id="codigoInterno"
           value="AUTO" />


    <!-- CODIGO DE BARRAS -->
    <div class="bloque-codigo-barras">
        <partial name="_OrbitScanner" />
        <div class="fila-codigo-barras">
            <label for="codigoBarras">Código de barras / GTIN</label>
            <span class="badge-codigo">ESCÁNER O MANUAL</span>
        </div>

        <input asp-for="codigo_barras"
               id="codigoBarras"
               autocomplete="off"
               placeholder="Escanee el código o escríbalo aquí" />

        <div class="ayuda-codigo">
            <span class="icono-codigo">▦</span>
            <span>
                <strong>Escanee con el lector</strong> o escriba el código manualmente.
                Si el producto no tiene código, puede dejar este campo vacío.
            </span>
        </div>

        <div id="estadoCodigoBarras"
             class="estado-codigo estado-codigo-oculto"
             aria-live="polite">
        </div>
    </div>


    <!-- NOMBRE -->
    <div>
        <label for="nombreProducto">Nombre</label>

        <input asp-for="nombre"
               id="nombreProducto"
               placeholder="Ej.: Tapsin" />
    </div>


    <!-- CAMPOS MEDICAMENTO -->
    <div id="camposMedicamento" style="display:none;">

        <div>
            <label for="formaFarmaceutica">Forma farmacéutica</label>

            <select asp-for="forma_farmaceutica"
                    id="formaFarmaceutica"
                    onchange="sugerirUnidadSegunForma()">
                <option value="">Seleccione</option>
                <option value="Comprimido">Comprimido</option>
                <option value="Comprimido recubierto">Comprimido recubierto</option>
                <option value="Cápsula">Cápsula</option>
                <option value="Solución oral">Solución oral</option>
                <option value="Jarabe">Jarabe</option>
                <option value="Ampolla">Ampolla</option>
                <option value="Gotas">Gotas</option>
                <option value="Crema">Crema</option>
                <option value="Inhalador">Inhalador</option>
                <option value="Supositorio">Supositorio</option>
                <option value="Sobre">Sobre</option>
                <option value="Otro">Otro</option>
            </select>
        </div>

        <div>
            <label for="principioActivo">Principio activo</label>

            <input asp-for="principio_activo"
                   id="principioActivo"
                   placeholder="Ej.: Dipirona + cafeína" />
        </div>

        <div>
            <label for="concentracion">Concentración</label>

            <input asp-for="concentracion"
                   id="concentracion"
                   placeholder="Ej.: 500 mg / 400 mg" />

            <small class="texto-ayuda">
                Aquí van los mg, g, mg/mL, etc. Ej.: 500 mg / 400 mg.
                La concentración NO indica cuántos comprimidos trae el envase.
            </small>
        </div>

        <div>
            <label for="requiereControl">¿Requiere control?</label>

            <select asp-for="requiere_control"
                    id="requiereControl">
                <option value="false">No</option>
                <option value="true">Sí</option>
            </select>
        </div>
    </div>


    <!-- CAMPOS INSUMO -->
    <div id="camposInsumo" style="display:none;">
        <div>
            <label for="material">Material</label>

            <input asp-for="material"
                   id="material" />
        </div>

        <div>
            <label for="esEsteril">¿Es estéril?</label>

            <select asp-for="es_esteril"
                    id="esEsteril">
                <option value="false">No</option>
                <option value="true">Sí</option>
            </select>
        </div>
    </div>


    <!-- CONTENIDO / STOCK -->
    </fieldset><fieldset class="orbit-product-content"><legend>02 · Contenido e inventario</legend><div class="seccion-inventario">
        <div class="seccion-inventario-titulo">Control de contenido y stock</div>
        <div class="seccion-inventario-subtitulo">
            Indique cuánto contiene el producto y en qué unidad se controlará.
        </div>

        <div>
            <label for="contenidoPorEnvase">Cantidad por envase</label>

            <input asp-for="contenido_por_envase"
                   id="contenidoPorEnvase"
                   type="number"
                   min="1"
                   placeholder="Ej.: 60"
                   oninput="actualizarResumenStock()" />

            <small class="texto-ayuda">
                Ejemplo: si la caja trae 60 comprimidos, escriba 60 y seleccione Comprimidos como unidad de inventario.
            </small>
        </div>

        <div>
            <label for="unidadMedidaReal">Unidad de inventario / contenido</label>

            <input asp-for="unidad_medida"
                   id="unidadMedidaReal"
                   type="hidden" />

            <select id="unidadSelector"
                    onchange="cambiarUnidad()">
                <option value="">Seleccione</option>

                <optgroup label="Unidades físicas">
                    <option value="Comprimidos">Comprimidos</option>
                    <option value="Cápsulas">Cápsulas</option>
                    <option value="Ampollas">Ampollas</option>
                    <option value="Sobres">Sobres</option>
                    <option value="Supositorios">Supositorios</option>
                    <option value="Inhaladores">Inhaladores</option>
                    <option value="Frascos">Frascos</option>
                    <option value="Unidades">Unidades</option>
                </optgroup>

                <optgroup label="Peso / volumen">
                    <option value="mg">mg</option>
                    <option value="g">g</option>
                    <option value="kg">kg</option>
                    <option value="mL">mL</option>
                    <option value="L">L</option>
                </optgroup>

                <option value="Otro">Otro</option>
                <option value="Omitir">Omitir</option>
            </select>

            <small class="texto-ayuda">
                Para comprimidos use <strong>Comprimidos</strong>.
                Los <strong>mg</strong> normalmente corresponden a la concentración; use mg/g aquí solo si el stock se controla físicamente por peso.
            </small>

            <div id="advertenciaUnidad"
                 class="ayuda-stock"
                 style="display:none; margin-top:8px;"></div>

            <div id="unidadOtroContenedor"
                 class="unidad-otro"
                 style="display:none;">
                <label for="unidadOtro">Especifique la unidad</label>

                <input id="unidadOtro"
                       type="text"
                       placeholder="Ej.: comprimidos, ampollas, sobres"
                       oninput="actualizarUnidadPersonalizada()" />
            </div>
        </div>

        <div class="bloque-stock-alerta">
            <label id="labelStockMinimo">Alerta de stock bajo</label>

            <input asp-for="stock_minimo"
                   id="stockMinimo"
                   type="number"
                   min="0"
                   oninput="actualizarResumenStock()" />

            <div class="ayuda-stock" id="ayudaStock">
                Seleccione una unidad para ver cómo se interpretará la alerta.
            </div>
        </div>
    </div>


    <!-- IMAGEN -->
    <div>
        <label for="imagenProducto">Imagen del producto</label>

        <input type="file"
               name="imagen"
               id="imagenProducto"
               accept="image/*" />

        <small class="texto-ayuda">Opcional.</small>
    </div>


    <br />

    </fieldset></div><div class="orbit-form-actions"><button type="submit"
            id="btnRegistrarProducto" data-orbit-action="primary">
        Registrar producto
    </button>
</div></form>


<div class="contenedor-volver">
    <a asp-controller="Home"
       asp-action="Productos"
       class="btn-volver-productos" data-orbit-action="secondary">
        ← Volver a Productos
    </a>
</div>


<!-- CONFIRMACION -->
<div id="modalConfirmacion" class="modal-fondo">
    <div class="modal-contenido" data-orbit-dialog="surface">
        <div class="modal-icono">?</div>

        <h2>Confirmar acción</h2>

        <p>¿Quieres registrar este producto?</p>

        <div class="modal-botones">
            <button type="button"
                    class="btn-modal-si"
                    onclick="registrarProducto()" data-orbit-action="primary">
                Sí
            </button>

            <button type="button"
                    class="btn-modal-no"
                    onclick="cerrarConfirmacion()" data-orbit-action="secondary">
                No
            </button>

            <button type="button"
                    class="btn-modal-cancelar"
                    onclick="cancelarRegistro()" data-orbit-action="secondary">
                Cancelar
            </button>
        </div>
    </div>
</div>


<style>
    .espacio-mensaje {
        min-height: 48px;
        margin-bottom: 8px;
    }

    .mensaje {
        width: 100%;
        padding: 12px 15px;
        border-radius: 7px;
        text-align: center;
        font-weight: 600;
        opacity: 1;
        transition: opacity 0.5s ease;
    }

    .mensaje-exito {
        background-color: #d1e7dd;
        color: #0f5132;
        border: 1px solid #badbcc;
    }

    .mensaje-error {
        background-color: #f8d7da;
        color: #842029;
        border: 1px solid #f5c2c7;
    }

    .mensaje-oculto {
        visibility: hidden;
    }

    .texto-ayuda {
        display: block;
        margin-top: 6px;
        color: #718592;
        font-size: 12px;
    }


    /* CODIGO DE BARRAS */
    .bloque-codigo-barras {
        padding: 14px;
        margin: 4px 0 16px 0;
        border: 1px solid #b8dbe4;
        border-radius: 10px;
        background-color: #f4fbfc;
    }

    .fila-codigo-barras {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 10px;
        flex-wrap: wrap;
    }

    .badge-codigo {
        padding: 4px 8px;
        border-radius: 999px;
        background-color: #d9f1f4;
        color: #0b6670;
        font-size: 10px;
        font-weight: 800;
        letter-spacing: .04em;
    }

    .bloque-codigo-barras input {
        margin-top: 5px;
    }

    .ayuda-codigo {
        display: flex;
        align-items: flex-start;
        gap: 8px;
        margin-top: 8px;
        color: #526d7c;
        font-size: 12px;
        line-height: 1.45;
    }

    .ayuda-codigo strong {
        color: #075f6b;
    }

    .estado-codigo {
        margin-top: 10px;
        padding: 11px 12px;
        border-radius: 8px;
        font-size: 12px;
        line-height: 1.45;
    }

    .estado-codigo-oculto {
        display: none;
    }

    .estado-codigo-verificando {
        display: block;
        background-color: #eef7fb;
        border: 1px solid #c5dfea;
        color: #315f75;
    }

    .estado-codigo-disponible {
        display: block;
        background-color: #e7f6ed;
        border: 1px solid #b8dec6;
        color: #17633a;
    }

    .estado-codigo-duplicado {
        display: block;
        background-color: #fff4df;
        border: 1px solid #efd09a;
        color: #7a5110;
    }

    .estado-codigo-titulo {
        display: block;
        margin-bottom: 2px;
        font-weight: 800;
    }

    .estado-codigo-accion {
        display: inline-block;
        margin-top: 8px;
        padding: 7px 11px;
        border-radius: 7px;
        background-color: #1198a5;
        color: white;
        text-decoration: none;
        font-weight: 700;
    }

    .estado-codigo-accion:hover {
        background-color: #0d8490;
        color: white;
    }

    #btnRegistrarProducto:disabled {
        opacity: .55;
        cursor: not-allowed;
    }

    .icono-codigo {
        color: #1198a5;
        font-size: 18px;
        line-height: 1;
    }


    /* CONTENIDO / STOCK */
    .seccion-inventario {
        margin-top: 18px;
        padding-top: 18px;
        border-top: 1px solid #dbe5ea;
    }

    .seccion-inventario-titulo {
        color: #003b64;
        font-size: 15px;
        font-weight: 700;
    }

    .seccion-inventario-subtitulo {
        margin: 3px 0 14px 0;
        color: #718592;
        font-size: 12px;
    }

    .unidad-otro {
        margin-top: 10px;
    }

    .ayuda-stock {
        margin-top: 8px;
        padding: 10px 12px;
        border-radius: 8px;
        background-color: #f3fafc;
        border: 1px solid #c9e5ec;
        color: #536c7b;
        font-size: 12px;
        line-height: 1.45;
    }

    .ayuda-stock strong {
        color: #0b5f7b;
    }


    /* VOLVER */
    .contenedor-volver {
        display: flex;
        justify-content: center;
        margin-top: 30px;
        margin-bottom: 30px;
    }

    .btn-volver-productos {
        display: inline-block;
        padding: 12px 22px;
        background-color: #1198a5;
        color: white;
        border-radius: 7px;
        text-decoration: none;
        font-weight: 600;
        transition: background-color 0.2s ease;
    }

    .btn-volver-productos:hover {
        background-color: #0d8490;
        color: white;
    }


    /* MODAL */
    .modal-fondo {
        display: none;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.45);
        align-items: center;
        justify-content: center;
        z-index: 9999;
    }

    .modal-contenido {
        width: 90%;
        max-width: 430px;
        background-color: white;
        border-radius: 15px;
        padding: 30px;
        text-align: center;
        box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25);
    }

    .modal-icono {
        width: 55px;
        height: 55px;
        margin: 0 auto 15px auto;
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: #1198a5;
        color: white;
        border-radius: 50%;
        font-size: 30px;
        font-weight: bold;
    }

    .modal-contenido h2 {
        margin-top: 0;
        color: #003b64;
    }

    .modal-contenido p {
        margin-top: 15px;
        margin-bottom: 25px;
        font-size: 17px;
        color: #444;
    }

    .modal-botones {
        display: flex;
        justify-content: center;
        gap: 10px;
        flex-wrap: wrap;
    }

    .modal-botones button {
        min-width: 90px;
        padding: 10px 18px;
        border: none;
        border-radius: 7px;
        color: white;
        font-weight: 600;
        cursor: pointer;
    }

    .btn-modal-si { background-color: #198754; }
    .btn-modal-si:hover { background-color: #157347; }
    .btn-modal-no { background-color: #c82333; }
    .btn-modal-no:hover { background-color: #a91d2a; }
    .btn-modal-cancelar { background-color: #59636b; }
    .btn-modal-cancelar:hover { background-color: #474f55; }
</style>


<script>
    let productoConfirmado = false;
    let codigoDuplicado = false;
    let temporizadorCodigo = null;


    function mostrarEstadoCodigo(clase, contenido) {
        const estado = document.getElementById("estadoCodigoBarras");

        estado.className = `estado-codigo ${clase}`;
        estado.innerHTML = contenido;
    }


    function limpiarEstadoCodigo() {
        const estado = document.getElementById("estadoCodigoBarras");

        estado.className = "estado-codigo estado-codigo-oculto";
        estado.innerHTML = "";

        codigoDuplicado = false;

        const boton = document.getElementById("btnRegistrarProducto");
        if (boton) {
            boton.disabled = false;
        }
    }


    async function verificarCodigoBarrasExistente() {
        const campo = document.getElementById("codigoBarras");
        const codigo = campo.value.trim();
        const boton = document.getElementById("btnRegistrarProducto");

        if (codigo === "") {
            limpiarEstadoCodigo();
            return false;
        }

        mostrarEstadoCodigo(
            "estado-codigo-verificando",
            "<strong>Verificando código...</strong>"
        );

        try {
            const url =
                '@Url.Action("BuscarProductoPorCodigoBarras", "Home")'
                + "?codigo="
                + encodeURIComponent(codigo);

            const respuesta = await fetch(url);

            if (!respuesta.ok) {
                limpiarEstadoCodigo();
                return false;
            }

            const datos = await respuesta.json();

            // El usuario puede haber cambiado el código mientras esperaba la respuesta.
            if (document.getElementById("codigoBarras").value.trim() !== codigo) {
                return false;
            }

            if (datos.existe && datos.producto) {
                codigoDuplicado = true;

                if (boton) {
                    boton.disabled = true;
                }

                const nombre = datos.producto.nombre ?? "Producto registrado";
                const principio = datos.producto.principio_activo ?? "";
                const concentracion = datos.producto.concentracion ?? "";

                let detalle = "";

                if (principio) {
                    detalle += `<br>${escaparHtmlCodigo(principio)}`;
                }

                if (concentracion) {
                    detalle += ` ${escaparHtmlCodigo(concentracion)}`;
                }

                mostrarEstadoCodigo(
                    "estado-codigo-duplicado",
                    `
                        <span class="estado-codigo-titulo">
                            ⚠ Este código ya está registrado
                        </span>
                        Ya pertenece a <strong>${escaparHtmlCodigo(nombre)}</strong>${detalle}.
                        <br>No es necesario crear otro producto con el mismo código.
                        <br>
                        <a class="estado-codigo-accion"
                           href="@Url.Action("CrearLote", "Home")">
                            Ir a Registrar entrada
                        </a>
                    `
                );

                return true;
            }

            codigoDuplicado = false;

            if (boton) {
                boton.disabled = false;
            }

            mostrarEstadoCodigo(
                "estado-codigo-disponible",
                `
                    <span class="estado-codigo-titulo">
                        ✓ Código disponible
                    </span>
                    Este código no está asociado a otro producto.
                `
            );

            return false;
        }
        catch {
            // Si la consulta falla, no bloqueamos el formulario.
            // El repositorio seguirá validando duplicados al guardar.
            limpiarEstadoCodigo();
            return false;
        }
    }


    function programarVerificacionCodigo() {
        clearTimeout(temporizadorCodigo);

        temporizadorCodigo = setTimeout(
            verificarCodigoBarrasExistente,
            350
        );
    }


    function escaparHtmlCodigo(valor) {
        return String(valor ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    function cambiarTipo() {
        const tipo = document.getElementById("tipoProducto").value;
        const medicamento = document.getElementById("camposMedicamento");
        const insumo = document.getElementById("camposInsumo");

        medicamento.style.display =
            tipo === "Medicamento" ? "block" : "none";

        insumo.style.display =
            tipo === "Insumo" ? "block" : "none";
    }


    function sugerirUnidadSegunForma() {
        const forma = document.getElementById("formaFarmaceutica");
        const selector = document.getElementById("unidadSelector");

        if (!forma || !selector) {
            return;
        }

        const sugerencias = {
            "Comprimido": "Comprimidos",
            "Comprimido recubierto": "Comprimidos",
            "Cápsula": "Cápsulas",
            "Ampolla": "Ampollas",
            "Sobre": "Sobres",
            "Supositorio": "Supositorios",
            "Inhalador": "Inhaladores",
            "Solución oral": "mL",
            "Jarabe": "mL",
            "Gotas": "mL",
            "Crema": "g"
        };

        const sugerida = sugerencias[forma.value];

        if (sugerida) {
            selector.value = sugerida;
            cambiarUnidad();
        }
    }


    function cambiarUnidad() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const contenedorOtro = document.getElementById("unidadOtroContenedor");
        const otro = document.getElementById("unidadOtro");

        if (selector.value === "Otro") {
            contenedorOtro.style.display = "block";
            real.value = otro.value.trim();
        }
        else if (selector.value === "Omitir") {
            contenedorOtro.style.display = "none";
            otro.value = "";
            real.value = "";
        }
        else {
            contenedorOtro.style.display = "none";
            otro.value = "";
            real.value = selector.value;
        }

        actualizarResumenStock();
    }


    function actualizarUnidadPersonalizada() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const otro = document.getElementById("unidadOtro");

        if (selector.value === "Otro") {
            real.value = otro.value.trim();
        }

        actualizarResumenStock();
    }


    function actualizarResumenStock() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const stock = document.getElementById("stockMinimo");
        const label = document.getElementById("labelStockMinimo");
        const ayuda = document.getElementById("ayudaStock");

        const unidad = real.value.trim();
        const minimo = stock.value.trim();
        const advertencia = document.getElementById("advertenciaUnidad");
        const forma = document.getElementById("formaFarmaceutica");

        if (advertencia) {
            advertencia.style.display = "none";
            advertencia.innerHTML = "";

            const esComprimido =
                forma
                && (forma.value === "Comprimido" || forma.value === "Comprimido recubierto");

            if (esComprimido && ["mg", "g", "kg"].includes(unidad)) {
                advertencia.style.display = "block";
                advertencia.innerHTML =
                    "⚠ Para un medicamento en comprimidos normalmente la unidad de inventario debe ser <strong>Comprimidos</strong>. "
                    + "Los mg/g deben registrarse arriba en <strong>Concentración</strong>, salvo que realmente controle el stock por peso.";
            }
        }

        if (selector.value === "Omitir") {
            label.innerText = "Alerta de stock bajo";

            ayuda.innerHTML =
                minimo !== ""
                    ? `SARMedix avisará cuando el stock llegue a <strong>${minimo}</strong> o menos.`
                    : "Indique desde qué cantidad desea recibir una alerta de stock bajo.";

            return;
        }

        if (unidad === "") {
            label.innerText = "Alerta de stock bajo";
            ayuda.innerText =
                "Seleccione una unidad para ver cómo se interpretará la alerta.";
            return;
        }

        label.innerText = `Alerta de stock bajo (${unidad})`;

        ayuda.innerHTML =
            minimo !== ""
                ? `SARMedix avisará cuando queden <strong>${minimo} ${unidad}</strong> o menos.`
                : `La alerta se medirá en <strong>${unidad}</strong>.`;
    }


    function mostrarError(texto, campo) {
        const mensaje = document.getElementById("mensajeFormulario");

        mensaje.innerText = texto;
        mensaje.className = "mensaje mensaje-error";
        mensaje.style.visibility = "visible";
        mensaje.style.opacity = "1";

        campo.focus();
    }


    function validarYConfirmar() {
        if (productoConfirmado) {
            return true;
        }

        const tipo = document.getElementById("tipoProducto");
        const nombre = document.getElementById("nombreProducto");
        const contenido = document.getElementById("contenidoPorEnvase");
        const unidadSelector = document.getElementById("unidadSelector");
        const unidadOtro = document.getElementById("unidadOtro");
        const stock = document.getElementById("stockMinimo");
        const codigoBarras = document.getElementById("codigoBarras");

        if (codigoDuplicado) {
            mostrarError(
                "Este código de barras ya pertenece a un producto registrado.",
                codigoBarras
            );
            return false;
        }

        if (tipo.value === "") {
            mostrarError("Debe seleccionar el tipo de producto.", tipo);
            return false;
        }

        if (nombre.value.trim() === "") {
            mostrarError("Debe ingresar el nombre del producto.", nombre);
            return false;
        }

        if (tipo.value === "Medicamento") {
            const forma = document.getElementById("formaFarmaceutica");
            const principio = document.getElementById("principioActivo");
            const concentracion = document.getElementById("concentracion");

            if (forma.value === "") {
                mostrarError("Debe seleccionar la forma farmacéutica.", forma);
                return false;
            }

            if (principio.value.trim() === "") {
                mostrarError("Debe ingresar el principio activo.", principio);
                return false;
            }

            if (concentracion.value.trim() === "") {
                mostrarError("Debe ingresar la concentración.", concentracion);
                return false;
            }
        }

        if (tipo.value === "Insumo") {
            const material = document.getElementById("material");

            if (material.value.trim() === "") {
                mostrarError("Debe ingresar el material.", material);
                return false;
            }
        }

        if (
            contenido.value.trim() === ""
            || Number(contenido.value) <= 0
        ) {
            mostrarError(
                "La cantidad contenida debe ser mayor a 0.",
                contenido
            );
            return false;
        }

        if (unidadSelector.value === "") {
            mostrarError(
                "Seleccione una unidad de inventario o elija Omitir.",
                unidadSelector
            );
            return false;
        }

        if (
            unidadSelector.value === "Otro"
            && unidadOtro.value.trim() === ""
        ) {
            mostrarError(
                "Especifique la unidad de inventario.",
                unidadOtro
            );
            return false;
        }

        if (
            stock.value.trim() === ""
            || Number(stock.value) < 0
        ) {
            mostrarError(
                "Debe ingresar una cantidad válida para la alerta de stock bajo.",
                stock
            );
            return false;
        }

        document.getElementById("modalConfirmacion").style.display = "flex";
        return false;
    }


    function registrarProducto() {
        productoConfirmado = true;
        document.getElementById("modalConfirmacion").style.display = "none";
        document.getElementById("formCrearProducto").requestSubmit();
    }


    function cerrarConfirmacion() {
        productoConfirmado = false;
        document.getElementById("modalConfirmacion").style.display = "none";
    }


    function cancelarRegistro() {
        productoConfirmado = false;
        document.getElementById("modalConfirmacion").style.display = "none";
        document.getElementById("formCrearProducto").reset();
        document.getElementById("codigoInterno").value = "AUTO";
        document.getElementById("unidadMedidaReal").value = "";
        document.getElementById("unidadOtroContenedor").style.display = "none";
        limpiarEstadoCodigo();
        cambiarTipo();
        actualizarResumenStock();

        const mensaje = document.getElementById("mensajeFormulario");
        mensaje.innerText = "";
        mensaje.className = "mensaje mensaje-error mensaje-oculto";
        mensaje.style.visibility = "hidden";
        mensaje.style.opacity = "1";

        document.getElementById("tipoProducto").focus();
    }


    document.addEventListener("DOMContentLoaded", function () {
        cambiarTipo();

        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const otro = document.getElementById("unidadOtro");
        const contenedorOtro = document.getElementById("unidadOtroContenedor");
        const valorGuardado = real.value.trim();

        const opciones = [
            "Comprimidos",
            "Cápsulas",
            "Ampollas",
            "Sobres",
            "Supositorios",
            "Inhaladores",
            "Frascos",
            "Unidades",
            "mg",
            "g",
            "kg",
            "mL",
            "L"
        ];

        if (valorGuardado === "") {
            selector.value = "";
        }
        else if (opciones.includes(valorGuardado)) {
            selector.value = valorGuardado;
        }
        else {
            selector.value = "Otro";
            otro.value = valorGuardado;
            contenedorOtro.style.display = "block";
        }

        actualizarResumenStock();

        const codigo = document.getElementById("codigoBarras");

        if (codigo) {
            codigo.addEventListener("input", function () {
                codigoDuplicado = false;

                const boton = document.getElementById("btnRegistrarProducto");
                if (boton) {
                    boton.disabled = false;
                }

                if (codigo.value.trim() === "") {
                    limpiarEstadoCodigo();
                    return;
                }

                programarVerificacionCodigo();
            });

            codigo.addEventListener("blur", function () {
                verificarCodigoBarrasExistente();
            });

            codigo.addEventListener("keydown", function (evento) {
                if (evento.key === "Enter") {
                    evento.preventDefault();
                    verificarCodigoBarrasExistente();
                }
            });

            if (codigo.value.trim() !== "") {
                verificarCodigoBarrasExistente();
                codigo.focus();
                codigo.select();
            }
            else {
                codigo.focus();
            }
        }
    });


    setTimeout(function () {
        const mensaje = document.getElementById("mensajeFormulario");

        if (
            mensaje
            && !mensaje.classList.contains("mensaje-oculto")
        ) {
            mensaje.style.opacity = "0";

            setTimeout(function () {
                mensaje.style.visibility = "hidden";
            }, 500);
        }
    }, 3000);
</script>

LoginSARMedix/Views/Home/CrearRol.cshtml.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "CrearRol"; ViewData["SmFamily"] = "users"; }
@model LoginSARMedix.Models.Rol

@{
    ViewData["Title"] = "Crear Rol";
    ViewData["TituloBarra"] = "Crear Rol";
}


<section class="contenedor-crear-rol">

    <h1 class="titulo-crear-rol">
        Crear Nuevo Rol
    </h1>

    <p class="descripcion-crear-rol">
        Ingrese los datos del nuevo rol para registrarlo en SARMedix.
    </p>


    <div class="tarjeta-crear-rol">

        <!-- MENSAJE -->

        <div class="espacio-mensaje">

            @if (ViewBag.Mensaje != null)
            {
                <div class="mensaje-error"
                     id="mensajeRol">

                    <span class="mensaje-icono">
                        !
                    </span>

                    <span id="textoMensajeRol">
                        @ViewBag.Mensaje
                    </span>

                </div>
            }
            else
            {
                <div class="mensaje-error mensaje-oculto"
                     id="mensajeRol">

                    <span class="mensaje-icono">
                        !
                    </span>

                    <span id="textoMensajeRol">
                    </span>

                </div>
            }

        </div>


        <!-- FORMULARIO -->

        <form asp-controller="Home"
              asp-action="NuevoRol"
              method="post"
              id="formCrearRol"
              onsubmit="return validarYConfirmarRol()"
              novalidate data-orbit-form="CrearRol">

            <fieldset class="orbit-role-fields"><legend>Definición del rol</legend><div class="grupo-rol">

                <label asp-for="nombre">
                    Nombre del rol
                </label>

                <input asp-for="nombre"
                       id="nombreRol"
                       placeholder="Ej: Encargado de Farmacia" />

            </div>


            <div class="grupo-rol">

                <label asp-for="descripcion">
                    Descripción
                </label>

                <textarea asp-for="descripcion"
                          id="descripcionRol"
                          placeholder="Ingrese una descripción de las funciones del rol"></textarea>

            </div>


            </fieldset><button type="submit"
                    class="btn-guardar-rol" data-orbit-action="primary">

                Crear rol

            </button>

        </form>

    </div>


    <!-- VOLVER -->

    <div class="volver-rol">

        <a asp-controller="Home"
           asp-action="RolesPermisos"
           class="btn-volver-rol" data-orbit-action="secondary">

            ← Volver a Roles y Permisos

        </a>

    </div>

</section>



<!-- CONFIRMACION -->

<div id="modalConfirmacion"
     class="modal-fondo">

    <div class="modal-contenido" data-orbit-dialog="surface">

        <div class="modal-icono">
            ?
        </div>

        <div class="modal-titulo">
            Confirmar acción
        </div>

        <p>
            ¿Quieres crear este rol?
        </p>

        <div class="modal-botones">

            <button type="button"
                    class="btn-modal-si"
                    onclick="crearRol()" data-orbit-action="primary">

                Sí

            </button>

            <button type="button"
                    class="btn-modal-no"
                    onclick="cerrarConfirmacionRol()" data-orbit-action="secondary">

                No

            </button>

            <button type="button"
                    class="btn-modal-cancelar"
                    onclick="cancelarCreacionRol()" data-orbit-action="secondary">

                Cancelar

            </button>

        </div>

    </div>

</div>



<style>

    /* CONTENIDO */

    .contenedor-crear-rol {
        width: 90%;
        max-width: 650px;
        margin: 5px auto;
    }


    .titulo-crear-rol {
        margin-bottom: 8px;
        text-align: center;
        color: #087bc2;
        font-size: 32px;
        font-weight: 700;
    }


    .descripcion-crear-rol {
        margin-bottom: 30px;
        text-align: center;
        color: #687b89;
        font-size: 16px;
    }



    /* TARJETA */

    .tarjeta-crear-rol {
        padding: 35px;
        background: rgba(255, 255, 255, 0.96);
        border-radius: 14px;
        box-shadow: 0 7px 20px rgba(28, 65, 95, 0.15);
    }



    /* FORMULARIO */

    #formCrearRol {
        width: 100%;
        max-width: none;
        margin: 0;
        padding: 0;
        background: transparent;
        box-shadow: none;
    }


    .grupo-rol {
        margin-bottom: 22px;
    }


    .grupo-rol label {
        display: block;
        margin-bottom: 8px;
        color: #17324d;
        font-weight: 600;
    }


    .grupo-rol input,
    .grupo-rol textarea {
        width: 100%;
        padding: 12px;
        border: 1px solid #b9cbd7;
        border-radius: 7px;
        background: white;
        color: #17324d;
        font-family: inherit;
        font-size: 15px;
    }


    .grupo-rol input:focus,
    .grupo-rol textarea:focus {
        outline: none;
        border-color: #087bc2;
        box-shadow: 0 0 0 3px rgba(8, 123, 194, 0.10);
    }


    .grupo-rol textarea {
        min-height: 120px;
        resize: vertical;
    }



    /* MENSAJE */

    .espacio-mensaje {
        min-height: 58px;
        margin-bottom: 15px;
    }


    .mensaje-error {
        padding: 14px 18px;
        display: flex;
        align-items: center;
        gap: 12px;
        background: #fdecec;
        border: 1px solid #e5aaaa;
        color: #a12828;
        border-radius: 9px;
        font-size: 15px;
        font-weight: 600;
        opacity: 1;
    }


    .mensaje-oculto {
        visibility: hidden;
    }


    .mensaje-icono {
        width: 28px;
        height: 28px;
        min-width: 28px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        background: #a12828;
        color: white;
        font-weight: bold;
    }



    /* BOTON CREAR */

    .btn-guardar-rol {
        width: 100%;
        padding: 13px;
        background: #0b8f9c;
        color: white;
        border: none;
        border-radius: 7px;
        font-size: 15px;
        font-weight: 600;
        cursor: pointer;
        transition:
            background 0.2s ease,
            transform 0.2s ease;
    }


    .btn-guardar-rol:hover {
        background: #087580;
        transform: translateY(-2px);
    }



    /* VOLVER */

    .volver-rol {
        margin-top: 30px;
        text-align: center;
    }


    .btn-volver-rol {
        display: inline-block;
        padding: 11px 20px;
        background: #0b8f9c;
        color: white;
        text-decoration: none;
        border-radius: 7px;
        font-weight: 600;
    }


    .btn-volver-rol:hover {
        background: #087580;
        color: white;
    }



    /* MODAL */

    .modal-fondo {
        display: none;
        position: fixed;
        inset: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.45);
        align-items: center;
        justify-content: center;
        z-index: 99999;
    }


    .modal-contenido {
        width: 90%;
        max-width: 430px;
        padding: 30px;
        background: white;
        border-radius: 15px;
        text-align: center;
        box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25);
    }


    .modal-icono {
        width: 55px;
        height: 55px;
        margin: 0 auto 15px auto;
        display: flex;
        align-items: center;
        justify-content: center;
        background: #1198a5;
        color: white;
        border-radius: 50%;
        font-size: 30px;
        font-weight: bold;
    }


    .modal-titulo {
        margin: 0;
        color: #003b64;
        font-size: 25px;
        font-weight: 700;
    }


    .modal-contenido p {
        margin-top: 15px;
        margin-bottom: 25px;
        color: #444;
        font-size: 17px;
    }


    .modal-botones {
        display: flex;
        justify-content: center;
        gap: 10px;
        flex-wrap: wrap;
    }


    .modal-botones button {
        width: auto !important;
        min-width: 90px;
        margin: 0 !important;
        padding: 10px 18px !important;
        border: none !important;
        border-radius: 7px !important;
        color: white !important;
        font-weight: 600;
        cursor: pointer;
    }


    .btn-modal-si {
        background: #198754 !important;
    }


    .btn-modal-si:hover {
        background: #157347 !important;
    }


    .btn-modal-no {
        background: #c82333 !important;
    }


    .btn-modal-no:hover {
        background: #a91d2a !important;
    }


    .btn-modal-cancelar {
        background: #59636b !important;
    }


    .btn-modal-cancelar:hover {
        background: #474f55 !important;
    }



    /* RESPONSIVE */

    @@media (max-width: 600px) {

        .contenedor-crear-rol {
            width: 94%;
        }

        .tarjeta-crear-rol {
            padding: 24px;
        }

        .modal-botones {
            flex-direction: column;
        }

        .modal-botones button {
            width: 100% !important;
        }
    }

</style>



<script>

    let rolConfirmado = false;


    // MOSTRAR ERROR

    function mostrarErrorRol(texto, campo) {

        const mensaje =
            document.getElementById("mensajeRol");

        const textoMensaje =
            document.getElementById("textoMensajeRol");


        textoMensaje.innerText = texto;

        mensaje.className =
            "mensaje-error";

        mensaje.style.visibility =
            "visible";

        mensaje.style.opacity =
            "1";

        campo.focus();
    }



    // VALIDAR CAMPOS

    function validarYConfirmarRol() {

        if (rolConfirmado) {
            return true;
        }


        const nombre =
            document.getElementById("nombreRol");

        const descripcion =
            document.getElementById("descripcionRol");


        if (nombre.value.trim() === "") {

            mostrarErrorRol(
                "Debe ingresar el nombre del rol.",
                nombre
            );

            return false;
        }


        if (descripcion.value.trim() === "") {

            mostrarErrorRol(
                "Debe ingresar una descripción.",
                descripcion
            );

            return false;
        }


        document.getElementById(
            "modalConfirmacion"
        ).style.display = "flex";


        return false;
    }



    // BOTON SI

    function crearRol() {

        rolConfirmado = true;

        document.getElementById(
            "modalConfirmacion"
        ).style.display = "none";


        document.getElementById(
            "formCrearRol"
        ).requestSubmit();
    }



    // BOTON NO

    function cerrarConfirmacionRol() {

        rolConfirmado = false;

        document.getElementById(
            "modalConfirmacion"
        ).style.display = "none";
    }



    // BOTON CANCELAR

    function cancelarCreacionRol() {

        rolConfirmado = false;


        document.getElementById(
            "modalConfirmacion"
        ).style.display = "none";


        document.getElementById(
            "nombreRol"
        ).value = "";


        document.getElementById(
            "descripcionRol"
        ).value = "";


        const mensaje =
            document.getElementById(
                "mensajeRol"
            );


        const textoMensaje =
            document.getElementById(
                "textoMensajeRol"
            );


        textoMensaje.innerText = "";


        mensaje.className =
            "mensaje-error mensaje-oculto";


        mensaje.style.visibility =
            "hidden";


        mensaje.style.opacity =
            "1";


        document.getElementById(
            "nombreRol"
        ).focus();
    }

</script>

LoginSARMedix/Views/Home/CrearUsuario.cs.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "CrearUsuario"; ViewData["SmFamily"] = "users"; }
@model LoginSARMedix.Models.Usuario

@{
    ViewData["TituloBarra"] = "Crear Usuario";
}

<header class="orbit-editor-heading"><span class="orbit-eyebrow">ÓRBITA / PERSONAS</span><h1>Ingrese los datos del nuevo usuario</h1></header>

<form asp-controller="Home"
      asp-action="NuevoUsuario"
      method="post"
      class="formulario-principal"
      id="formCrearUsuario"
      novalidate data-orbit-form="CrearUsuario">

    <div class="espacio-mensaje">
        @if (TempData["Mensaje"] != null)
        {
            <div class="mensaje mensaje-exito" id="mensajeFormulario">
                @TempData["Mensaje"]
            </div>
        }
        else if (ViewBag.Mensaje != null)
        {
            <div class="mensaje mensaje-error" id="mensajeFormulario">
                @ViewBag.Mensaje
            </div>
        }
        else
        {
            <div class="mensaje mensaje-error mensaje-oculto"
                 id="mensajeFormulario"></div>
        }
    </div>

    <div class="orbit-identity-grid"><fieldset><legend>01 · Identidad personal</legend><div class="grupo-campo">
        <label for="nombre">Nombre</label>
        <input asp-for="nombre"
               id="nombre"
               autocomplete="off" />
    </div>

    <div class="grupo-campo">
        <label for="apellido">Apellido</label>
        <input asp-for="apellido"
               id="apellido"
               autocomplete="off" />
    </div>

    <div class="grupo-campo">
        <label for="email">Correo electrónico</label>

        <input asp-for="email"
               id="email"
               type="email"
               autocomplete="off" />

        <div id="estadoEmail"
             class="validacion-caliente"
             aria-live="polite">
        </div>
    </div>

    <div class="grupo-campo">
        <label for="rut">RUT</label>

        <input asp-for="rut"
               id="rut"
               maxlength="10"
               autocomplete="off" />

        <div id="estadoRut"
             class="validacion-caliente"
             aria-live="polite">
        </div>
    </div>

    </fieldset><fieldset class="orbit-credentials"><legend>02 · Perfil de acceso</legend><div class="grupo-campo">
        <label for="id_rol">Rol</label>

        <select asp-for="id_rol"
                id="id_rol">

            <option value="">
                Seleccione un rol
            </option>

            <option value="1">
                Administrador
            </option>

            <option value="2">
                TENS
            </option>

            <option value="3">
                Enfermera
            </option>

            <option value="4">
                Auxiliar
            </option>

        </select>
    </div>

    <div class="grupo-campo">
        <label for="nombre_usuario">
            Nombre de usuario
        </label>

        <input asp-for="nombre_usuario"
               id="nombre_usuario"
               autocomplete="off" />

        <div id="estadoNombreUsuario"
             class="validacion-caliente"
             aria-live="polite">
        </div>
    </div>

    <div class="grupo-campo">
        <label for="contrasena">
            Contraseña
        </label>

        <input asp-for="contrasena"
               id="contrasena"
               type="password"
               autocomplete="new-password" />
    </div>

    <br />

    </fieldset></div><div class="orbit-form-actions"><button type="submit" data-orbit-action="primary">
        Crear usuario
    </button>

</div></form>


<div class="contenedor-volver">

    <a asp-controller="Home"
       asp-action="UsuariosPermisos"
       class="btn-volver-usuarios" data-orbit-action="secondary">

        ← Volver a Usuarios y Permisos

    </a>

</div>


<!-- =============================================================
     MODAL DE CONFIRMACION
     ============================================================= -->

<div id="modalConfirmacion"
     class="modal-fondo">

    <div class="modal-contenido" data-orbit-dialog="surface">

        <div class="modal-icono">
            ?
        </div>

        <h2>
            Confirmar acción
        </h2>

        <p>
            ¿Quieres crear este usuario?
        </p>

        <div class="modal-botones">

            <button type="button"
                    class="btn-modal-si"
                    onclick="crearUsuario()" data-orbit-action="primary">

                Sí

            </button>

            <button type="button"
                    class="btn-modal-no"
                    onclick="cerrarConfirmacion()" data-orbit-action="secondary">

                No

            </button>

            <button type="button"
                    class="btn-modal-cancelar"
                    onclick="cancelarCreacion()" data-orbit-action="secondary">

                Cancelar

            </button>

        </div>

    </div>

</div>


<style>

    /* =========================================================
           MENSAJES
           ========================================================= */

    .espacio-mensaje {
        min-height: 48px;
        margin-bottom: 8px;
    }


    .mensaje {
        width: 100%;
        padding: 12px 15px;
        border-radius: 7px;
        text-align: center;
        font-weight: 600;
        opacity: 1;
        transition: opacity 0.5s ease;
        box-sizing: border-box;
    }


    .mensaje-exito {
        background-color: #d1e7dd;
        color: #0f5132;
        border: 1px solid #badbcc;
    }


    .mensaje-error {
        background-color: #f8d7da;
        color: #842029;
        border: 1px solid #f5c2c7;
    }


    .mensaje-oculto {
        visibility: hidden;
    }



    /* =========================================================
           CAMPOS
           ========================================================= */

    .grupo-campo {
        width: 100%;
        margin-bottom: 18px;
    }


        .grupo-campo label {
            display: block;
            margin-bottom: 8px;
            font-weight: 600;
        }


    .formulario-principal input,
    .formulario-principal select {
        width: 100%;
        height: 54px;
        padding: 0 16px;
        border: 1px solid #b8cfe0;
        border-radius: 10px;
        font-size: 16px;
        background-color: white;
        box-sizing: border-box;
        outline: none;
    }


        .formulario-principal input:focus,
        .formulario-principal select:focus {
            border-color: #1198a5;
            box-shadow: 0 0 0 3px rgba( 17, 152, 165, 0.15 );
        }



    /* =========================================================
           VALIDACION EN CALIENTE
           ========================================================= */

    .validacion-caliente {
        min-height: 22px;
        margin-top: 7px;
        display: flex;
        align-items: center;
        gap: 7px;
        color: #73838c;
        font-size: 13px;
        font-weight: 600;
        line-height: 1.35;
    }


        .validacion-caliente:empty {
            min-height: 0;
            margin-top: 0;
        }


    .validacion-verificando {
        color: #627985;
    }


    .validacion-correcta {
        color: #198754;
    }


    .validacion-error {
        color: #b42318;
    }


    .validacion-incompleta {
        color: #7a8991;
    }



    /* =========================================================
           SPINNER
           =========================================================
           La animacion se hace directamente mediante SVG.
           Así evitamos usar reglas CSS especiales que Razor
           podría intentar interpretar.
           ========================================================= */

    .validacion-spinner {
        width: 16px;
        height: 16px;
        min-width: 16px;
        display: inline-block;
    }



    /* =========================================================
           ICONOS OK / ERROR
           ========================================================= */

    .validacion-icono-ok,
    .validacion-icono-error {
        width: 17px;
        height: 17px;
        min-width: 17px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        color: white;
        font-size: 11px;
        font-weight: 800;
        line-height: 1;
    }


    .validacion-icono-ok {
        background-color: #198754;
    }


    .validacion-icono-error {
        background-color: #dc3545;
    }



    /* =========================================================
           CAMPO DISPONIBLE
           ========================================================= */

    .formulario-principal
    input.campo-disponible {
        border-color: #55b984;
        background-color: #fbfffc;
        box-shadow: 0 0 0 3px rgba( 25, 135, 84, 0.08 );
    }



    /* =========================================================
           CAMPO NO DISPONIBLE
           ========================================================= */

    .formulario-principal
    input.campo-no-disponible {
        border-color: #dc3545;
        background-color: #fff8f8;
        box-shadow: 0 0 0 3px rgba( 220, 53, 69, 0.10 );
    }



    /* =========================================================
           BOTON CREAR
           ========================================================= */

    .formulario-principal
    button[type="submit"] {
        width: 100%;
        min-height: 48px;
        border: none;
        border-radius: 8px;
        background-color: #1198a5;
        color: white;
        font-size: 16px;
        font-weight: 600;
        cursor: pointer;
    }


        .formulario-principal
        button[type="submit"]:hover {
            background-color: #0d8490;
        }



    /* =========================================================
           VOLVER
           ========================================================= */

    .contenedor-volver {
        display: flex;
        justify-content: center;
        margin-top: 30px;
        margin-bottom: 30px;
    }


    .btn-volver-usuarios {
        display: inline-block;
        padding: 12px 22px;
        background-color: #1198a5;
        color: white;
        border-radius: 7px;
        text-decoration: none;
        font-weight: 600;
    }


        .btn-volver-usuarios:hover {
            background-color: #0d8490;
            color: white;
        }



    /* =========================================================
           MODAL
           ========================================================= */

    .modal-fondo {
        display: none;
        position: fixed;
        inset: 0;
        background-color: rgba( 0, 0, 0, 0.45 );
        align-items: center;
        justify-content: center;
        z-index: 9999;
    }


    .modal-contenido {
        width: 90%;
        max-width: 430px;
        padding: 30px;
        background-color: white;
        border-radius: 15px;
        text-align: center;
        box-shadow: 0 12px 35px rgba( 0, 0, 0, 0.25 );
    }


    .modal-icono {
        width: 55px;
        height: 55px;
        margin: 0 auto 15px auto;
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: #1198a5;
        color: white;
        border-radius: 50%;
        font-size: 30px;
        font-weight: bold;
    }


    .modal-contenido h2 {
        margin-top: 0;
        color: #003b64;
    }


    .modal-contenido p {
        margin-top: 15px;
        margin-bottom: 25px;
        font-size: 17px;
        color: #444;
    }


    .modal-botones {
        display: flex;
        justify-content: center;
        gap: 10px;
        flex-wrap: wrap;
    }


        .modal-botones button {
            min-width: 90px;
            padding: 10px 18px;
            border: none;
            border-radius: 7px;
            color: white;
            font-weight: 600;
            cursor: pointer;
        }


    .btn-modal-si {
        background-color: #198754;
    }


        .btn-modal-si:hover {
            background-color: #157347;
        }


    .btn-modal-no {
        background-color: #c82333;
    }


        .btn-modal-no:hover {
            background-color: #a91d2a;
        }


    .btn-modal-cancelar {
        background-color: #59636b;
    }


        .btn-modal-cancelar:hover {
            background-color: #474f55;
        }

</style>


<script>

    // =========================================================
    // ESTADO GENERAL
    // =========================================================

    let usuarioConfirmado =
        false;


    const estadosDisponibilidad =
    {
        rut:
            "vacio",

        email:
            "vacio",

        nombreUsuario:
            "vacio"
    };


    const temporizadores =
    {
        rut:
            null,

        email:
            null,

        nombreUsuario:
            null
    };


    const solicitudes =
    {
        rut:
            0,

        email:
            0,

        nombreUsuario:
            0
    };



    // =========================================================
    // CAMPOS
    // =========================================================

    function obtenerCamposUsuario() {

        return {

            nombre:
                document.getElementById(
                    "nombre"
                ),

            apellido:
                document.getElementById(
                    "apellido"
                ),

            email:
                document.getElementById(
                    "email"
                ),

            rut:
                document.getElementById(
                    "rut"
                ),

            rol:
                document.getElementById(
                    "id_rol"
                ),

            nombreUsuario:
                document.getElementById(
                    "nombre_usuario"
                ),

            contrasena:
                document.getElementById(
                    "contrasena"
                )

        };

    }



    // =========================================================
    // MENSAJE GENERAL
    // =========================================================

    function ocultarMensajeGeneral() {

        const mensaje =
            document.getElementById(
                "mensajeFormulario"
            );


        if (!mensaje) {

            return;

        }


        mensaje.innerText =
            "";


        mensaje.className =
            "mensaje mensaje-error mensaje-oculto";


        mensaje.style.visibility =
            "hidden";


        mensaje.style.opacity =
            "1";

    }



    function mostrarErrorGeneral(
        texto,
        campo
    ) {

        const mensaje =
            document.getElementById(
                "mensajeFormulario"
            );


        if (mensaje) {

            mensaje.innerText =
                texto;


            mensaje.className =
                "mensaje mensaje-error";


            mensaje.style.visibility =
                "visible";


            mensaje.style.opacity =
                "1";

        }


        if (campo) {

            campo.classList.add(
                "campo-error"
            );


            campo.focus();

        }

    }



    function limpiarErrorCampo(
        campo
    ) {

        if (!campo) {

            return;

        }


        campo.classList.remove(
            "campo-error"
        );

    }



    // =========================================================
    // FORMATEAR RUT
    // =========================================================

    function formatearRut(
        input
    ) {

        let rut =
            input.value
                .replace(
                    /[^0-9kK]/g,
                    ""
                )
                .toUpperCase()
                .substring(
                    0,
                    9
                );


        if (
            rut.length
            >
            1
        ) {

            rut =
                rut.slice(
                    0,
                    -1
                )
                +
                "-"
                +
                rut.slice(
                    -1
                );

        }


        input.value =
            rut;

    }



    // =========================================================
    // VALIDAR DIGITO VERIFICADOR
    // =========================================================

    function validarDigitoRut(
        rutFormateado
    ) {

        const rutLimpio =
            String(
                rutFormateado
                ??
                ""
            )
                .replace(
                    /\./g,
                    ""
                )
                .replace(
                    /-/g,
                    ""
                )
                .toUpperCase();


        if (
            !/^\d{7,8}[0-9K]$/.test(
                rutLimpio
            )
        ) {

            return false;

        }


        const cuerpo =
            rutLimpio.slice(
                0,
                -1
            );


        const digitoIngresado =
            rutLimpio.slice(
                -1
            );


        let suma =
            0;


        let multiplicador =
            2;


        for (
            let i =
                cuerpo.length - 1;

            i >= 0;

            i--
        ) {

            suma +=
                Number(
                    cuerpo[i]
                )
                *
                multiplicador;


            multiplicador++;


            if (
                multiplicador
                >
                7
            ) {

                multiplicador =
                    2;

            }

        }


        const resultado =
            11
            -
            (
                suma
                %
                11
            );


        let digitoCalculado;


        if (
            resultado
            ===
            11
        ) {

            digitoCalculado =
                "0";

        }
        else if (
            resultado
            ===
            10
        ) {

            digitoCalculado =
                "K";

        }
        else {

            digitoCalculado =
                String(
                    resultado
                );

        }


        return (
            digitoIngresado
            ===
            digitoCalculado
        );

    }



    // =========================================================
    // VALIDAR CORREO
    // =========================================================
    //
    // \x40 representa el símbolo arroba.
    //
    // Así no escribimos ese carácter directamente dentro
    // del JavaScript de una vista Razor.
    // =========================================================

    function correoTieneFormatoValido(
        correo
    ) {

        return /^[^\s\x40]+\x40[^\s\x40]+\.[^\s\x40]+$/.test(
            String(
                correo
                ??
                ""
            )
                .trim()
        );

    }



    // =========================================================
    // CLASES DE DISPONIBILIDAD
    // =========================================================

    function limpiarClasesDisponibilidad(
        campo
    ) {

        if (!campo) {

            return;

        }


        campo.classList.remove(
            "campo-disponible"
        );


        campo.classList.remove(
            "campo-no-disponible"
        );

    }



    // =========================================================
    // ESTADO VACIO
    // =========================================================

    function mostrarEstadoVacio(
        elemento,
        campo
    ) {

        elemento.className =
            "validacion-caliente";


        elemento.innerHTML =
            "";


        limpiarClasesDisponibilidad(
            campo
        );


        campo.dataset.duplicado =
            "false";

    }



    // =========================================================
    // ESTADO INCOMPLETO
    // =========================================================

    function mostrarEstadoIncompleto(
        elemento,
        texto,
        campo
    ) {

        elemento.className =
            "validacion-caliente validacion-incompleta";


        elemento.textContent =
            texto;


        limpiarClasesDisponibilidad(
            campo
        );


        campo.dataset.duplicado =
            "false";

    }



    // =========================================================
    // ESTADO VERIFICANDO
    // =========================================================

    function mostrarEstadoVerificando(
        elemento,
        texto,
        campo
    ) {

        elemento.className =
            "validacion-caliente validacion-verificando";


        /*
            SVG animado.

            No necesita keyframes de CSS.
        */

        elemento.innerHTML =
            '<svg class="validacion-spinner" viewBox="0 0 24 24" aria-hidden="true">'
            +
            '<circle cx="12" cy="12" r="9" fill="none" stroke="#cad8df" stroke-width="3"></circle>'
            +
            '<path d="M12 3a9 9 0 0 1 9 9" fill="none" stroke="#1198a5" stroke-width="3" stroke-linecap="round">'
            +
            '<animateTransform attributeName="transform" type="rotate" from="0 12 12" to="360 12 12" dur="0.75s" repeatCount="indefinite"></animateTransform>'
            +
            '</path>'
            +
            '</svg>'
            +
            '<span>'
            +
            texto
            +
            '</span>';


        limpiarClasesDisponibilidad(
            campo
        );


        campo.dataset.duplicado =
            "false";

    }



    // =========================================================
    // ESTADO CORRECTO
    // =========================================================

    function mostrarEstadoCorrecto(
        elemento,
        texto,
        campo
    ) {

        elemento.className =
            "validacion-caliente validacion-correcta";


        elemento.innerHTML =
            '<span class="validacion-icono-ok" aria-hidden="true">✓</span>'
            +
            '<span>'
            +
            texto
            +
            '</span>';


        limpiarClasesDisponibilidad(
            campo
        );


        campo.classList.add(
            "campo-disponible"
        );


        campo.dataset.duplicado =
            "false";

    }



    // =========================================================
    // ESTADO ERROR
    // =========================================================

    function mostrarEstadoError(
        elemento,
        texto,
        campo,
        duplicado
    ) {

        elemento.className =
            "validacion-caliente validacion-error";


        elemento.innerHTML =
            '<span class="validacion-icono-error" aria-hidden="true">×</span>'
            +
            '<span>'
            +
            texto
            +
            '</span>';


        limpiarClasesDisponibilidad(
            campo
        );


        campo.classList.add(
            "campo-no-disponible"
        );


        campo.dataset.duplicado =
            duplicado
                ? "true"
                : "false";

    }



    // =========================================================
    // CONSULTA HTTP
    // =========================================================

    async function consultarDisponibilidad(
        url
    ) {

        const respuesta =
            await fetch(
                url,
                {
                    method:
                        "GET",

                    headers:
                    {
                        "X-Requested-With":
                            "XMLHttpRequest"
                    },

                    cache:
                        "no-store"
                }
            );


        if (!respuesta.ok) {

            throw new Error(
                "No se pudo completar la verificación."
            );

        }


        return await respuesta.json();

    }



    // =========================================================
    // VALIDACION EN CALIENTE - RUT
    // =========================================================

    function prepararValidacionRut() {

        const campo =
            document.getElementById(
                "rut"
            );


        const estado =
            document.getElementById(
                "estadoRut"
            );


        campo.addEventListener(
            "input",
            function (
                evento
            ) {

                /*
                    Evita que otra validación en bubble
                    vuelva a procesar este mismo evento.
                */

                evento.stopPropagation();


                formatearRut(
                    campo
                );


                clearTimeout(
                    temporizadores.rut
                );


                solicitudes.rut++;


                const solicitudActual =
                    solicitudes.rut;


                const valor =
                    campo.value
                        .trim();


                limpiarErrorCampo(
                    campo
                );


                ocultarMensajeGeneral();


                limpiarClasesDisponibilidad(
                    campo
                );


                campo.dataset.duplicado =
                    "false";


                if (
                    valor
                    ===
                    ""
                ) {

                    estadosDisponibilidad.rut =
                        "vacio";


                    mostrarEstadoVacio(
                        estado,
                        campo
                    );


                    return;

                }


                const rutLimpio =
                    valor.replace(
                        /[-.]/g,
                        ""
                    );


                if (
                    rutLimpio.length
                    <
                    8
                ) {

                    estadosDisponibilidad.rut =
                        "incompleto";


                    mostrarEstadoIncompleto(
                        estado,
                        "Continúe ingresando el RUT.",
                        campo
                    );


                    return;

                }


                if (
                    !validarDigitoRut(
                        valor
                    )
                ) {

                    estadosDisponibilidad.rut =
                        "invalido";


                    mostrarEstadoError(
                        estado,
                        "El RUT ingresado no es válido.",
                        campo,
                        false
                    );


                    return;

                }


                estadosDisponibilidad.rut =
                    "verificando";


                mostrarEstadoVerificando(
                    estado,
                    "Verificando disponibilidad...",
                    campo
                );


                temporizadores.rut =
                    setTimeout(
                        async function () {

                            try {

                                const datos =
                                    await consultarDisponibilidad(
                                        "/Home/VerificarRut?rut="
                                        +
                                        encodeURIComponent(
                                            valor
                                        )
                                    );


                                if (
                                    solicitudes.rut
                                    !==
                                    solicitudActual
                                    ||
                                    campo.value.trim()
                                    !==
                                    valor
                                ) {

                                    return;

                                }


                                if (
                                    datos.existe
                                    ===
                                    true
                                ) {

                                    estadosDisponibilidad.rut =
                                        "ocupado";


                                    mostrarEstadoError(
                                        estado,
                                        "Este RUT ya está registrado.",
                                        campo,
                                        true
                                    );

                                }
                                else {

                                    estadosDisponibilidad.rut =
                                        "disponible";


                                    mostrarEstadoCorrecto(
                                        estado,
                                        "RUT válido y disponible.",
                                        campo
                                    );

                                }

                            }
                            catch {

                                if (
                                    solicitudes.rut
                                    !==
                                    solicitudActual
                                ) {

                                    return;

                                }


                                estadosDisponibilidad.rut =
                                    "error";


                                mostrarEstadoError(
                                    estado,
                                    "No se pudo verificar el RUT. Intente nuevamente.",
                                    campo,
                                    false
                                );

                            }

                        },
                        450
                    );

            }
        );

    }



    // =========================================================
    // VALIDACION EN CALIENTE - CORREO
    // =========================================================

    function prepararValidacionEmail() {

        const campo =
            document.getElementById(
                "email"
            );


        const estado =
            document.getElementById(
                "estadoEmail"
            );


        campo.addEventListener(
            "input",
            function (
                evento
            ) {

                evento.stopPropagation();


                clearTimeout(
                    temporizadores.email
                );


                solicitudes.email++;


                const solicitudActual =
                    solicitudes.email;


                const valor =
                    campo.value
                        .trim();


                limpiarErrorCampo(
                    campo
                );


                ocultarMensajeGeneral();


                limpiarClasesDisponibilidad(
                    campo
                );


                campo.dataset.duplicado =
                    "false";


                if (
                    valor
                    ===
                    ""
                ) {

                    estadosDisponibilidad.email =
                        "vacio";


                    mostrarEstadoVacio(
                        estado,
                        campo
                    );


                    return;

                }


                if (
                    !correoTieneFormatoValido(
                        valor
                    )
                ) {

                    estadosDisponibilidad.email =
                        "incompleto";


                    mostrarEstadoIncompleto(
                        estado,
                        "Ingrese un correo electrónico válido.",
                        campo
                    );


                    return;

                }


                estadosDisponibilidad.email =
                    "verificando";


                mostrarEstadoVerificando(
                    estado,
                    "Verificando correo...",
                    campo
                );


                temporizadores.email =
                    setTimeout(
                        async function () {

                            try {

                                const datos =
                                    await consultarDisponibilidad(
                                        "/Home/VerificarCorreo?correo="
                                        +
                                        encodeURIComponent(
                                            valor
                                        )
                                    );


                                if (
                                    solicitudes.email
                                    !==
                                    solicitudActual
                                    ||
                                    campo.value.trim()
                                    !==
                                    valor
                                ) {

                                    return;

                                }


                                if (
                                    datos.existe
                                    ===
                                    true
                                ) {

                                    estadosDisponibilidad.email =
                                        "ocupado";


                                    mostrarEstadoError(
                                        estado,
                                        "Este correo ya está registrado.",
                                        campo,
                                        true
                                    );

                                }
                                else {

                                    estadosDisponibilidad.email =
                                        "disponible";


                                    mostrarEstadoCorrecto(
                                        estado,
                                        "Correo disponible.",
                                        campo
                                    );

                                }

                            }
                            catch {

                                if (
                                    solicitudes.email
                                    !==
                                    solicitudActual
                                ) {

                                    return;

                                }


                                estadosDisponibilidad.email =
                                    "error";


                                mostrarEstadoError(
                                    estado,
                                    "No se pudo verificar el correo. Intente nuevamente.",
                                    campo,
                                    false
                                );

                            }

                        },
                        500
                    );

            }
        );

    }



    // =========================================================
    // VALIDACION EN CALIENTE - NOMBRE USUARIO
    // =========================================================

    function prepararValidacionNombreUsuario() {

        const campo =
            document.getElementById(
                "nombre_usuario"
            );


        const estado =
            document.getElementById(
                "estadoNombreUsuario"
            );


        campo.addEventListener(
            "input",
            function (
                evento
            ) {

                evento.stopPropagation();


                clearTimeout(
                    temporizadores.nombreUsuario
                );


                solicitudes.nombreUsuario++;


                const solicitudActual =
                    solicitudes.nombreUsuario;


                const valor =
                    campo.value
                        .trim();


                limpiarErrorCampo(
                    campo
                );


                ocultarMensajeGeneral();


                limpiarClasesDisponibilidad(
                    campo
                );


                campo.dataset.duplicado =
                    "false";


                if (
                    valor
                    ===
                    ""
                ) {

                    estadosDisponibilidad.nombreUsuario =
                        "vacio";


                    mostrarEstadoVacio(
                        estado,
                        campo
                    );


                    return;

                }


                if (
                    valor.length
                    <
                    3
                ) {

                    estadosDisponibilidad.nombreUsuario =
                        "incompleto";


                    mostrarEstadoIncompleto(
                        estado,
                        "Ingrese al menos 3 caracteres.",
                        campo
                    );


                    return;

                }


                estadosDisponibilidad.nombreUsuario =
                    "verificando";


                mostrarEstadoVerificando(
                    estado,
                    "Verificando nombre de usuario...",
                    campo
                );


                temporizadores.nombreUsuario =
                    setTimeout(
                        async function () {

                            try {

                                const datos =
                                    await consultarDisponibilidad(
                                        "/Home/VerificarNombreUsuario?nombreUsuario="
                                        +
                                        encodeURIComponent(
                                            valor
                                        )
                                    );


                                if (
                                    solicitudes.nombreUsuario
                                    !==
                                    solicitudActual
                                    ||
                                    campo.value.trim()
                                    !==
                                    valor
                                ) {

                                    return;

                                }


                                if (
                                    datos.existe
                                    ===
                                    true
                                ) {

                                    estadosDisponibilidad.nombreUsuario =
                                        "ocupado";


                                    mostrarEstadoError(
                                        estado,
                                        "Este nombre de usuario ya existe.",
                                        campo,
                                        true
                                    );

                                }
                                else {

                                    estadosDisponibilidad.nombreUsuario =
                                        "disponible";


                                    mostrarEstadoCorrecto(
                                        estado,
                                        "Nombre de usuario disponible.",
                                        campo
                                    );

                                }

                            }
                            catch {

                                if (
                                    solicitudes.nombreUsuario
                                    !==
                                    solicitudActual
                                ) {

                                    return;

                                }


                                estadosDisponibilidad.nombreUsuario =
                                    "error";


                                mostrarEstadoError(
                                    estado,
                                    "No se pudo verificar el nombre de usuario. Intente nuevamente.",
                                    campo,
                                    false
                                );

                            }

                        },
                        500
                    );

            }
        );

    }



    // =========================================================
    // VALIDACION FINAL
    // =========================================================

    function validarYConfirmar() {

        const campos =
            obtenerCamposUsuario();


        /*
            Solo queremos un campo rojo a la vez.
        */

        document
            .querySelectorAll(
                "#formCrearUsuario .campo-error"
            )
            .forEach(
                function (
                    campo
                ) {

                    campo.classList.remove(
                        "campo-error"
                    );

                }
            );


        ocultarMensajeGeneral();



        // =====================================================
        // NOMBRE
        // =====================================================

        if (
            campos.nombre.value
                .trim()
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe ingresar el nombre.",
                campos.nombre
            );


            return false;

        }



        // =====================================================
        // APELLIDO
        // =====================================================

        if (
            campos.apellido.value
                .trim()
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe ingresar el apellido.",
                campos.apellido
            );


            return false;

        }



        // =====================================================
        // CORREO
        // =====================================================

        if (
            campos.email.value
                .trim()
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe ingresar el correo electrónico.",
                campos.email
            );


            return false;

        }


        if (
            !correoTieneFormatoValido(
                campos.email.value
            )
        ) {

            mostrarErrorGeneral(
                "Debe ingresar un correo electrónico válido.",
                campos.email
            );


            return false;

        }


        if (
            estadosDisponibilidad.email
            ===
            "verificando"
        ) {

            mostrarErrorGeneral(
                "Espere mientras se verifica el correo electrónico.",
                campos.email
            );


            return false;

        }


        if (
            estadosDisponibilidad.email
            ===
            "ocupado"
        ) {

            mostrarErrorGeneral(
                "El correo electrónico ingresado ya está registrado.",
                campos.email
            );


            return false;

        }


        if (
            estadosDisponibilidad.email
            !==
            "disponible"
        ) {

            mostrarErrorGeneral(
                "Debe verificarse el correo antes de crear el usuario.",
                campos.email
            );


            return false;

        }



        // =====================================================
        // RUT
        // =====================================================

        if (
            campos.rut.value
                .trim()
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe ingresar el RUT.",
                campos.rut
            );


            return false;

        }


        if (
            !validarDigitoRut(
                campos.rut.value
            )
        ) {

            mostrarErrorGeneral(
                "El RUT ingresado no es válido.",
                campos.rut
            );


            return false;

        }


        if (
            estadosDisponibilidad.rut
            ===
            "verificando"
        ) {

            mostrarErrorGeneral(
                "Espere mientras se verifica el RUT.",
                campos.rut
            );


            return false;

        }


        if (
            estadosDisponibilidad.rut
            ===
            "ocupado"
        ) {

            mostrarErrorGeneral(
                "El RUT ingresado ya está registrado.",
                campos.rut
            );


            return false;

        }


        if (
            estadosDisponibilidad.rut
            !==
            "disponible"
        ) {

            mostrarErrorGeneral(
                "Debe verificarse el RUT antes de crear el usuario.",
                campos.rut
            );


            return false;

        }



        // =====================================================
        // ROL
        // =====================================================

        if (
            campos.rol.value
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe seleccionar un rol.",
                campos.rol
            );


            return false;

        }



        // =====================================================
        // NOMBRE DE USUARIO
        // =====================================================

        if (
            campos.nombreUsuario.value
                .trim()
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe ingresar el nombre de usuario.",
                campos.nombreUsuario
            );


            return false;

        }


        if (
            campos.nombreUsuario.value
                .trim()
                .length
            <
            3
        ) {

            mostrarErrorGeneral(
                "El nombre de usuario debe tener al menos 3 caracteres.",
                campos.nombreUsuario
            );


            return false;

        }


        if (
            estadosDisponibilidad.nombreUsuario
            ===
            "verificando"
        ) {

            mostrarErrorGeneral(
                "Espere mientras se verifica el nombre de usuario.",
                campos.nombreUsuario
            );


            return false;

        }


        if (
            estadosDisponibilidad.nombreUsuario
            ===
            "ocupado"
        ) {

            mostrarErrorGeneral(
                "El nombre de usuario ingresado ya existe.",
                campos.nombreUsuario
            );


            return false;

        }


        if (
            estadosDisponibilidad.nombreUsuario
            !==
            "disponible"
        ) {

            mostrarErrorGeneral(
                "Debe verificarse el nombre de usuario antes de crear el usuario.",
                campos.nombreUsuario
            );


            return false;

        }



        // =====================================================
        // CONTRASEÑA
        // =====================================================

        if (
            campos.contrasena.value
                .trim()
            ===
            ""
        ) {

            mostrarErrorGeneral(
                "Debe ingresar una contraseña.",
                campos.contrasena
            );


            return false;

        }



        // =====================================================
        // TODO CORRECTO
        // =====================================================

        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "flex";


        return true;

    }



    // =========================================================
    // CONFIRMAR CREACION
    // =========================================================

    function crearUsuario() {

        usuarioConfirmado =
            true;


        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "none";


        document.getElementById(
            "formCrearUsuario"
        ).requestSubmit();

    }



    // =========================================================
    // CERRAR CONFIRMACION
    // =========================================================

    function cerrarConfirmacion() {

        usuarioConfirmado =
            false;


        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "none";

    }



    // =========================================================
    // CANCELAR CREACION
    // =========================================================

    function cancelarCreacion() {

        usuarioConfirmado =
            false;


        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "none";


        const formulario =
            document.getElementById(
                "formCrearUsuario"
            );


        formulario.reset();


        clearTimeout(
            temporizadores.rut
        );


        clearTimeout(
            temporizadores.email
        );


        clearTimeout(
            temporizadores.nombreUsuario
        );


        /*
            Invalidamos respuestas pendientes.
        */

        solicitudes.rut++;


        solicitudes.email++;


        solicitudes.nombreUsuario++;


        estadosDisponibilidad.rut =
            "vacio";


        estadosDisponibilidad.email =
            "vacio";


        estadosDisponibilidad.nombreUsuario =
            "vacio";


        const campos =
            obtenerCamposUsuario();


        mostrarEstadoVacio(
            document.getElementById(
                "estadoRut"
            ),
            campos.rut
        );


        mostrarEstadoVacio(
            document.getElementById(
                "estadoEmail"
            ),
            campos.email
        );


        mostrarEstadoVacio(
            document.getElementById(
                "estadoNombreUsuario"
            ),
            campos.nombreUsuario
        );


        document
            .querySelectorAll(
                "#formCrearUsuario .campo-error"
            )
            .forEach(
                function (
                    campo
                ) {

                    campo.classList.remove(
                        "campo-error"
                    );

                }
            );


        ocultarMensajeGeneral();


        campos.nombre.focus();

    }



    // =========================================================
    // SUBMIT LOCAL
    // =========================================================
    //
    // IMPORTANTE:
    //
    // Este formulario se valida aquí ANTES que site.js.
    //
    // Evitamos así que la validación general y la validación
    // especial en caliente de Crear Usuario compitan.
    //
    // =========================================================

    document.addEventListener(
        "submit",
        function (
            evento
        ) {

            const formulario =
                evento.target;


            if (
                !(
                    formulario
                    instanceof
                    HTMLFormElement
                )
                ||
                formulario.id
                !==
                "formCrearUsuario"
            ) {

                return;

            }


            /*
                Evitamos que site.js vuelva a validar
                este formulario.
            */

            evento.stopImmediatePropagation();


            /*
                Si ya se confirmó mediante el modal,
                dejamos que el POST continúe.
            */

            if (usuarioConfirmado) {

                return;

            }


            evento.preventDefault();


            validarYConfirmar();

        },
        true
    );



    // =========================================================
    // QUITAR ERROR CUANDO SE CORRIGE UN CAMPO NORMAL
    // =========================================================

    document
        .querySelectorAll(
            "#formCrearUsuario input:not(#email):not(#rut):not(#nombre_usuario)"
        )
        .forEach(
            function (
                campo
            ) {

                campo.addEventListener(
                    "input",
                    function () {

                        limpiarErrorCampo(
                            this
                        );


                        ocultarMensajeGeneral();

                    }
                );

            }
        );



    document
        .getElementById(
            "id_rol"
        )
        .addEventListener(
            "change",
            function () {

                limpiarErrorCampo(
                    this
                );


                ocultarMensajeGeneral();

            }
        );



    // =========================================================
    // ACTIVAR VALIDACIONES EN CALIENTE
    // =========================================================

    prepararValidacionRut();


    prepararValidacionEmail();


    prepararValidacionNombreUsuario();



    // =========================================================
    // REVALIDAR SI EL SERVIDOR DEVUELVE DATOS
    // =========================================================

    window.addEventListener(
        "load",
        function () {

            const campos =
                obtenerCamposUsuario();


            [
                campos.email,
                campos.rut,
                campos.nombreUsuario
            ]
            .forEach(
                function (
                    campo
                ) {

                    if (
                        campo
                        &&
                        campo.value
                            .trim()
                        !==
                        ""
                    ) {

                        campo.dispatchEvent(
                            new Event(
                                "input",
                                {
                                    bubbles:
                                        false
                                }
                            )
                        );

                    }

                }
            );

        }
    );



    // =========================================================
    // OCULTAR MENSAJE DE EXITO
    // =========================================================

    setTimeout(
        function () {

            const mensaje =
                document.getElementById(
                    "mensajeFormulario"
                );


            if (
                mensaje
                &&
                mensaje.classList.contains(
                    "mensaje-exito"
                )
            ) {

                mensaje.style.opacity =
                    "0";


                setTimeout(
                    function () {

                        mensaje.style.visibility =
                            "hidden";

                    },
                    500
                );

            }

        },
        3000
    );

</script>

