LoginSARMedix/Views/Home/EditarProducto..text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "EditarProducto"; ViewData["SmFamily"] = "products"; }
@model LoginSARMedix.Models.Producto

@{
    ViewData["Title"] = "Editar Producto";
    ViewData["TituloBarra"] = "Editar Producto";

    string mensaje =
        TempData["Mensaje"]?.ToString()
        ?? ViewBag.Mensaje?.ToString()
        ?? "";

    string tipoMensaje =
        TempData["TipoMensaje"]?.ToString()
        ?? (ViewBag.Mensaje != null ? "error" : "");
}

<header class="orbit-editor-heading"><span class="orbit-eyebrow">ÓRBITA / CATÁLOGO</span><h1>Editar producto</h1></header>

<form asp-controller="Home"
      asp-action="ActualizarProducto"
      method="post"
      class="formulario-principal"
      id="formEditarProducto"
      onsubmit="return validarYConfirmar()"
      novalidate data-orbit-form="EditarProducto">

    <input asp-for="id_producto" type="hidden" />
    <input asp-for="tipo" type="hidden" />
    <input asp-for="codigo_interno" id="codigoInterno" type="hidden" />


    <div class="espacio-mensaje">
        @if (!string.IsNullOrEmpty(mensaje))
        {
            if (tipoMensaje == "exito")
            {
                <div class="mensaje mensaje-exito" id="mensajeFormulario">
                    @mensaje
                </div>
            }
            else
            {
                <div class="mensaje mensaje-error" id="mensajeFormulario">
                    @mensaje
                </div>
            }
        }
        else
        {
            <div class="mensaje mensaje-error mensaje-oculto"
                 id="mensajeFormulario">
            </div>
        }
    </div>


    <div class="orbit-product-grid"><fieldset class="orbit-product-identity"><legend>01 · Identificación y presentación</legend><div>
        <label>Tipo de producto</label>
        <input value="@Model.tipo" disabled />
    </div>


    <div class="bloque-codigo-barras">
        <partial name="_OrbitScanner" />
        <div class="fila-codigo-barras">
            <label for="codigoBarras">Código de barras / GTIN</label>
            <span class="badge-codigo">ESCÁNER O MANUAL</span>
        </div>

        <input asp-for="codigo_barras"
               id="codigoBarras"
               autocomplete="off"
               placeholder="Escanee el código o escríbalo aquí" />

        <div class="ayuda-codigo">
            <span class="icono-codigo">▦</span>
            <span>
                <strong>Escanee con el lector</strong> o escriba el código manualmente.
                Si el producto no tiene código, puede dejar este campo vacío.
            </span>
        </div>
    </div>


    <div>
        <label for="nombreProducto">Nombre</label>
        <input asp-for="nombre" id="nombreProducto" />
    </div>


    @if (Model.tipo == "Medicamento")
    {
        <div>
            <label for="formaFarmaceutica">Forma farmacéutica</label>

            <select asp-for="forma_farmaceutica"
                    id="formaFarmaceutica"
                    onchange="sugerirUnidadSegunForma()">
                <option value="">Seleccione</option>
                <option value="Comprimido">Comprimido</option>
                <option value="Comprimido recubierto">Comprimido recubierto</option>
                <option value="Cápsula">Cápsula</option>
                <option value="Solución oral">Solución oral</option>
                <option value="Jarabe">Jarabe</option>
                <option value="Ampolla">Ampolla</option>
                <option value="Gotas">Gotas</option>
                <option value="Crema">Crema</option>
                <option value="Inhalador">Inhalador</option>
                <option value="Supositorio">Supositorio</option>
                <option value="Sobre">Sobre</option>
                <option value="Otro">Otro</option>
            </select>
        </div>

        <div>
            <label for="principioActivo">Principio activo</label>
            <input asp-for="principio_activo" id="principioActivo" />
        </div>

        <div>
            <label for="concentracion">Concentración</label>
            <input asp-for="concentracion"
                   id="concentracion"
                   placeholder="Ej.: 500 mg / 400 mg" />

            <small class="texto-ayuda">
                Aquí van los mg, g, mg/mL, etc. La concentración NO es la cantidad física de comprimidos del envase.
            </small>
        </div>

        <div>
            <label for="requiereControl">¿Requiere control?</label>

            <select asp-for="requiere_control"
                    id="requiereControl">
                <option value="false">No</option>
                <option value="true">Sí</option>
            </select>
        </div>
    }


    @if (Model.tipo == "Insumo")
    {
        <div>
            <label for="material">Material</label>
            <input asp-for="material" id="material" />
        </div>

        <div>
            <label for="esEsteril">¿Es estéril?</label>

            <select asp-for="es_esteril"
                    id="esEsteril">
                <option value="false">No</option>
                <option value="true">Sí</option>
            </select>
        </div>
    }


    </fieldset><fieldset class="orbit-product-content"><legend>02 · Contenido e inventario</legend><div class="seccion-inventario">
        <div class="seccion-inventario-titulo">Control de contenido y stock</div>
        <div class="seccion-inventario-subtitulo">
            Indique cuánto contiene el producto y en qué unidad se controlará.
        </div>

        <div>
            <label for="contenidoPorEnvase">Cantidad por envase</label>

            <input asp-for="contenido_por_envase"
                   id="contenidoPorEnvase"
                   type="number"
                   min="1"
                   placeholder="Ej.: 60"
                   oninput="actualizarResumenStock()" />

            <small class="texto-ayuda">
                Ejemplo: una caja con 60 comprimidos = 60 + Comprimidos.
            </small>
        </div>

        <div>
            <label for="unidadMedidaReal">Unidad de inventario / contenido</label>

            <input asp-for="unidad_medida"
                   id="unidadMedidaReal"
                   type="hidden" />

            <select id="unidadSelector"
                    onchange="cambiarUnidad()">
                <option value="">Seleccione</option>

                <optgroup label="Unidades físicas">
                    <option value="Comprimidos">Comprimidos</option>
                    <option value="Cápsulas">Cápsulas</option>
                    <option value="Ampollas">Ampollas</option>
                    <option value="Sobres">Sobres</option>
                    <option value="Supositorios">Supositorios</option>
                    <option value="Inhaladores">Inhaladores</option>
                    <option value="Frascos">Frascos</option>
                    <option value="Unidades">Unidades</option>
                </optgroup>

                <optgroup label="Peso / volumen">
                    <option value="mg">mg</option>
                    <option value="g">g</option>
                    <option value="kg">kg</option>
                    <option value="mL">mL</option>
                    <option value="L">L</option>
                </optgroup>

                <option value="Otro">Otro</option>
                <option value="Omitir">Omitir</option>
            </select>

            <small class="texto-ayuda">
                Para comprimidos use <strong>Comprimidos</strong>.
                Mantuvimos mg/g disponibles para productos cuyo stock realmente se controle por peso.
            </small>

            <div id="advertenciaUnidad"
                 class="ayuda-stock"
                 style="display:none; margin-top:8px;"></div>

            <div id="unidadOtroContenedor"
                 class="unidad-otro"
                 style="display:none;">
                <label for="unidadOtro">Especifique la unidad</label>

                <input id="unidadOtro"
                       type="text"
                       placeholder="Ej.: comprimidos, ampollas, sobres"
                       oninput="actualizarUnidadPersonalizada()" />
            </div>
        </div>

        <div>
            <label id="labelStockMinimo">Alerta de stock bajo</label>

            <input asp-for="stock_minimo"
                   id="stockMinimo"
                   type="number"
                   min="0"
                   oninput="actualizarResumenStock()" />

            <div class="ayuda-stock" id="ayudaStock"></div>
        </div>
    </div>


    <br />

    </fieldset></div><div class="orbit-form-actions"><button type="submit" data-orbit-action="primary">Actualizar producto</button>
</div></form>


<div class="contenedor-volver">
    <a asp-controller="Home"
       asp-action="ListadoProductos2"
       class="btn-volver-listado" data-orbit-action="secondary">
        ← Volver al listado de productos
    </a>

    <a asp-controller="Home"
       asp-action="Productos"
       class="btn-volver-productos" data-orbit-action="secondary">
        ← Volver a Productos
    </a>
</div>


<div id="modalConfirmacion" class="modal-fondo">
    <div class="modal-contenido" data-orbit-dialog="surface">
        <div class="modal-icono">?</div>
        <h2>Confirmar acción</h2>
        <p>¿Quieres actualizar este producto?</p>

        <div class="modal-botones">
            <button type="button"
                    class="btn-modal-si"
                    onclick="actualizarProducto()" data-orbit-action="primary">
                Sí
            </button>

            <button type="button"
                    class="btn-modal-no"
                    onclick="cerrarConfirmacion()" data-orbit-action="secondary">
                No
            </button>

            <button type="button"
                    class="btn-modal-cancelar"
                    onclick="cancelarEdicion()" data-orbit-action="secondary">
                Cancelar
            </button>
        </div>
    </div>
</div>


<style>
    .espacio-mensaje {
        min-height: 48px;
        margin-bottom: 8px;
    }

    .mensaje {
        width: 100%;
        padding: 12px 15px;
        border-radius: 7px;
        text-align: center;
        font-weight: 600;
        opacity: 1;
        transition: opacity 0.5s ease;
    }

    .mensaje-exito {
        background-color: #d1e7dd;
        color: #0f5132;
        border: 1px solid #badbcc;
    }

    .mensaje-error {
        background-color: #f8d7da;
        color: #842029;
        border: 1px solid #f5c2c7;
    }

    .mensaje-oculto {
        visibility: hidden;
    }

    .bloque-codigo-barras {
        padding: 14px;
        margin: 4px 0 16px 0;
        border: 1px solid #b8dbe4;
        border-radius: 10px;
        background-color: #f4fbfc;
    }

    .fila-codigo-barras {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 10px;
        flex-wrap: wrap;
    }

    .badge-codigo {
        padding: 4px 8px;
        border-radius: 999px;
        background-color: #d9f1f4;
        color: #0b6670;
        font-size: 10px;
        font-weight: 800;
        letter-spacing: .04em;
    }

    .bloque-codigo-barras input {
        margin-top: 5px;
    }

    .ayuda-codigo {
        display: flex;
        align-items: flex-start;
        gap: 8px;
        margin-top: 8px;
        color: #526d7c;
        font-size: 12px;
        line-height: 1.45;
    }

    .ayuda-codigo strong { color: #075f6b; }
    .icono-codigo { color: #1198a5; font-size: 18px; line-height: 1; }

    .seccion-inventario {
        margin-top: 18px;
        padding-top: 18px;
        border-top: 1px solid #dbe5ea;
    }

    .seccion-inventario-titulo {
        color: #003b64;
        font-size: 15px;
        font-weight: 700;
    }

    .seccion-inventario-subtitulo {
        margin: 3px 0 14px 0;
        color: #718592;
        font-size: 12px;
    }

    .unidad-otro { margin-top: 10px; }

    .ayuda-stock {
        margin-top: 8px;
        padding: 10px 12px;
        border-radius: 8px;
        background-color: #f3fafc;
        border: 1px solid #c9e5ec;
        color: #536c7b;
        font-size: 12px;
        line-height: 1.45;
    }

    .ayuda-stock strong { color: #0b5f7b; }

    .contenedor-volver {
        display: flex;
        justify-content: center;
        gap: 15px;
        flex-wrap: wrap;
        margin-top: 30px;
        margin-bottom: 30px;
    }

    .btn-volver-listado,
    .btn-volver-productos {
        display: inline-block;
        padding: 12px 22px;
        color: white;
        border-radius: 7px;
        text-decoration: none;
        font-weight: 600;
    }

    .btn-volver-listado { background-color: #59636b; }
    .btn-volver-listado:hover { background-color: #474f55; color: white; }
    .btn-volver-productos { background-color: #1198a5; }
    .btn-volver-productos:hover { background-color: #0d8490; color: white; }

    .modal-fondo {
        display: none;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.45);
        align-items: center;
        justify-content: center;
        z-index: 9999;
    }

    .modal-contenido {
        width: 90%;
        max-width: 430px;
        background-color: white;
        border-radius: 15px;
        padding: 30px;
        text-align: center;
        box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25);
    }

    .modal-icono {
        width: 55px;
        height: 55px;
        margin: 0 auto 15px auto;
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: #1198a5;
        color: white;
        border-radius: 50%;
        font-size: 30px;
        font-weight: bold;
    }

    .modal-contenido h2 { margin-top: 0; color: #003b64; }
    .modal-contenido p { margin-top: 15px; margin-bottom: 25px; font-size: 17px; color: #444; }

    .modal-botones {
        display: flex;
        justify-content: center;
        gap: 10px;
        flex-wrap: wrap;
    }

    .modal-botones button {
        min-width: 90px;
        padding: 10px 18px;
        border: none;
        border-radius: 7px;
        color: white;
        font-weight: 600;
        cursor: pointer;
    }

    .btn-modal-si { background-color: #198754; }
    .btn-modal-no { background-color: #c82333; }
    .btn-modal-cancelar { background-color: #59636b; }
</style>


<script>
    let productoConfirmado = false;

    function sugerirUnidadSegunForma() {
        const forma = document.getElementById("formaFarmaceutica");
        const selector = document.getElementById("unidadSelector");

        if (!forma || !selector) {
            return;
        }

        const sugerencias = {
            "Comprimido": "Comprimidos",
            "Comprimido recubierto": "Comprimidos",
            "Cápsula": "Cápsulas",
            "Ampolla": "Ampollas",
            "Sobre": "Sobres",
            "Supositorio": "Supositorios",
            "Inhalador": "Inhaladores",
            "Solución oral": "mL",
            "Jarabe": "mL",
            "Gotas": "mL",
            "Crema": "g"
        };

        const sugerida = sugerencias[forma.value];

        if (sugerida) {
            selector.value = sugerida;
            cambiarUnidad();
        }
    }


    function cambiarUnidad() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const contenedorOtro = document.getElementById("unidadOtroContenedor");
        const otro = document.getElementById("unidadOtro");

        if (selector.value === "Otro") {
            contenedorOtro.style.display = "block";
            real.value = otro.value.trim();
        }
        else if (selector.value === "Omitir") {
            contenedorOtro.style.display = "none";
            otro.value = "";
            real.value = "";
        }
        else {
            contenedorOtro.style.display = "none";
            otro.value = "";
            real.value = selector.value;
        }

        actualizarResumenStock();
    }

    function actualizarUnidadPersonalizada() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const otro = document.getElementById("unidadOtro");

        if (selector.value === "Otro") {
            real.value = otro.value.trim();
        }

        actualizarResumenStock();
    }

    function actualizarResumenStock() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const stock = document.getElementById("stockMinimo");
        const label = document.getElementById("labelStockMinimo");
        const ayuda = document.getElementById("ayudaStock");

        const unidad = real.value.trim();
        const minimo = stock.value.trim();
        const advertencia = document.getElementById("advertenciaUnidad");
        const forma = document.getElementById("formaFarmaceutica");

        if (advertencia) {
            advertencia.style.display = "none";
            advertencia.innerHTML = "";

            const esComprimido =
                forma
                && (forma.value === "Comprimido" || forma.value === "Comprimido recubierto");

            if (esComprimido && ["mg", "g", "kg"].includes(unidad)) {
                advertencia.style.display = "block";
                advertencia.innerHTML =
                    "⚠ Para comprimidos normalmente use <strong>Comprimidos</strong> como unidad de inventario. "
                    + "Los mg/g corresponden normalmente a la <strong>Concentración</strong>.";
            }
        }

        if (selector.value === "Omitir") {
            label.innerText = "Alerta de stock bajo";
            ayuda.innerHTML =
                minimo !== ""
                    ? `SARMedix avisará cuando el stock llegue a <strong>${minimo}</strong> o menos.`
                    : "Indique desde qué cantidad desea recibir una alerta de stock bajo.";
            return;
        }

        if (unidad === "") {
            label.innerText = "Alerta de stock bajo";
            ayuda.innerText = "Seleccione una unidad para ver cómo se interpretará la alerta.";
            return;
        }

        label.innerText = `Alerta de stock bajo (${unidad})`;
        ayuda.innerHTML =
            minimo !== ""
                ? `SARMedix avisará cuando queden <strong>${minimo} ${unidad}</strong> o menos.`
                : `La alerta se medirá en <strong>${unidad}</strong>.`;
    }

    function mostrarError(texto, campo) {
        const mensaje = document.getElementById("mensajeFormulario");
        mensaje.innerText = texto;
        mensaje.className = "mensaje mensaje-error";
        mensaje.style.visibility = "visible";
        mensaje.style.opacity = "1";
        campo.focus();
    }

    function validarYConfirmar() {
        if (productoConfirmado) {
            return true;
        }

        const nombre = document.getElementById("nombreProducto");
        const contenido = document.getElementById("contenidoPorEnvase");
        const unidadSelector = document.getElementById("unidadSelector");
        const unidadOtro = document.getElementById("unidadOtro");
        const stock = document.getElementById("stockMinimo");

        if (nombre.value.trim() === "") {
            mostrarError("Debe ingresar el nombre del producto.", nombre);
            return false;
        }

        @if (Model.tipo == "Medicamento")
        {
            <text>
                const forma = document.getElementById("formaFarmaceutica");
                const principio = document.getElementById("principioActivo");
                const concentracion = document.getElementById("concentracion");

                if (forma.value === "") {
                    mostrarError("Debe seleccionar la forma farmacéutica.", forma);
                    return false;
                }

                if (principio.value.trim() === "") {
                    mostrarError("Debe ingresar el principio activo.", principio);
                    return false;
                }

                if (concentracion.value.trim() === "") {
                    mostrarError("Debe ingresar la concentración.", concentracion);
                    return false;
                }
            </text>
        }

        @if (Model.tipo == "Insumo")
        {
            <text>
                const material = document.getElementById("material");

                if (material.value.trim() === "") {
                    mostrarError("Debe ingresar el material.", material);
                    return false;
                }
            </text>
        }

        if (contenido.value.trim() === "" || Number(contenido.value) <= 0) {
            mostrarError("La cantidad contenida debe ser mayor a 0.", contenido);
            return false;
        }

        if (unidadSelector.value === "") {
            mostrarError("Seleccione una unidad de inventario o elija Omitir.", unidadSelector);
            return false;
        }

        if (unidadSelector.value === "Otro" && unidadOtro.value.trim() === "") {
            mostrarError("Especifique la unidad de inventario.", unidadOtro);
            return false;
        }

        if (stock.value.trim() === "" || Number(stock.value) < 0) {
            mostrarError("Debe ingresar una cantidad válida para la alerta de stock bajo.", stock);
            return false;
        }

        document.getElementById("modalConfirmacion").style.display = "flex";
        return false;
    }

    function actualizarProducto() {
        productoConfirmado = true;
        document.getElementById("modalConfirmacion").style.display = "none";
        document.getElementById("formEditarProducto").requestSubmit();
    }

    function cerrarConfirmacion() {
        productoConfirmado = false;
        document.getElementById("modalConfirmacion").style.display = "none";
    }

    function cancelarEdicion() {
        productoConfirmado = false;
        document.getElementById("modalConfirmacion").style.display = "none";
        document.getElementById("formEditarProducto").reset();
        inicializarUnidad();
        actualizarResumenStock();
    }

    function inicializarUnidad() {
        const selector = document.getElementById("unidadSelector");
        const real = document.getElementById("unidadMedidaReal");
        const otro = document.getElementById("unidadOtro");
        const contenedorOtro = document.getElementById("unidadOtroContenedor");
        const valorGuardado = real.value.trim();
        const opciones = [
            "Comprimidos",
            "Cápsulas",
            "Ampollas",
            "Sobres",
            "Supositorios",
            "Inhaladores",
            "Frascos",
            "Unidades",
            "mg",
            "g",
            "kg",
            "mL",
            "L"
        ];

        if (valorGuardado === "") {
            selector.value = "Omitir";
            contenedorOtro.style.display = "none";
        }
        else if (opciones.includes(valorGuardado)) {
            selector.value = valorGuardado;
            contenedorOtro.style.display = "none";
        }
        else {
            selector.value = "Otro";
            otro.value = valorGuardado;
            contenedorOtro.style.display = "block";
        }
    }

    document.addEventListener("DOMContentLoaded", function () {
        inicializarUnidad();
        actualizarResumenStock();
    });

    setTimeout(function () {
        const mensaje = document.getElementById("mensajeFormulario");

        if (mensaje && !mensaje.classList.contains("mensaje-oculto")) {
            mensaje.style.opacity = "0";

            setTimeout(function () {
                mensaje.style.visibility = "hidden";
            }, 500);
        }
    }, 3000);
</script>

LoginSARMedix/Views/Home/EditarRol.cshtm.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "EditarRol"; ViewData["SmFamily"] = "users"; }
@model LoginSARMedix.Models.Rol

@{
    ViewData["Title"] = "Editar Rol";
    ViewData["TituloBarra"] = "Editar Rol";
}


<section class="contenedor-editar-rol">

    <h1 class="titulo-editar-rol">
        Editar Rol
    </h1>

    <p class="descripcion-editar-rol">
        Modifique el nombre o la descripción del rol seleccionado.
    </p>


    <div class="tarjeta-editar-rol">

        @if (ViewBag.Mensaje != null)
        {
            <div class="mensaje-error">
                @ViewBag.Mensaje
            </div>
        }


        <form asp-controller="Home"
              asp-action="ActualizarRol"
              method="post"
              class="form-editar-rol" data-orbit-form="EditarRol">

            <input type="hidden"
                   asp-for="id_rol" />


            <fieldset class="orbit-role-fields"><legend>Definición del rol</legend><div class="grupo-rol">

                <label asp-for="nombre">
                    Nombre del rol
                </label>

                <input asp-for="nombre"
                       required />

            </div>


            <div class="grupo-rol">

                <label asp-for="descripcion">
                    Descripción
                </label>

                <textarea asp-for="descripcion"
                          required></textarea>

            </div>


            </fieldset><button type="submit"
                    class="btn-guardar-rol" data-orbit-action="primary">

                Guardar cambios

            </button>

        </form>

    </div>



    <!-- VOLVER -->

    <div class="volver-rol">

        <a asp-controller="Home"
           asp-action="RolesPermisos"
           asp-route-idRol="@Model.id_rol"
           class="btn-volver-rol" data-orbit-action="secondary">

            ← Volver a Roles y Permisos

        </a>

    </div>

</section>



<style>

    /* CONTENEDOR */

    .contenedor-editar-rol {
        width: 90%;
        max-width: 650px;
        margin: 5px auto;
    }


    .titulo-editar-rol {
        margin-bottom: 8px;
        text-align: center;
        color: #087bc2;
        font-size: 32px;
        font-weight: 700;
    }


    .descripcion-editar-rol {
        margin-bottom: 30px;
        text-align: center;
        color: #687b89;
        font-size: 16px;
    }



    /* TARJETA */

    .tarjeta-editar-rol {
        padding: 35px;
        background: rgba(255, 255, 255, 0.96);
        border-radius: 14px;
        box-shadow: 0 7px 20px rgba(28, 65, 95, 0.15);
    }



    /* FORMULARIO */

    .form-editar-rol {
        width: 100%;
        max-width: none;
        margin: 0;
        padding: 0;
        background: transparent;
        box-shadow: none;
    }


    .grupo-rol {
        margin-bottom: 22px;
    }


    .grupo-rol label {
        display: block;
        margin-bottom: 8px;
        color: #17324d;
        font-weight: 600;
    }


    .grupo-rol input,
    .grupo-rol textarea {
        width: 100%;
        padding: 12px;
        border: 1px solid #b9cbd7;
        border-radius: 7px;
        background: white;
        color: #17324d;
        font-family: inherit;
        font-size: 15px;
    }


    .grupo-rol input:focus,
    .grupo-rol textarea:focus {
        outline: none;
        border-color: #087bc2;
        box-shadow: 0 0 0 3px rgba(8, 123, 194, 0.10);
    }


    .grupo-rol textarea {
        min-height: 120px;
        resize: vertical;
    }



    /* BOTON GUARDAR */

    .btn-guardar-rol {
        width: 100%;
        padding: 13px;
        background: #0b8f9c;
        color: white;
        border: none;
        border-radius: 7px;
        font-size: 15px;
        font-weight: 600;
        cursor: pointer;
    }


    .btn-guardar-rol:hover {
        background: #087580;
    }



    /* MENSAJE */

    .mensaje-error {
        margin-bottom: 22px;
        padding: 14px 18px;
        background: #fdecec;
        border: 1px solid #e5aaaa;
        color: #a12828;
        border-radius: 9px;
        font-size: 15px;
        font-weight: 600;
    }



    /* VOLVER */

    .volver-rol {
        margin-top: 30px;
        text-align: center;
    }


    .btn-volver-rol {
        display: inline-block;
        padding: 11px 20px;
        background: #0b8f9c;
        color: white;
        text-decoration: none;
        border-radius: 7px;
        font-weight: 600;
    }


    .btn-volver-rol:hover {
        background: #087580;
        color: white;
    }



    /* RESPONSIVE */

    @@media (max-width: 600px) {

        .contenedor-editar-rol {
            width: 94%;
        }


        .tarjeta-editar-rol {
            padding: 24px;
        }

    }

</style>

LoginSARMedix/Views/Home/EditarUsuario.c.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "EditarUsuario"; ViewData["SmFamily"] = "users"; }
@model LoginSARMedix.Models.Usuario

@{
    ViewData["Title"] = "Editar Usuario";
    ViewData["TituloBarra"] = "Editar Usuario";
}
<header class="orbit-editor-heading"><span class="orbit-eyebrow">ÓRBITA / PERSONAS</span><h1>Editar usuario</h1></header>

<form asp-controller="Home"
      asp-action="ActualizarUsuario"
      method="post"
      class="formulario-principal" data-orbit-form="EditarUsuario">

    <input asp-for="id_usuario"
           type="hidden" />


    <div class="orbit-identity-grid"><fieldset><legend>01 · Identidad personal</legend><div class="grupo-campo">

        <label for="nombre">
            Nombre
        </label>

        <input asp-for="nombre"
               autocomplete="off" />

    </div>


    <div class="grupo-campo">

        <label for="apellido">
            Apellido
        </label>

        <input asp-for="apellido"
               autocomplete="off" />

    </div>


    <div class="grupo-campo">

        <label for="email">
            Correo electrónico
        </label>

        <input asp-for="email"
               type="email"
               autocomplete="off" />

    </div>


    <div class="grupo-campo">

        <label for="rut">
            RUT
        </label>

        <input asp-for="rut"
               maxlength="10"
               autocomplete="off"
               oninput="formatearRut(this)" />

    </div>


    </fieldset><fieldset class="orbit-credentials"><legend>02 · Perfil de acceso</legend><div class="grupo-campo">

        <label for="id_rol">
            Rol
        </label>

        <select asp-for="id_rol">

            <option value="1">
                Administrador
            </option>

            <option value="2">
                TENS
            </option>

            <option value="3">
                Enfermera
            </option>

            <option value="4">
                Auxiliar
            </option>

        </select>

    </div>


    <div class="grupo-campo">

        <label for="nombre_usuario">
            Nombre de usuario
        </label>

        <input asp-for="nombre_usuario"
               autocomplete="off" />

    </div>


    </fieldset></div><div class="orbit-form-actions"><button type="submit" data-orbit-action="primary">

        Actualizar usuario

    </button>


    <div class="contenedor-volver">

        <a asp-controller="Home"
           asp-action="Usuarios"
           class="btn-volver" data-orbit-action="secondary">

            ← Volver al listado

        </a>

    </div>

</div></form>


@if (ViewBag.Mensaje != null)
{
    <div class="orbit-inline-error" role="alert">@ViewBag.Mensaje</div>
}


<style>

    .grupo-campo {
        width: 100%;
        margin-bottom: 18px;
    }


    .grupo-campo label {
        display: block;
        width: 100%;
        margin-bottom: 8px;
        font-weight: 600;
    }


    /* INPUTS */

    .formulario-principal input:not([type="hidden"]) {
        display: block !important;

        width: 100% !important;
        max-width: 100% !important;

        height: 54px !important;

        padding: 0 16px !important;

        margin: 0 !important;

        border: 1px solid #b8cfe0 !important;
        border-radius: 10px !important;

        background-color: #ffffff !important;

        font-size: 16px !important;
        font-family: inherit !important;

        box-sizing: border-box !important;

        outline: none !important;

        appearance: none;
        -webkit-appearance: none;
    }


    /* SELECT DEL ROL */

    .formulario-principal select {
        display: block !important;

        width: 100% !important;
        max-width: 100% !important;

        height: 54px !important;

        padding: 0 16px !important;

        margin: 0 !important;

        border: 1px solid #b8cfe0 !important;
        border-radius: 10px !important;

        background-color: #ffffff !important;

        font-size: 16px !important;
        font-family: inherit !important;

        box-sizing: border-box !important;

        outline: none !important;
    }


    /* FOCUS */

    .formulario-principal input:not([type="hidden"]):focus,
    .formulario-principal select:focus {
        border-color: #1198a5 !important;

        box-shadow:
            0 0 0 3px
            rgba(17, 152, 165, 0.15) !important;
    }


    /* BOTON ACTUALIZAR */

    .formulario-principal button[type="submit"] {
        width: 100%;

        min-height: 48px;

        border: none;

        border-radius: 8px;

        background-color: #1198a5;

        color: white;

        font-size: 16px;
        font-weight: 600;

        cursor: pointer;
    }


    .formulario-principal button[type="submit"]:hover {
        background-color: #0d8490;
    }


    /* BOTON VOLVER */

    .contenedor-volver {
        display: flex;
        justify-content: center;

        margin-top: 25px;
        margin-bottom: 20px;
    }


    .btn-volver {
        display: inline-block;

        padding: 12px 22px;

        background-color: #1198a5;

        color: white;

        border-radius: 7px;

        text-decoration: none;

        font-weight: 600;
    }


    .btn-volver:hover {
        background-color: #0d8490;
        color: white;
    }

</style>


<script>

    function formatearRut(input) {

        let rut = input.value
            .replace(/[^0-9kK]/g, '')
            .toUpperCase();


        rut = rut.substring(0, 9);


        if (rut.length > 1) {

            rut =
                rut.slice(0, -1)
                + "-"
                + rut.slice(-1);

        }


        input.value = rut;
    }

</script>

LoginSARMedix/Views/Home/EntregaDosifica.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "EntregaDosificacion"; ViewData["SmFamily"] = "dosing"; }
@{
    ViewData["Title"] = "Entrega por escáner";
    ViewData["TituloBarra"] = "Entrega por escáner";
}

<style>
    .scan-pagina {
        width: min(900px, 94%);
        margin: 40px auto 60px;
    }

    .scan-encabezado {
        text-align: center;
        margin-bottom: 22px;
    }

    .scan-encabezado h1 {
        margin: 0 0 7px;
        color: #17324d;
        font-size: 32px;
        font-weight: 900;
    }

    .scan-encabezado p {
        margin: 0;
        color: #607487;
    }

    .scan-panel {
        padding: 25px;
        border-radius: 18px;
        background: rgba(255,255,255,.97);
        box-shadow: 0 14px 32px rgba(36,76,105,.15);
    }

    .scan-caja {
        padding: 22px;
        border: 2px dashed #77b9d8;
        border-radius: 14px;
        background: #f5fbff;
        text-align: center;
    }

    .scan-caja label {
        display: block;
        margin-bottom: 10px;
        color: #245777;
        font-size: 16px;
        font-weight: 800;
    }

    .scan-input {
        width: 100%;
        min-height: 56px;
        padding: 12px 16px;
        border: 2px solid #0b82bd;
        border-radius: 11px;
        outline: none;
        text-align: center;
        font-size: 21px;
        font-weight: 800;
        letter-spacing: 1px;
        color: #17324d;
        background: white;
    }

    .scan-ayuda {
        margin-top: 9px;
        color: #7890a1;
        font-size: 13px;
    }

    .btn-procesar-scan {
        margin-top: 14px;
        min-height: 42px;
        padding: 9px 18px;
        border: 0;
        border-radius: 9px;
        background: #087bc2;
        color: white;
        font-weight: 800;
        cursor: pointer;
    }

    .btn-procesar-scan:disabled {
        opacity: .5;
        cursor: not-allowed;
    }

    .resultado {
        display: none;
        margin-top: 20px;
        padding: 18px;
        border-radius: 13px;
    }

    .resultado.ok {
        display: block;
        background: #eaf8ef;
        border: 1px solid #b8dfc5;
        color: #21633a;
    }

    .resultado.error {
        display: block;
        background: #fff0f0;
        border: 1px solid #efc1c1;
        color: #9d2f2f;
    }

    .resultado.alerta {
        display: block;
        background: #fff7dc;
        border: 1px solid #eed38a;
        color: #795c09;
    }

    .resultado h2 {
        margin: 0 0 10px;
        font-size: 20px;
    }

    .resultado-grid {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 8px 16px;
        margin-top: 12px;
    }

    .dato {
        padding: 8px 0;
        border-bottom: 1px solid rgba(0,0,0,.08);
    }

    .dato small {
        display: block;
        opacity: .72;
    }

    .dato strong {
        display: block;
        margin-top: 3px;
    }

    .scan-acciones {
        margin-top: 18px;
        display: flex;
        justify-content: center;
        gap: 10px;
    }

    .btn-historial-turno {
        padding: 10px 15px;
        border: 1px solid #0b82bd;
        border-radius: 9px;
        background: #087bc2;
        color: white;
        font-weight: 800;
        text-decoration: none;
    }

    .btn-historial-turno:hover {
        background: #066da4;
        color: white;
    }

    .btn-volver {
        padding: 10px 15px;
        border: 1px solid #cbd9e4;
        border-radius: 9px;
        background: white;
        color: #496273;
        font-weight: 800;
        text-decoration: none;
    }

    @@media (max-width: 650px) {
        .resultado-grid {
            grid-template-columns: 1fr;
        }
    }
</style>


<section class="scan-pagina">

    <div class="scan-encabezado">
        <h1>Entrega por escáner</h1>

        <p>
            Escanee el código DOS del paquete.
            Cada lectura confirmada descuenta una entrega.
        </p>
    </div>


    <div class="scan-panel"><div class="orbit-scan-station"><span class="orbit-eyebrow">PUNTO DE ENTREGA</span>
        <partial name="_OrbitScanner" />

        <form id="formScan" data-orbit-form="EntregaDosificacion">
            @Html.AntiForgeryToken()

            <div class="scan-caja">

                <label for="codigoScan">
                    ▥ Escanee la dosificación
                </label>

                <input type="text"
                       id="codigoScan"
                       class="scan-input"
                       autocomplete="off"
                       autofocus
                       placeholder="DOS-000001" />

                <div class="scan-ayuda">
                    El lector funciona como teclado.
                    Al recibir Enter, SARMedix aplica FEFO,
                    descuenta stock y genera historial.
                    También puede escribir el código y presionar Procesar.
                    SARMedix corrige automáticamente guiones leídos como apóstrofes por el lector.
                </div>

                <button type="button"
                        id="btnProcesarScan"
                        class="btn-procesar-scan" data-orbit-action="primary">
                    Procesar código
                </button>

            </div>
        </form>


        </div><section class="orbit-scan-feedback" aria-label="Resultado de la lectura"><span class="orbit-eyebrow">RESULTADO DE LA OPERACIÓN</span><div id="resultadoScan"
             class="resultado">
        </div>


        </section><div class="scan-acciones">
            <a asp-controller="Home"
               asp-action="HistorialSalidasTurno"
               class="btn-historial-turno" data-orbit-action="secondary">
                📊 Salidas del turno
            </a>

            <a asp-controller="Home"
               asp-action="Dosificaciones"
               class="btn-volver" data-orbit-action="secondary">
                Volver a Dosificaciones
            </a>
        </div>

    </div>

</section>


<script>
    const input =
        document.getElementById(
            "codigoScan"
        );


    const resultado =
        document.getElementById(
            "resultadoScan"
        );


    const btnProcesarScan =
        document.getElementById(
            "btnProcesarScan"
        );


    const token =
        document.querySelector(
            'input[name="__RequestVerificationToken"]'
        ).value;


    let procesando =
        false;


    function normalizarCodigoDosificacion(
        valor
    ) {

        let codigo =
            (valor ?? "")
                .trim()
                .toUpperCase();


        const posicionDos =
            codigo.indexOf(
                "DOS"
            );


        if (
            codigo.startsWith("]A")
            &&
            posicionDos >= 0
        ) {
            codigo =
                codigo.substring(
                    posicionDos
                );
        }


        codigo =
            codigo
                .replaceAll("*", "")
                .replaceAll(" ", "")
                .replaceAll("\r", "")
                .replaceAll("\n", "")
                .replaceAll("\t", "")
                .replaceAll("–", "-")
                .replaceAll("—", "-")
                .replaceAll("−", "-")
                .replaceAll("'", "-")
                .replaceAll("’", "-")
                .replaceAll("´", "-")
                .replaceAll("`", "-");


        if (
            codigo.startsWith("DOS")
            &&
            !codigo.startsWith("DOS-")
        ) {
            const resto =
                codigo
                    .substring(3)
                    .replace(/^-+/, "");


            if (/^\d+$/.test(resto)) {
                codigo =
                    "DOS-"
                    +
                    resto;
            }
        }


        return codigo;
    }



    async function procesarCodigo() {

        if (procesando) {
            return;
        }


        const codigo =
            normalizarCodigoDosificacion(
                input.value
            );


        input.value =
            codigo;


        if (!codigo) {
            return;
        }


        procesando =
            true;


        input.disabled =
            true;


        btnProcesarScan.disabled =
            true;


        resultado.className =
            "resultado";


        resultado.innerHTML =
            "Procesando entrega...";


        try {

            const body =
                new URLSearchParams();


            body.append(
                "__RequestVerificationToken",
                token
            );


            body.append(
                "codigo",
                codigo
            );


            const respuesta =
                await fetch(
                    '@Url.Action("ProcesarEntregaDosificacion", "Home")',
                    {
                        method: "POST",
                        headers: {
                            "Content-Type":
                                "application/x-www-form-urlencoded;charset=UTF-8"
                        },
                        body:
                            body.toString()
                    }
                );


            const datos =
                await respuesta.json();


            if (!datos.exito) {

                resultado.className =
                    "resultado error";


                resultado.innerHTML =
                    "<h2>✖ No se registró la entrega</h2>"
                    +
                    "<div>"
                    + (datos.mensaje ?? "Error desconocido.")
                    + "</div>";

                return;
            }


            const clase =
                datos.stockBajo
                    ? "resultado alerta"
                    : "resultado ok";


            const titulo =
                datos.stockBajo
                    ? "⚠ Entrega registrada · STOCK BAJO"
                    : "✓ Entrega registrada";


            resultado.className =
                clase;


            resultado.innerHTML =
                "<h2>"
                + titulo
                + "</h2>"
                +
                '<div class="resultado-grid">'
                +
                '<div class="dato"><small>Código</small><strong>'
                + datos.codigo
                + "</strong></div>"
                +
                '<div class="dato"><small>Medicamento</small><strong>'
                + datos.producto
                + (datos.concentracion
                    ? " " + datos.concentracion
                    : "")
                + "</strong></div>"
                +
                '<div class="dato"><small>Entrega</small><strong>'
                + datos.cantidad
                + " "
                + datos.unidad
                + "</strong></div>"
                +
                '<div class="dato"><small>Clínica</small><strong>'
                + datos.clinica
                + "</strong></div>"
                +
                '<div class="dato"><small>Stock</small><strong>'
                + datos.stockAnterior
                + " → "
                + datos.stockResultante
                + " "
                + datos.unidad
                + "</strong></div>"
                +
                '<div class="dato"><small>FEFO</small><strong>'
                + (datos.detalleLotes ?? "")
                + "</strong></div>"
                +
                "</div>"
                +
                (
                    datos.stockBajo
                        ? '<div style="margin-top:12px;font-weight:800;">Mínimo configurado: '
                            + datos.stockMinimo
                            + " "
                            + datos.unidad
                            + ". Se recomienda reponer la Clínica.</div>"
                        : ""
                );

        }
        catch {

            resultado.className =
                "resultado error";


            resultado.innerHTML =
                "<h2>✖ Error</h2>"
                +
                "<div>No fue posible procesar el código.</div>";
        }
        finally {

            input.value =
                "";


            input.disabled =
                false;


            btnProcesarScan.disabled =
                false;


            procesando =
                false;


            setTimeout(
                function () {
                    input.focus();
                },
                80
            );
        }
    }


    input.addEventListener(
        "keydown",
        function (evento) {

            if (evento.key === "Enter") {

                evento.preventDefault();

                procesarCodigo();
            }
        }
    );


    btnProcesarScan.addEventListener(
        "click",
        function () {
            procesarCodigo();
        }
    );


    window.addEventListener(
        "load",
        function () {
            input.focus();
        }
    );
</script>

LoginSARMedix/Views/Home/HistorialSalida.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "HistorialSalidasTurno"; ViewData["SmFamily"] = "history"; }
@using LoginSARMedix.Models
@model HistorialSalidasTurnoViewModel

@{
    ViewData["Title"] = "Salidas del turno";
    ViewData["TituloBarra"] = "Salidas del turno";

    int totalMovimientos =
        Model.resumen
            .SelectMany(r => r.detalles)
            .Select(d => d.id_movimiento)
            .Distinct()
            .Count();
}

<style>
    .turno-pagina {
        width: min(1180px, 94%);
        margin: 32px auto 55px;
    }

    .turno-encabezado {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        gap: 18px;
        margin-bottom: 18px;
    }

    .turno-encabezado h1 {
        margin: 0 0 6px;
        color: #17324d;
        font-size: 31px;
        font-weight: 900;
    }

    .turno-encabezado p {
        margin: 0;
        color: #607487;
    }

    .btn-volver-scan {
        padding: 10px 15px;
        border: 1px solid #c9d9e4;
        border-radius: 9px;
        background: white;
        color: #456175;
        text-decoration: none;
        font-weight: 800;
        white-space: nowrap;
    }

    .filtro-turno {
        padding: 18px;
        border-radius: 15px;
        background: rgba(255,255,255,.97);
        box-shadow: 0 10px 28px rgba(35,76,105,.12);
        margin-bottom: 18px;
    }

    .filtro-grid {
        display: grid;
        grid-template-columns: 1.15fr .8fr .8fr auto;
        gap: 12px;
        align-items: end;
    }

    .campo label {
        display: block;
        margin-bottom: 6px;
        color: #29465d;
        font-size: 13px;
        font-weight: 800;
    }

    .campo input {
        width: 100%;
        min-height: 42px;
        padding: 9px 11px;
        border: 1px solid #c8d8e4;
        border-radius: 9px;
        background: white;
        color: #17324d;
    }

    .btn-aplicar {
        min-height: 42px;
        padding: 9px 18px;
        border: 0;
        border-radius: 9px;
        background: #087bc2;
        color: white;
        font-weight: 850;
        cursor: pointer;
    }

    .presets {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        margin-top: 12px;
    }

    .preset {
        padding: 7px 11px;
        border: 1px solid #c7dbe8;
        border-radius: 999px;
        background: #f4faff;
        color: #236486;
        font-size: 12px;
        font-weight: 800;
        cursor: pointer;
    }

    .periodo {
        margin-top: 13px;
        padding: 11px 13px;
        border-radius: 9px;
        background: #eef8fd;
        color: #245b78;
        font-size: 13px;
    }

    .controlados-info {
        margin-top: 9px;
        color: #6d7f8d;
        font-size: 12px;
    }

    .metricas {
        display: grid;
        grid-template-columns: repeat(2, minmax(0,1fr));
        gap: 12px;
        margin-bottom: 18px;
    }

    .metrica {
        padding: 16px 18px;
        border: 1px solid #d7e6ef;
        border-radius: 13px;
        background: rgba(255,255,255,.95);
    }

    .metrica small {
        display: block;
        color: #6b8294;
        font-weight: 700;
    }

    .metrica strong {
        display: block;
        margin-top: 3px;
        color: #17324d;
        font-size: 24px;
    }

    .informe-sugerencia {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        margin-bottom: 18px;
        padding: 17px 18px;
        border: 1px solid #b9ddc6;
        border-radius: 14px;
        background: linear-gradient(135deg,#f2fbf5,#eef8ff);
        box-shadow: 0 8px 20px rgba(40,99,70,.08);
    }

    .informe-sugerencia strong {
        display: block;
        color: #20573a;
        font-size: 15px;
    }

    .informe-sugerencia span {
        display: block;
        margin-top: 4px;
        color: #60796b;
        font-size: 13px;
    }

    .btn-informe {
        padding: 11px 17px;
        border-radius: 9px;
        background: #1c8a55;
        color: white;
        text-decoration: none;
        font-weight: 850;
        white-space: nowrap;
    }

    .tabla-panel {
        overflow: hidden;
        border: 1px solid #d6e5ee;
        border-radius: 15px;
        background: rgba(255,255,255,.98);
        box-shadow: 0 10px 28px rgba(37,76,103,.10);
    }

    .tabla-titulo {
        padding: 17px 19px;
        border-bottom: 1px solid #dde9ef;
        background: linear-gradient(135deg,#0c668c,#0b8795);
        color: white;
    }

    .tabla-titulo h2 {
        margin: 0 0 3px;
        font-size: 19px;
    }

    .tabla-titulo p {
        margin: 0;
        opacity: .9;
        font-size: 12px;
    }

    .tabla-wrap {
        overflow-x: auto;
    }

    table {
        width: 100%;
        border-collapse: collapse;
        min-width: 780px;
    }

    th {
        padding: 12px 14px;
        background: #f3f8fb;
        border-bottom: 1px solid #dbe7ee;
        color: #557083;
        text-align: left;
        font-size: 11px;
        text-transform: uppercase;
        letter-spacing: .4px;
    }

    td {
        padding: 14px;
        border-bottom: 1px solid #edf2f5;
        color: #29465d;
        font-size: 13px;
    }

    tbody tr:last-child td {
        border-bottom: 0;
    }

    tbody tr:hover {
        background: #f8fcfe;
    }

    .producto {
        color: #17324d;
        font-weight: 900;
        font-size: 14px;
    }

    .concentracion {
        display: block;
        margin-top: 3px;
        color: #718797;
        font-size: 11px;
    }

    .cantidad-total {
        display: inline-flex;
        align-items: baseline;
        gap: 5px;
        padding: 7px 11px;
        border-radius: 10px;
        background: #eaf7fa;
        color: #0c7188;
        font-weight: 900;
    }

    .cantidad-total strong {
        font-size: 20px;
    }

    .badge-controlado {
        display: inline-block;
        padding: 4px 8px;
        border-radius: 999px;
        background: #fff0f2;
        color: #b23b4b;
        font-size: 11px;
        font-weight: 850;
    }

    .badge-normal {
        display: inline-block;
        padding: 4px 8px;
        border-radius: 999px;
        background: #edf7ef;
        color: #38724a;
        font-size: 11px;
        font-weight: 850;
    }

    .sin-salidas {
        padding: 42px 20px;
        border: 1px dashed #b9d3e3;
        border-radius: 14px;
        background: rgba(255,255,255,.9);
        color: #637d90;
        text-align: center;
    }

    @@media (max-width: 850px) {
        .filtro-grid,
        .metricas {
            grid-template-columns: 1fr;
        }

        .turno-encabezado,
        .informe-sugerencia {
            align-items: flex-start;
            flex-direction: column;
        }
    }
</style>

<section class="turno-pagina">

    <div class="turno-encabezado">
        <div>
            <h1>Salidas del turno</h1>
            <p>
                Consolidado de medicamentos entregados dentro del rango horario seleccionado.
            </p>
        </div>

        <a asp-controller="Home"
           asp-action="EntregaDosificacion"
           class="btn-volver-scan" data-orbit-action="secondary">
            ← Volver al escáner
        </a>
    </div>


    <form asp-controller="Home"
          asp-action="HistorialSalidasTurno"
          method="get"
          class="filtro-turno"
          id="formTurno" data-orbit-form="HistorialSalidasTurno">

        <fieldset class="orbit-turno-fields"><legend>Ventana de consulta</legend><div class="filtro-grid">

            <div class="campo">
                <label for="fecha">Día del turno</label>
                <input type="date"
                       id="fecha"
                       name="fecha"
                       value="@Model.fecha.ToString("yyyy-MM-dd")" />
            </div>

            <div class="campo">
                <label for="horaInicio">Desde</label>
                <input type="time"
                       id="horaInicio"
                       name="horaInicio"
                       value="@Model.hora_inicio" />
            </div>

            <div class="campo">
                <label for="horaFin">Hasta</label>
                <input type="time"
                       id="horaFin"
                       name="horaFin"
                       value="@Model.hora_fin" />
            </div>

            <button type="submit"
                    class="btn-aplicar" data-orbit-action="quiet">
                Aplicar corte
            </button>

        </div></fieldset>

        <div class="presets">
            <button type="button"
                    class="preset"
                    data-inicio="08:00"
                    data-fin="00:00" data-orbit-action="quiet">
                08:00 → 00:00
            </button>

            <button type="button"
                    class="preset"
                    data-inicio="08:00"
                    data-fin="20:00" data-orbit-action="quiet">
                08:00 → 20:00
            </button>

            <button type="button"
                    class="preset"
                    data-inicio="20:00"
                    data-fin="08:00" data-orbit-action="quiet">
                20:00 → 08:00
            </button>
        </div>

        <div class="periodo">
            <strong>Periodo consultado:</strong>
            @Model.inicio_real.ToString("dd/MM/yyyy HH:mm")
            →
            @Model.fin_real.ToString("dd/MM/yyyy HH:mm")

            @if (Model.fin_real.Date > Model.inicio_real.Date)
            {
                <span>
                    · el corte cruza medianoche
                </span>
            }
        </div>

        <div class="controlados-info">
            @if (Model.puede_ver_controlados)
            {
                <span>
                    🔐 Las salidas de medicamentos controlados están incluidas en este resumen.
                </span>
            }
            else
            {
                <span>
                    🔒 Los medicamentos controlados no se muestran con este perfil.
                </span>
            }
        </div>

    </form>


    <div class="metricas">

        <div class="metrica">
            <small>Medicamentos distintos</small>
            <strong>@Model.resumen.Count</strong>
        </div>

        <div class="metrica">
            <small>Registros de salida</small>
            <strong>@totalMovimientos</strong>
        </div>

    </div>


    @if (Model.resumen.Count > 0)
    {
        <div class="informe-sugerencia">

            <div>
                <strong>
                    ¿Desea descargar o presentar el informe de este corte?
                </strong>

                <span>
                    El informe muestra primero los totales por medicamento y al final el detalle cronológico por hora.
                </span>
            </div>

            <a asp-controller="Home"
               asp-action="InformeSalidasTurno"
               asp-route-fecha="@Model.fecha.ToString("yyyy-MM-dd")"
               asp-route-horaInicio="@Model.hora_inicio"
               asp-route-horaFin="@Model.hora_fin"
               target="_blank"
               class="btn-informe" data-orbit-action="secondary">
                📄 Generar informe
            </a>

        </div>
    }


    @if (Model.resumen.Count == 0)
    {
        <div class="sin-salidas">
            No se registraron salidas dentro de este rango horario.
        </div>
    }
    else
    {
        <section class="tabla-panel">

            <div class="tabla-titulo">
                <h2>Resumen total del corte</h2>
                <p>
                    Cantidad total entregada por medicamento durante el periodo seleccionado.
                </p>
            </div>

            <div class="tabla-wrap">

                <table data-orbit-table="HistorialSalidasTurno">

                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Medicamento</th>
                            <th>Total entregado</th>
                            <th>Unidad</th>
                            <th>Tipo</th>
                            <th>Registros</th>
                        </tr>
                    </thead>

                    <tbody>

                        @{
                            int numeroFila = 1;
                        }

                        @foreach (var item in Model.resumen)
                        {
                            <tr>
                                <td>
                                    @numeroFila
                                </td>

                                <td>
                                    <span class="producto">
                                        @item.nombre_producto
                                    </span>

                                    @if (!string.IsNullOrWhiteSpace(item.concentracion))
                                    {
                                        <span class="concentracion">
                                            @item.concentracion
                                        </span>
                                    }
                                </td>

                                <td>
                                    <span class="cantidad-total">
                                        <strong>@item.cantidad_total</strong>
                                        <span>@item.unidad_medida</span>
                                    </span>
                                </td>

                                <td>
                                    @item.unidad_medida
                                </td>

                                <td>
                                    @if (item.es_controlado)
                                    {
                                        <span class="badge-controlado">
                                            🔐 Controlado
                                        </span>
                                    }
                                    else
                                    {
                                        <span class="badge-normal">
                                            Salida clínica
                                        </span>
                                    }
                                </td>

                                <td>
                                    @item.detalles.Count
                                </td>
                            </tr>

                            numeroFila++;
                        }

                    </tbody>

                </table>

            </div>

        </section>
    }

</section>

<script>
    const inicio = document.getElementById("horaInicio");
    const fin = document.getElementById("horaFin");
    const formulario = document.getElementById("formTurno");

    document.querySelectorAll(".preset").forEach(function (boton) {
        boton.addEventListener("click", function () {
            inicio.value = boton.dataset.inicio;
            fin.value = boton.dataset.fin;
            formulario.submit();
        });
    });
</script>

LoginSARMedix/Views/Home/HistorialSector.text:
﻿@* SM-ORBITA-METADATA *@
@{
    ViewData["SmScreen"] = "HistorialSectores";
    ViewData["SmFamily"] = "history";
}

@using LoginSARMedix.Models
@model List<MovimientoSectorHistorial>

@{
    ViewData["Title"] = "Historial por sector";
    ViewData["TituloBarra"] = "Historial por sector";

    var ubicaciones =
        ViewBag.Ubicaciones as List<Ubicacion>
        ?? new List<Ubicacion>();

    int? idSeleccionado =
        ViewBag.IdUbicacion as int?;

    int cantidadRegistros =
        Model?.Count ?? 0;
}

<link rel="stylesheet"
      href="~/css/sarmedix-structural.css"
      asp-append-version="true" />

<link rel="stylesheet"
      href="~/css/sarmedix-refinement.css"
      asp-append-version="true" />


<!-- =========================================
     HISTORIAL POR SECTOR - ORBITA 2.0
     ========================================= -->

<section class="historial-card sm-reimagined sm-history-workspace historial-sectores-orbita">

    <!-- ENCABEZADO -->

    <header class="sm-history-heading">

        <span class="sm-workspace-symbol">

            <svg class="sm-icon"
                 viewBox="0 0 24 24"
                 aria-hidden="true">

                <use href="#sm-icon-movements" />

            </svg>

        </span>

        <div>

            <span class="sm-overline">
                ÓRBITA / TRAZABILIDAD
            </span>

            <h1>
                La memoria del sistema.
            </h1>

            <p>
                Cada movimiento, su responsable y su momento.
                Historial por sector.
            </p>

        </div>

    </header>


    <div class="sm-history-grid">

        <!-- =====================================
             PANEL DE BUSQUEDA DE SECTOR
             ===================================== -->

        <aside class="sm-history-console">

            <div class="sm-console-heading">

                <span class="sm-overline">
                    EXPLORAR REGISTROS
                </span>

                <h2>
                    Encuentra el contexto
                </h2>

                <p>
                    Selecciona una Bodega o Clínica para
                    revisar sus movimientos de inventario.
                </p>

            </div>


            <!-- SELECTOR DE SECTOR -->

            <form asp-controller="Home"
                  asp-action="HistorialSectores"
                  method="get"
                  class="form-sector-historial"
                  data-orbit-form="HistorialSectores">

                <div class="sector-filtro-campo">

                    <label for="sectorHistorial">
                        Sector
                    </label>

                    <select name="idUbicacion"
                            id="sectorHistorial"
                            required>

                        <option value=""
                                selected="@(!idSeleccionado.HasValue)">
                            Seleccione un sector...
                        </option>

                        @foreach (var ubicacion in ubicaciones)
                        {
                            <option value="@ubicacion.id_ubicacion"
                                    selected="@(idSeleccionado == ubicacion.id_ubicacion)">

                                @ubicacion.nombre_sector —
                                @(ubicacion.tipo_sector ?? "Sin tipo")

                            </option>
                        }

                    </select>

                </div>


                <button type="submit"
                        class="btn-ver-historial-sector"
                        data-orbit-action="primary">

                    Ver historial

                </button>

            </form>

        </aside>


        <!-- =====================================
             RESULTADOS
             ===================================== -->

        <section class="sm-history-ledger">

            <!-- RESUMEN DE REGISTROS -->

            <div class="historial-resumen-filtros">

                <span>

                    Movimientos mostrados:

                    <strong>
                        @cantidadRegistros
                    </strong>

                </span>

                @if (idSeleccionado.HasValue)
                {
                    var sectorSeleccionado =
                        ubicaciones.FirstOrDefault(
                            u => u.id_ubicacion == idSeleccionado.Value
                        );

                    if (sectorSeleccionado != null)
                    {
                        <span class="sector-resumen-nombre">

                            <span aria-hidden="true">
                                📍
                            </span>

                            @sectorSeleccionado.nombre_sector

                        </span>
                    }
                }

            </div>


            <!-- =====================================
                 TABLA DE MOVIMIENTOS
                 ===================================== -->

            <div class="tabla-wrap">

                @if (!idSeleccionado.HasValue)
                {
                    <div class="sector-sin-registros">

                        <span class="sector-vacio-icono">
                            🏥
                        </span>

                        <strong>
                            Selecciona un sector
                        </strong>

                        <p>
                            Elige una Bodega o Clínica para
                            consultar su historial de movimientos.
                        </p>

                    </div>
                }
                else if (Model == null || Model.Count == 0)
                {
                    <div class="sector-sin-registros">

                        <span class="sector-vacio-icono">
                            📋
                        </span>

                        <strong>
                            Sin movimientos registrados
                        </strong>

                        <p>
                            Este sector todavía no registra
                            movimientos en su historial.
                        </p>

                    </div>
                }
                else
                {
                    <table class="tabla-sectores-historial"
                           data-orbit-table="HistorialSectores">

                        <thead>

                            <tr>

                                <th scope="col">
                                    Fecha y hora
                                </th>

                                <th scope="col">
                                    Movimiento
                                </th>

                                <th scope="col">
                                    Producto
                                </th>

                                <th scope="col">
                                    Lote
                                </th>

                                <th scope="col">
                                    Cantidad
                                </th>

                                <th scope="col">
                                    Stock
                                </th>

                                <th scope="col">
                                    Responsable
                                </th>

                                <th scope="col">
                                    Detalle
                                </th>

                            </tr>

                        </thead>


                        <tbody>

                            @foreach (var mov in Model)
                            {
                                string tipoMovimiento =
                                    mov.tipo_movimiento?.ToString() ?? "";

                                bool esEntrada =
                                    tipoMovimiento.IndexOf(
                                        "entrada",
                                        StringComparison.OrdinalIgnoreCase
                                    ) >= 0;

                                bool esSalida =
                                    tipoMovimiento.IndexOf(
                                        "salida",
                                        StringComparison.OrdinalIgnoreCase
                                    ) >= 0;

                                string claseMovimiento =
                                    esEntrada
                                        ? "sector-tipo-entrada"
                                        : esSalida
                                            ? "sector-tipo-salida"
                                            : "sector-tipo-otro";

                                string iconoMovimiento =
                                    esEntrada
                                        ? "↑"
                                        : esSalida
                                            ? "↓"
                                            : "↔";

                                <tr>

                                    <!-- FECHA Y HORA -->

                                    <td>

                                        <div class="sector-fecha">

                                            <strong>
                                                @mov.fecha_hora.ToString("dd-MM-yyyy")
                                            </strong>

                                            <span>
                                                @mov.fecha_hora.ToString("HH:mm:ss")
                                            </span>

                                        </div>

                                    </td>


                                    <!-- TIPO DE MOVIMIENTO -->

                                    <td>

                                        <span class="sector-tipo @claseMovimiento">

                                            <span aria-hidden="true">
                                                @iconoMovimiento
                                            </span>

                                            @tipoMovimiento

                                        </span>

                                    </td>


                                    <!-- PRODUCTO -->

                                    <td>

                                        <div class="sector-producto">

                                            <span class="sector-producto-icono"
                                                  aria-hidden="true">
                                                💊
                                            </span>

                                            <strong>
                                                @mov.producto
                                            </strong>

                                        </div>

                                    </td>


                                    <!-- LOTE -->

                                    <td>

                                        <span class="sector-lote">
                                            @mov.lote
                                        </span>

                                    </td>


                                    <!-- CANTIDAD -->

                                    <td>

                                        <div class="sector-cantidad">

                                            <strong>
                                                @mov.cantidad
                                            </strong>

                                            <span>
                                                @mov.unidad_medida
                                            </span>

                                        </div>

                                    </td>


                                    <!-- STOCK ANTERIOR Y RESULTANTE -->

                                    <td>

                                        <div class="sector-stock">

                                            <span class="sector-stock-anterior">
                                                @mov.stock_anterior
                                            </span>

                                            <span class="sector-stock-flecha"
                                                  aria-hidden="true">
                                                →
                                            </span>

                                            <span class="sector-stock-resultante">
                                                @mov.stock_resultante
                                            </span>

                                        </div>

                                    </td>


                                    <!-- RESPONSABLE -->

                                    <td>

                                        <div class="sector-responsable">

                                            <span class="sector-responsable-icono"
                                                  aria-hidden="true">
                                                👤
                                            </span>

                                            <span>
                                                @mov.responsable
                                            </span>

                                        </div>

                                    </td>


                                    <!-- OBSERVACION -->

                                    <td>

                                        <div class="sector-detalle">

                                            <span class="sector-detalle-etiqueta">
                                                DETALLE DEL MOVIMIENTO
                                            </span>

                                            <p>
                                                @if (!string.IsNullOrWhiteSpace(mov.observacion))
                                                {
                                                    @mov.observacion
                                                }
                                                else
                                                {
                                                    <span class="sector-sin-observacion">
                                                        Sin observación registrada
                                                    </span>
                                                }
                                            </p>

                                        </div>

                                    </td>

                                </tr>
                            }

                        </tbody>

                    </table>
                }

            </div>

        </section>

    </div>

</section>


<!-- =========================================
     ESTILOS HISTORIAL POR SECTOR
     ========================================= -->

<style>

    /* CONTENEDOR PRINCIPAL */

    body.sm-app .historial-sectores-orbita {
        display: block !important;
        width: 100% !important;
        max-width: 1500px !important;
        min-width: 0 !important;
        margin: 5px auto !important;
        box-sizing: border-box;
        overflow: visible !important;
    }


        /* COMPOSICION VERTICAL */

        body.sm-app .historial-sectores-orbita
        .sm-history-grid {
            display: flex !important;
            flex-direction: column !important;
            align-items: stretch !important;
            gap: 18px !important;
            width: 100% !important;
            min-width: 0 !important;
        }


        /* =====================================
           PANEL DE FILTROS
           ===================================== */

        body.sm-app .historial-sectores-orbita
        .sm-history-console {
            display: block !important;
            width: 100% !important;
            max-width: none !important;
            min-width: 0 !important;
            height: auto !important;
            margin: 0 !important;
            padding: 20px 22px !important;
            border: 1px solid #bdd1eb !important;
            border-radius: 18px !important;
            background: linear-gradient( 135deg, #eef5ff, #e7f0ff ) !important;
            box-sizing: border-box;
        }


        body.sm-app .historial-sectores-orbita
        .sm-console-heading {
            margin: 0 0 16px !important;
            padding: 0 0 12px !important;
            border-bottom: 1px solid #cadaf0 !important;
        }


            body.sm-app .historial-sectores-orbita
            .sm-console-heading h2 {
                margin: 3px 0 4px;
                font-size: 20px;
                color: #173d69;
            }


            body.sm-app .historial-sectores-orbita
            .sm-console-heading p {
                margin: 0;
                color: #526f8f;
            }


        /* =====================================
           SELECTOR DE SECTOR
           ===================================== */

        body.sm-app .historial-sectores-orbita
        .form-sector-historial {
