     ========================================= -->

<script>

    // OCULTAR MENSAJE DESPUES DE 3 SEGUNDOS

    setTimeout(
        function () {

            const mensaje =
                document.getElementById("mensajeLogin");

            if (mensaje) {

                mensaje.style.opacity = "0";

                setTimeout(
                    function () {

                        mensaje.style.visibility = "hidden";

                    },
                    500
                );

            }

        },
        3000
    );

</script>

LoginSARMedix/Views/Home/InformeSalidasT.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "InformeSalidasTurno"; ViewData["SmFamily"] = "history"; }
@using LoginSARMedix.Models
@model HistorialSalidasTurnoViewModel

@{
    Layout = null;

    string generadoPor =
        ViewBag.GeneradoPor?.ToString()
        ?? "";

    string rolGenerador =
        ViewBag.RolGenerador?.ToString()
        ?? "";

    DateTime fechaGeneracion =
        ViewBag.FechaGeneracion is DateTime
            ? (DateTime)ViewBag.FechaGeneracion
            : DateTime.Now;

    var detalles =
        Model.resumen
            .SelectMany(r => r.detalles)
            .OrderBy(d => d.fecha_hora)
            .ThenBy(d => d.nombre_producto)
            .ToList();

    int totalMovimientos =
        detalles
            .Select(d => d.id_movimiento)
            .Distinct()
            .Count();
}

<!DOCTYPE html>

<html lang="es">

<head>

    <meta charset="utf-8" />

    <meta name="viewport"
          content="width=device-width, initial-scale=1" />

    <title>
        Informe de salidas por turno
    </title>


    <style id="estilosInforme">

        * {
            box-sizing: border-box;
        }

        body {
            margin: 0;
            padding: 28px;
            background: #eef3f6;
            color: #20384a;
            font-family:
                Arial,
                Helvetica,
                sans-serif;
        }

        .acciones-informe {
            width: min(1050px, 100%);
            margin: 0 auto 14px;
            display: flex;
            justify-content: flex-end;
            gap: 9px;
        }

        .acciones-informe button,
        .acciones-informe a {
            padding: 10px 15px;
            border-radius: 8px;
            font-size: 13px;
            font-weight: 800;
            text-decoration: none;
            cursor: pointer;
        }

        .btn-volver {
            border: 1px solid #c6d5de;
            background: white;
            color: #456175;
        }

        .btn-descargar {
            border: 0;
            background: #1b8755;
            color: white;
        }

        .btn-imprimir {
            border: 0;
            background: #087bc2;
            color: white;
        }

        .documento {
            width: min(1050px, 100%);
            margin: 0 auto;
            padding: 38px 42px;
            background: white;
            box-shadow:
                0 12px 32px
                rgba(36, 69, 91, .13);
        }

        .cabecera {
            display: flex;
            justify-content: space-between;
            gap: 25px;
            padding-bottom: 20px;
            border-bottom: 3px solid #0c7898;
        }

        .marca {
            color: #087bc2;
            font-size: 15px;
            font-weight: 900;
            letter-spacing: .5px;
        }

        h1 {
            margin: 7px 0 4px;
            color: #17324d;
            font-size: 28px;
        }

        .subtitulo {
            margin: 0;
            color: #667d8d;
            font-size: 13px;
        }

        .folio {
            min-width: 210px;
            text-align: right;
            color: #5e7484;
            font-size: 12px;
            line-height: 1.6;
        }

        .datos-corte {
            display: grid;
            grid-template-columns:
                repeat(
                    4,
                    minmax(0, 1fr)
                );
            gap: 10px;
            margin: 22px 0;
        }

        .dato {
            padding: 12px 13px;
            border: 1px solid #d9e5ec;
            border-radius: 9px;
            background: #f8fbfd;
        }

        .dato small {
            display: block;
            color: #738897;
            font-size: 10px;
            font-weight: 800;
            text-transform: uppercase;
        }

        .dato strong {
            display: block;
            margin-top: 4px;
            color: #17324d;
            font-size: 13px;
        }

        .seccion {
            margin-top: 28px;
        }

        .seccion-titulo {
            margin-bottom: 10px;
        }

        .seccion-titulo h2 {
            margin: 0 0 3px;
            color: #17324d;
            font-size: 19px;
        }

        .seccion-titulo p {
            margin: 0;
            color: #718493;
            font-size: 11px;
        }

        .tabla-wrap {
            overflow-x: auto;
        }

        table {
            width: 100%;
            border-collapse: collapse;
        }

        th {
            padding: 10px 9px;
            background: #0d6d8e;
            color: white;
            text-align: left;
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: .35px;
        }

        td {
            padding: 10px 9px;
            border-bottom: 1px solid #e4ebef;
            color: #314c5f;
            font-size: 11px;
            vertical-align: top;
        }

        tbody tr:nth-child(even) {
            background: #f8fbfc;
        }

        .nombre-med {
            color: #17324d;
            font-weight: 900;
        }

        .conc {
            display: block;
            margin-top: 2px;
            color: #788d9a;
            font-size: 10px;
        }

        .total {
            font-size: 15px;
            font-weight: 900;
            color: #0d7189;
        }

        .controlado {
            display: inline-block;
            padding: 3px 6px;
            border-radius: 999px;
            background: #fff0f2;
            color: #ae3a49;
            font-size: 9px;
            font-weight: 800;
        }

        .normal {
            display: inline-block;
            padding: 3px 6px;
            border-radius: 999px;
            background: #edf7ef;
            color: #3c714a;
            font-size: 9px;
            font-weight: 800;
        }

        .resumen-nota {
            margin-top: 10px;
            padding: 10px 12px;
            border-left: 4px solid #0b8098;
            background: #eff8fb;
            color: #4d6879;
            font-size: 10px;
            line-height: 1.45;
        }

        .pie {
            display: flex;
            justify-content: space-between;
            gap: 20px;
            margin-top: 34px;
            padding-top: 15px;
            border-top: 1px solid #dce6eb;
            color: #71828e;
            font-size: 9px;
        }

        .sin-datos {
            padding: 25px;
            border: 1px dashed #bfd1dc;
            background: #f9fcfd;
            color: #728795;
            text-align: center;
        }

        @@media print {

            body {
                padding: 0;
                background: white;
            }

            .acciones-informe {
                display: none !important;
            }

            .documento {
                width: 100%;
                max-width: none;
                padding: 20px;
                box-shadow: none;
            }

            .seccion {
                break-inside: avoid;
            }

            table {
                page-break-inside: auto;
            }

            tr {
                page-break-inside: avoid;
                page-break-after: auto;
            }

        }

        @@media (max-width: 800px) {

            body {
                padding: 12px;
            }

            .documento {
                padding: 22px;
            }

            .cabecera {
                flex-direction: column;
            }

            .folio {
                text-align: left;
            }

            .datos-corte {
                grid-template-columns:
                    repeat(
                        2,
                        minmax(0, 1fr)
                    );
            }

        }

    </style>

<!-- SM-ORBITA-STANDALONE -->
<link rel="stylesheet" href="~/css/sarmedix-system.css" asp-append-version="true" />
</head>


<body class="sm-standalone" data-sm-family="history" data-sm-screen="InformeSalidasTurno">


    <div class="acciones-informe">

        <a href="javascript:history.back();"
           class="btn-volver" data-orbit-action="secondary">
            ← Volver
        </a>

        <a asp-controller="Home"
           asp-action="DescargarInformeSalidasTurno"
           asp-route-fecha="@Model.fecha.ToString("yyyy-MM-dd")"
           asp-route-horaInicio="@Model.hora_inicio"
           asp-route-horaFin="@Model.hora_fin"
           class="btn-descargar" data-orbit-action="secondary">
            ⬇ Descargar informe
        </a>

        <button type="button"
                class="btn-imprimir"
                onclick="window.print()" data-orbit-action="primary">
            🖨 Imprimir / Guardar PDF
        </button>

    </div>



    <main id="informeDocumento"
          class="documento">


        <header class="cabecera">

            <div>

                <div class="marca">
                    SARMedix · SAR de Chiguay
                </div>

                <h1>
                    Informe de salidas por turno
                </h1>

                <p class="subtitulo">
                    Consolidado de medicamentos entregados durante el periodo seleccionado.
                </p>

            </div>


            <div class="folio">

                <div>
                    <strong>Generado:</strong>
                    @fechaGeneracion.ToString("dd/MM/yyyy HH:mm")
                </div>

                <div>
                    <strong>Responsable:</strong>
                    @(string.IsNullOrWhiteSpace(generadoPor) ? "-" : generadoPor)
                </div>

                <div>
                    <strong>Perfil:</strong>
                    @(string.IsNullOrWhiteSpace(rolGenerador) ? "-" : rolGenerador)
                </div>

            </div>

        </header>



        <section class="datos-corte">

            <div class="dato">
                <small>Inicio del corte</small>
                <strong>
                    @Model.inicio_real.ToString("dd/MM/yyyy HH:mm")
                </strong>
            </div>

            <div class="dato">
                <small>Fin del corte</small>
                <strong>
                    @Model.fin_real.ToString("dd/MM/yyyy HH:mm")
                </strong>
            </div>

            <div class="dato">
                <small>Medicamentos distintos</small>
                <strong>
                    @Model.resumen.Count
                </strong>
            </div>

            <div class="dato">
                <small>Registros de salida</small>
                <strong>
                    @totalMovimientos
                </strong>
            </div>

        </section>



        <section class="seccion">

            <div class="seccion-titulo">

                <h2>
                    1. Resumen total de salidas
                </h2>

                <p>
                    Totales consolidados por medicamento.
                </p>

            </div>


            @if (Model.resumen.Count == 0)
            {
                <div class="sin-datos">
                    No existen salidas para el periodo consultado.
                </div>
            }
            else
            {
                <div class="tabla-wrap">

                    <table>

                        <thead>

                            <tr>
                                <th>#</th>
                                <th>Medicamento</th>
                                <th>Total</th>
                                <th>Unidad</th>
                                <th>Tipo</th>
                                <th>Registros</th>
                            </tr>

                        </thead>


                        <tbody>

                            @{
                                int numero = 1;
                            }

                            @foreach (var item in Model.resumen)
                            {
                                <tr>

                                    <td>
                                        @numero
                                    </td>

                                    <td>
                                        <span class="nombre-med">
                                            @item.nombre_producto
                                        </span>

                                        @if (!string.IsNullOrWhiteSpace(item.concentracion))
                                        {
                                            <span class="conc">
                                                @item.concentracion
                                            </span>
                                        }
                                    </td>

                                    <td>
                                        <span class="total">
                                            @item.cantidad_total
                                        </span>
                                    </td>

                                    <td>
                                        @item.unidad_medida
                                    </td>

                                    <td>
                                        @if (item.es_controlado)
                                        {
                                            <span class="controlado">
                                                Controlado
                                            </span>
                                        }
                                        else
                                        {
                                            <span class="normal">
                                                Salida clínica
                                            </span>
                                        }
                                    </td>

                                    <td>
                                        @item.detalles.Count
                                    </td>

                                </tr>

                                numero++;
                            }

                        </tbody>

                    </table>

                </div>
            }


            <div class="resumen-nota">
                Los totales representan la suma de las cantidades entregadas dentro del horario seleccionado.
                Los medicamentos controlados se incluyen únicamente cuando el perfil que genera el informe tiene autorización.
            </div>

        </section>



        <section class="seccion">

            <div class="seccion-titulo">

                <h2>
                    2. Detalle cronológico por hora
                </h2>

                <p>
                    Respaldo de cada salida registrada durante el corte.
                </p>

            </div>


            @if (detalles.Count == 0)
            {
                <div class="sin-datos">
                    No existen movimientos para mostrar.
                </div>
            }
            else
            {
                <div class="tabla-wrap">

                    <table>

                        <thead>

                            <tr>
                                <th>Hora</th>
                                <th>Medicamento</th>
                                <th>Cantidad</th>
                                <th>Tipo</th>
                                <th>Sector</th>
                                <th>Responsable</th>
                                <th>Lote(s)</th>
                            </tr>

                        </thead>


                        <tbody>

                            @foreach (var detalle in detalles)
                            {
                                <tr>

                                    <td>
                                        @detalle.fecha_hora.ToString("dd/MM HH:mm")
                                    </td>

                                    <td>
                                        <span class="nombre-med">
                                            @detalle.nombre_producto
                                        </span>

                                        @if (!string.IsNullOrWhiteSpace(detalle.concentracion))
                                        {
                                            <span class="conc">
                                                @detalle.concentracion
                                            </span>
                                        }
                                    </td>

                                    <td>
                                        @detalle.cantidad
                                        @detalle.unidad_medida
                                    </td>

                                    <td>
                                        @detalle.tipo_salida
                                    </td>

                                    <td>
                                        @detalle.sector
                                    </td>

                                    <td>
                                        @detalle.responsable
                                    </td>

                                    <td>
                                        @detalle.lotes
                                    </td>

                                </tr>
                            }

                        </tbody>

                    </table>

                </div>
            }

        </section>



        <footer class="pie">

            <span>
                Informe generado automáticamente por SARMedix.
            </span>

            <span>
                Periodo:
                @Model.inicio_real.ToString("dd/MM/yyyy HH:mm")
                →
                @Model.fin_real.ToString("dd/MM/yyyy HH:mm")
            </span>

        </footer>


    </main>
<link rel="stylesheet" href="~/css/sarmedix-global.css" asp-append-version="true" />
</body>

</html>

LoginSARMedix/Views/Home/InventarioUbica.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "InventarioUbicacion"; ViewData["SmFamily"] = "sectors"; }
@using LoginSARMedix.Models
@model List<Lote>

@{
    ViewData["Title"] = "Inventario de ubicación";
    ViewData["TituloBarra"] = "Inventario de ubicación";

    string nombreUbicacion =
        ViewBag.NombreUbicacion?.ToString()
        ?? "Ubicación";

    bool ubicacionActiva =
        ViewBag.UbicacionActiva != null
        &&
        Convert.ToBoolean(
            ViewBag.UbicacionActiva
        );

    DateTime hoy =
        DateTime.Today;

    DateTime limiteVencimiento =
        hoy.AddDays(30);


    int totalUnidades =
        Model
            .Sum(
                lote =>
                    lote.cantidad_actual
            );


    int totalProductos =
        Model
            .Where(
                lote =>
                    lote.cantidad_actual > 0
            )
            .Select(
                lote =>
                    lote.id_producto
            )
            .Distinct()
            .Count();


    int totalLotes =
        Model.Count;


    int totalVencidos =
        Model.Count(
            lote =>
                lote.cantidad_actual > 0
                &&
                lote.fecha_vencimiento.HasValue
                &&
                lote.fecha_vencimiento.Value.Date < hoy
        );
}


<style>

    /* =========================================================
       PAGINA
       ========================================================= */

    .inventario-ubicacion-pagina {
        width: 100%;
        max-width: 1450px;
        margin: 0 auto;
        padding: 10px 10px 30px;
    }


    /* =========================================================
       ENCABEZADO
       ========================================================= */

    .inventario-encabezado {
        margin-bottom: 22px;
    }


    .inventario-volver {
        display: inline-flex;
        align-items: center;
        gap: 7px;

        margin-bottom: 18px;

        color: #176dad;
        font-size: 14px;
        font-weight: 650;

        text-decoration: none;
    }


    .inventario-volver:hover {
        color: #0c568d;
    }


    .inventario-encabezado-superior {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
    }


    .inventario-encabezado h1 {
        margin: 0;

        color: #093b62;

        font-size: 32px;
        font-weight: 750;
    }


    .inventario-encabezado p {
        margin: 7px 0 0;

        color: #657d90;

        font-size: 15px;
    }


    /* =========================================================
       ESTADO UBICACION
       ========================================================= */

    .inventario-estado {
        padding: 7px 13px;

        border-radius: 20px;

        font-size: 13px;
        font-weight: 700;

        white-space: nowrap;
    }


    .inventario-estado-activa {
        background: #e1f5e7;
        color: #17733a;
    }


    .inventario-estado-inactiva {
        background: #eeeeee;
        color: #606b73;
    }


    /* =========================================================
       RESUMEN
       ========================================================= */

    .inventario-resumen {
        display: grid;

        grid-template-columns:
            repeat(4, minmax(0, 1fr));

        gap: 15px;

        margin-bottom: 23px;
    }


    .inventario-resumen-card {
        padding: 18px;

        display: flex;
        align-items: center;
        gap: 14px;

        border: 1px solid #dce7ed;
        border-radius: 12px;

        background: rgba(
            255,
            255,
            255,
            0.96
        );

        box-shadow:
            0 7px 18px
            rgba(20, 70, 100, 0.08);
    }


    .inventario-resumen-icono {
        width: 46px;
        height: 46px;

        display: flex;
        align-items: center;
        justify-content: center;

        border-radius: 12px;

        background: #e8f4fc;

        font-size: 23px;
    }


    .inventario-resumen-numero {
        display: block;

        color: #103c5e;

        font-size: 22px;
        font-weight: 750;
    }


    .inventario-resumen-texto {
        display: block;

        margin-top: 2px;

        color: #718696;

        font-size: 13px;
    }


    /* =========================================================
       TABLA
       ========================================================= */

    .inventario-tabla-contenedor {
        overflow-x: auto;

        border: 1px solid #d9e5ec;
        border-radius: 12px;

        background: rgba(
            255,
            255,
            255,
            0.97
        );

        box-shadow:
            0 9px 25px
            rgba(20, 65, 95, 0.09);
    }


    .inventario-tabla {
        width: 100%;

        border-collapse: collapse;
    }


    .inventario-tabla th {
        padding: 15px 17px;

        background: #eef6fb;

        color: #31556f;

        font-size: 13px;
        font-weight: 700;

        text-align: left;

        border-bottom:
            1px solid #d8e5ed;
    }


    .inventario-tabla td {
        padding: 15px 17px;

        color: #27475d;

        font-size: 14px;

        border-bottom:
            1px solid #edf2f5;
    }


    .inventario-tabla tbody tr:last-child td {
        border-bottom: none;
    }


    .inventario-tabla tbody tr:hover {
        background: #f7fbfd;
    }


    .inventario-producto {
        color: #123d5e;
        font-weight: 700;
    }


    .inventario-stock {
        font-weight: 700;
    }


    /* =========================================================
       ESTADOS DEL LOTE
       ========================================================= */

    .inventario-lote-estado {
        display: inline-flex;
        align-items: center;

        padding: 6px 9px;

        border-radius: 7px;

        font-size: 12px;
        font-weight: 700;
    }


    .estado-normal {
        background: #e1f5e7;
        color: #17733a;
    }


    .estado-proximo {
        background: #fff0dd;
        color: #b85c00;
    }


    .estado-vencido {
        background: #fde5e5;
        color: #b42318;
    }


    .estado-sin-stock {
        background: #eeeeee;
        color: #66727b;
    }


    /* =========================================================
       SIN INVENTARIO
       ========================================================= */

    .inventario-vacio {
        padding: 45px 25px;

        text-align: center;

        border: 1px solid #dce6ed;
        border-radius: 12px;

        background: rgba(
            255,
            255,
            255,
            0.95
        );
    }


    .inventario-vacio-icono {
        display: block;

        margin-bottom: 10px;

        font-size: 40px;
    }


    .inventario-vacio h3 {
        margin: 0 0 7px;

        color: #123a5d;

        font-size: 20px;
    }


    .inventario-vacio p {
        margin: 0;

        color: #718696;

        font-size: 14px;
    }


    /* =========================================================
       RESPONSIVE
       ========================================================= */

    @@media (max-width: 950px) {

        .inventario-resumen {
            grid-template-columns:
                repeat(2, minmax(0, 1fr));
        }

    }


    @@media (max-width: 600px) {

        .inventario-resumen {
            grid-template-columns: 1fr;
        }


        .inventario-encabezado-superior {
            align-items: flex-start;
            flex-direction: column;
        }

    }

</style>


<div class="inventario-ubicacion-pagina">


    <!-- =========================================================
         ENCABEZADO
         ========================================================= -->

    <section class="inventario-encabezado">


        <a asp-controller="Home"
           asp-action="Ubicaciones"
           class="inventario-volver" data-orbit-action="secondary">

            ← Volver a ubicaciones

        </a>


        <div class="inventario-encabezado-superior">


            <div>

                <h1>
                    @nombreUbicacion
                </h1>


                <p>
                    Inventario registrado actualmente
                    en esta ubicación.
                </p>

            </div>


            @if (ubicacionActiva)
            {
                <span class="inventario-estado inventario-estado-activa">

                    ● Ubicación activa

                </span>
            }
            else
            {
                <span class="inventario-estado inventario-estado-inactiva">

                    ● Ubicación inactiva

                </span>
            }


        </div>


    </section>


    <!-- =========================================================
         RESUMEN
         ========================================================= -->

    <section class="inventario-resumen">


        <article class="inventario-resumen-card">

            <span class="inventario-resumen-icono">
                📦
            </span>

            <div>

                <span class="inventario-resumen-numero">
                    @totalUnidades
                </span>

                <span class="inventario-resumen-texto">
                    Unidades
                </span>

            </div>

        </article>


        <article class="inventario-resumen-card">

            <span class="inventario-resumen-icono">
                💊
            </span>

            <div>

                <span class="inventario-resumen-numero">
                    @totalProductos
                </span>

                <span class="inventario-resumen-texto">
                    Productos con stock
                </span>

            </div>

        </article>


        <article class="inventario-resumen-card">

            <span class="inventario-resumen-icono">
                🧾
            </span>

            <div>

                <span class="inventario-resumen-numero">
                    @totalLotes
                </span>

                <span class="inventario-resumen-texto">
                    Lotes registrados
                </span>

            </div>

        </article>


        <article class="inventario-resumen-card">

            <span class="inventario-resumen-icono">
                ⚠
            </span>

            <div>

                <span class="inventario-resumen-numero">
                    @totalVencidos
                </span>

                <span class="inventario-resumen-texto">
                    Lotes vencidos con stock
                </span>

            </div>

        </article>


    </section>


    <!-- =========================================================
         INVENTARIO
         ========================================================= -->

    @if (Model != null && Model.Any())
    {

        <div class="inventario-tabla-contenedor">

            <table class="inventario-tabla" data-orbit-table="InventarioUbicacion"><caption class="orbit-table-caption">Existencias · Lote, cantidad y vigencia</caption>


                <thead>

                    <tr>

                        <th>
                            Producto
                        </th>

                        <th>
                            N° lote
                        </th>

                        <th>
                            Stock
                        </th>

                        <th>
                            Vencimiento
                        </th>

                        <th>
                            Estado
                        </th>

                    </tr>

                </thead>


                <tbody>


                    @foreach (var lote in Model)
                    {

                        string estadoTexto;
                        string estadoClase;


                        if (lote.cantidad_actual <= 0)
                        {
                            estadoTexto =
                                "Sin stock";

                            estadoClase =
                                "estado-sin-stock";
                        }
                        else if (
                            lote.fecha_vencimiento.HasValue
                            &&
                            lote.fecha_vencimiento.Value.Date < hoy
                        )
                        {
                            estadoTexto =
                                "Vencido";

                            estadoClase =
                                "estado-vencido";
                        }
                        else if (
                            lote.fecha_vencimiento.HasValue
                            &&
                            lote.fecha_vencimiento.Value.Date
                                <= limiteVencimiento
                        )
                        {
                            estadoTexto =
                                "Próximo a vencer";

                            estadoClase =
                                "estado-proximo";
                        }
                        else
                        {
                            estadoTexto =
                                "Normal";

                            estadoClase =
                                "estado-normal";
                        }


                        <tr>


                            <td class="inventario-producto">

                                @lote.nombre_producto

                            </td>


                            <td>

                                @lote.numero_lote

                            </td>


                            <td class="inventario-stock">

                                @lote.cantidad_actual

                            </td>


                            <td>

                                @(
                                    lote.fecha_vencimiento.HasValue
                                    ?
                                    lote.fecha_vencimiento.Value
                                        .ToString("dd/MM/yyyy")
                                    :
                                    "Sin fecha"
                                )

                            </td>


                            <td>

                                <span class="inventario-lote-estado @estadoClase">

                                    @estadoTexto

                                </span>

                            </td>


                        </tr>

                    }


                </tbody>


            </table>

        </div>

    }
    else
    {

        <div class="inventario-vacio">

            <span class="inventario-vacio-icono">
                📦
            </span>

            <h3>
                Esta ubicación está vacía
            </h3>

            <p>
                Actualmente no existen lotes
                registrados en esta ubicación.
            </p>

        </div>

    }


</div>

LoginSARMedix/Views/Home/ListadoEliminar.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "ListadoEliminarUsuarios"; ViewData["SmFamily"] = "users"; }
@model List<LoginSARMedix.Models.Usuario>

@{
    ViewData["Title"] = "Usuarios Inactivos";
    ViewData["TituloBarra"] = "Usuarios Inactivos";
}

<div class="usuarios-card">

    <div class="usuarios-titulo">
        <h1>Usuarios inactivos</h1>
        <p>Administración de usuarios desactivados</p>
    </div>


    @if (TempData["Mensaje"] != null)
    {
        string tipoMensaje =
            TempData["TipoMensaje"]?.ToString() ?? "";

        <div class="mensaje @(tipoMensaje == "exito" ? "mensaje-exito" : "mensaje-error")">
            @TempData["Mensaje"]
        </div>
    }


    @if (Model != null && Model.Count > 0)
    {
        <div class="tabla-contenedor">

            <table class="tabla-usuarios" data-orbit-table="ListadoEliminarUsuarios"><caption class="orbit-table-caption">Usuarios inactivos · Gestión de acceso</caption>

                <thead>
                    <tr>
                        <th>Nombre</th>
                        <th>Apellido</th>
                        <th>RUT</th>
                        <th>Usuario</th>
                        <th>Rol</th>
                        <th>Estado</th>
                        <th>Acciones</th>
                    </tr>
                </thead>

                <tbody>

                    @foreach (var usuario in Model)
                    {
                        <tr>

                            <td>
                                @usuario.nombre
                            </td>

                            <td>
                                @usuario.apellido
                            </td>

                            <td>
                                @usuario.rut
                            </td>

                            <td>
                                @usuario.nombre_usuario
                            </td>

                            <td>
                                @usuario.rol
                            </td>

                            <td>

                                <span class="estado-inactivo">
                                    Inactivo
                                </span>

                            </td>

                            <td>

                                <div class="acciones-usuario">

                                    <form asp-controller="Home"
                                          asp-action="ReactivarUsuario"
                                          method="post"
                                          onsubmit="return confirmarReactivar(this)" data-orbit-form="ListadoEliminarUsuarios">

                                        <input type="hidden"
                                               name="idUsuario"
                                               value="@usuario.id_usuario" />

                                        <button type="submit"
                                                class="btn-reactivar" data-orbit-action="primary">

                                            Reactivar

                                        </button>

                                    </form>


                                    <form asp-controller="Home"
                                          asp-action="EliminarUsuario"
                                          method="post"
                                          onsubmit="return confirmarEliminar(this)" data-orbit-form="ListadoEliminarUsuarios">

                                        <input type="hidden"
                                               name="idUsuario"
                                               value="@usuario.id_usuario" />

                                        <button type="submit"
                                                class="btn-eliminar" data-orbit-action="danger">

                                            Eliminar

                                        </button>

                                    </form>

                                </div>

                            </td>

                        </tr>
                    }

                </tbody>

            </table>

        </div>
    }
    else
    {
        <div class="sin-usuarios">
            No existen usuarios inactivos.
        </div>
    }

</div>



<div class="contenedor-navegacion">

    <a asp-controller="Home"
       asp-action="Usuarios"
       class="btn-listado" data-orbit-action="secondary">

        ← Volver al Listado de Usuarios

    </a>


    <a asp-controller="Home"
       asp-action="UsuariosPermisos"
       class="btn-volver-usuarios" data-orbit-action="secondary">

        ← Volver a Usuarios y Permisos

    </a>

</div>



<!-- VENTANA DE CONFIRMACIÓN -->

<div id="modalConfirmacion"
     class="modal-fondo">

    <div class="modal-contenido" data-orbit-dialog="surface">

        <div class="modal-icono"
             id="modalIcono">
            ?
        </div>


        <div class="modal-titulo">
            Confirmar acción
        </div>


        <p id="textoConfirmacion">
        </p>


        <div class="modal-botones">

            <button type="button"
                    class="btn-modal-si"
                    onclick="realizarAccion()" data-orbit-action="warning">

                Sí

            </button>


            <button type="button"
                    class="btn-modal-no"
                    onclick="cerrarConfirmacion()" data-orbit-action="secondary">

                No

            </button>


            <button type="button"
                    class="btn-modal-cancelar"
                    onclick="cancelarAccion()" data-orbit-action="secondary">

                Cancelar

            </button>

        </div>

    </div>

</div>



<style>

    .usuarios-card {
        box-sizing: border-box;
        overflow: hidden;
    }


    .tabla-contenedor {
        width: 100%;
        max-width: 100%;
        overflow-x: auto;
        box-sizing: border-box;
    }


    .tabla-usuarios {
        width: 100%;
        max-width: 100%;
        box-sizing: border-box;
    }


    .acciones-usuario {
        display: flex;
        gap: 8px;
        align-items: center;
        justify-content: center;
        flex-wrap: wrap;
    }


    .acciones-usuario form {
        margin: 0;
    }


    .btn-reactivar {
        background-color: #198754;
        color: white;
        border: none;
        border-radius: 6px;
        padding: 8px 14px;
        cursor: pointer;
        font-weight: 600;
    }


    .btn-reactivar:hover {
        background-color: #157347;
    }


    .mensaje {
        padding: 12px;
        margin-bottom: 20px;
        border-radius: 6px;
        font-weight: 600;
    }


    .mensaje-exito {
        background-color: #d1e7dd;
        color: #0f5132;
        border: 1px solid #badbcc;
    }


    .mensaje-error {
        background-color: #f8d7da;
        color: #842029;
        border: 1px solid #f5c2c7;
    }


    .sin-usuarios {
        padding: 25px;
        text-align: center;
        color: #666;
        font-size: 16px;
    }



    /* BOTONES DE NAVEGACIÓN */

    .contenedor-navegacion {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 12px;
        margin-top: 30px;
        margin-bottom: 30px;
        flex-wrap: wrap;
    }


    .btn-listado {
        display: inline-block;
        padding: 12px 22px;
        background-color: #59636b;
        color: white;
        border-radius: 7px;
        text-decoration: none;
        font-weight: 600;
    }


    .btn-listado:hover {
        background-color: #474f55;
        color: white;
    }


    .btn-volver-usuarios {
        display: inline-block;
        padding: 12px 22px;
        background-color: #1198a5;
        color: white;
        border-radius: 7px;
        text-decoration: none;
        font-weight: 600;
    }


    .btn-volver-usuarios:hover {
        background-color: #0d8490;
        color: white;
    }



    /* VENTANA DE CONFIRMACIÓN */

    .modal-fondo {
        display: none;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.45);
        align-items: center;
        justify-content: center;
        z-index: 9999;
    }


    .modal-contenido {
        width: 90%;
        max-width: 430px;
        background-color: white;
        border-radius: 15px;
        padding: 30px;
        text-align: center;
        box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25);
    }


    .modal-icono {
        width: 55px;
        height: 55px;
        margin: 0 auto 15px auto;
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: #1198a5;
        color: white;
        border-radius: 50%;
        font-size: 30px;
        font-weight: bold;
    }


    .modal-titulo {
        margin: 0;
        color: #003b64;
        font-size: 25px;
        font-weight: 700;
    }


    .modal-contenido p {
        margin-top: 15px;
        margin-bottom: 25px;
        font-size: 17px;
        color: #444;
    }


    .modal-botones {
        display: flex;
        justify-content: center;
        gap: 10px;
        flex-wrap: wrap;
    }


    .modal-botones button {
        min-width: 90px;
        padding: 10px 18px;
        border: none;
        border-radius: 7px;
        color: white;
        font-weight: 600;
        cursor: pointer;
    }


    .btn-modal-si {
        background-color: #198754;
    }


    .btn-modal-si:hover {
        background-color: #157347;
    }


    .btn-modal-no {
        background-color: #c82333;
    }


    .btn-modal-no:hover {
        background-color: #a91d2a;
    }


    .btn-modal-cancelar {
        background-color: #59636b;
    }


    .btn-modal-cancelar:hover {
        background-color: #474f55;
    }

</style>



<script>

    let formularioPendiente = null;
    let accionPendiente = "";


    // CONFIRMAR REACTIVAR

    function confirmarReactivar(formulario) {

        formularioPendiente =
            formulario;

        accionPendiente =
            "reactivar";


        document.getElementById(
            "textoConfirmacion"
        ).innerText =
            "¿Quieres reactivar este usuario?";


        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "flex";


        return false;
    }



    // CONFIRMAR ELIMINAR

    function confirmarEliminar(formulario) {

        formularioPendiente =
            formulario;

        accionPendiente =
            "eliminar";


        document.getElementById(
            "textoConfirmacion"
        ).innerText =
            "¿Quieres eliminar definitivamente este usuario?";


        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "flex";


        return false;
    }



    // BOTÓN SÍ

    function realizarAccion() {

        if (formularioPendiente == null) {
            return;
        }


        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "none";


        formularioPendiente.submit();
    }



    // BOTÓN NO

    function cerrarConfirmacion() {

        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "none";


        formularioPendiente =
            null;

        accionPendiente =
            "";
    }



    // BOTÓN CANCELAR

    function cancelarAccion() {

        document.getElementById(
            "modalConfirmacion"
        ).style.display =
            "none";


        formularioPendiente =
            null;

        accionPendiente =
            "";
    }

</script>

LoginSARMedix/Views/Home/Lotes.cshtml.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "Lotes"; ViewData["SmFamily"] = "products"; }
@model List<LoginSARMedix.Models.Lote>

@using Microsoft.AspNetCore.Http

@{
    ViewData["Title"] = "Inventario";
    ViewData["TituloBarra"] = "Inventario";

    string permisosTexto =
        Context.Session.GetString("Permisos") ?? "";

    var permisos =
        permisosTexto
            .Split(
                '|',
                StringSplitOptions.RemoveEmptyEntries
            );

    bool puedeRegistrar =
        permisos.Any(
            p => p.Equals(
                "Registrar productos",
                StringComparison.OrdinalIgnoreCase
            )
        );
}


<link rel="stylesheet" href="~/css/sarmedix-structural.css" asp-append-version="true" />

<section class="usuarios-card sm-reimagined sm-stock-workspace" aria-label="Inventario">
    <aside class="sm-stock-rail">
        <div class="sm-overline">ÓRBITA / EXISTENCIAS</div>
        <h1>Todo el stock.<br /><em>En perspectiva.</em></h1>
        <p class="sm-lead">Consulta cada lote, su ubicación y su vencimiento desde una sola vista.</p>
        <div class="sm-stock-instrument"><partial name="_OrbitInstrument" /><div class="sm-instrument-reading"><strong>@(Model?.Count ?? 0)</strong><span>Lotes en esta vista</span></div></div>
        <div class="sm-rail-actions">    @if (puedeRegistrar)
    {
        <div class="acciones-superiores">

            <a asp-controller="Home"
               asp-action="CrearLote"
               class="btn-nuevo-lote" data-orbit-action="primary">

                + Registrar entrada

            </a>

        </div>
    }</div>
        <div class="sm-rail-navigation">    <div class="contenedor-navegacion">


        <a asp-controller="Home"
           asp-action="ListadoProductos2"
           class="btn-listado-productos" data-orbit-action="secondary">

            ← Ver catálogo de productos

        </a>


        <a asp-controller="Home"
           asp-action="Productos"
           class="btn-volver-productos" data-orbit-action="secondary">

            ← Volver a Productos

        </a>


    </div>


</div>
    </aside>
    <div class="sm-stock-content">
            @if (TempData["Mensaje"] != null)
    {
        string tipoMensaje =
            TempData["TipoMensaje"]?.ToString() ?? "";

        <div id="mensajeListado"
             class="mensaje @(tipoMensaje == "exito" ? "mensaje-exito" : "mensaje-error")">

            @TempData["Mensaje"]

        </div>
    }
        <header class="sm-workspace-heading"><div><span class="sm-overline">INVENTARIO / LOTES</span><h2>Mapa de existencias</h2></div><span class="sm-workspace-symbol"><svg class="sm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#sm-icon-inventory" /></svg></span></header>
        <div class="sm-stock-key"><span>Producto y lote</span><span>Vencimiento · Stock · Ubicación</span>@if (puedeRegistrar) { <span>Gestión</span> }</div>
        @if (Model != null && Model.Count > 0)
        {
            <ul class="sm-stock-list">
            @foreach (var lote in Model)
            {
                // Presentation uses the existing 30-day inventory threshold.
                var fecha = lote.fecha_vencimiento?.Date;
                var estado = !fecha.HasValue ? "Sin fecha" : fecha.Value < DateTime.Today ? "Vencido" : fecha.Value <= DateTime.Today.AddDays(30) ? "Próximo a vencer" : "Vigente";
                var estadoClase = !fecha.HasValue ? "unknown" : fecha.Value < DateTime.Today ? "expired" : fecha.Value <= DateTime.Today.AddDays(30) ? "soon" : "current";
                <li class="sm-stock-record" data-expiry="@estadoClase">
                    <div class="sm-stock-product"><span class="sm-record-icon"><svg class="sm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#sm-icon-products" /></svg></span><div><h3>@lote.nombre_producto</h3><span class="sm-stock-lot">Lote <strong>@lote.numero_lote</strong></span></div></div>
                    <dl class="sm-stock-facts">
                        <div><dt>Vencimiento</dt><dd>@lote.fecha_vencimiento?.ToString("dd-MM-yyyy") <span class="sm-state">@estado</span></dd></div>
                        <div class="sm-stock-quantity"><dt>Stock actual</dt><dd><span class="cantidad-lote">@lote.cantidad_actual</span>@if (lote.cantidad_actual <= 0) { <span class="sm-state sm-zero">Sin stock</span> }</dd></div>
                        <div><dt>Ubicación</dt><dd>@lote.nombre_ubicacion</dd></div>
                    </dl>
                    @if (puedeRegistrar)
                    {
                        <a asp-controller="Home" asp-action="EditarLote" asp-route-idLote="@lote.id_lote" class="btn-editar" data-orbit-action="secondary">Editar</a>
                    }
                </li>
            }
            </ul>
        }
        else
        {
            <div class="sin-registros">No existen existencias registradas en el inventario.</div>
        }
    </div>
</section>
<style>

    /* ========================================= */
    /* TARJETA                                   */
    /* ========================================= */

    .usuarios-card {
        box-sizing: border-box;
        overflow: hidden;
    }



    /* ========================================= */
    /* TABLA                                     */
    /* ========================================= */

    .tabla-contenedor {
        width: 100%;
        max-width: 100%;

        overflow-x: auto;

        box-sizing: border-box;
    }


    .tabla-usuarios {
        width: 100%;

        box-sizing: border-box;
    }


    .tabla-usuarios th,
    .tabla-usuarios td {
        vertical-align: middle;
    }



    /* ========================================= */
    /* BOTON REGISTRAR                           */
    /* ========================================= */

    .acciones-superiores {
        display: flex;

        justify-content: flex-end;

        margin-top: 20px;
        margin-bottom: 22px;
    }


    .btn-nuevo-lote {
        display: inline-block;

        padding: 10px 18px;

        background-color: #0d7898;

        color: white;

        border-radius: 6px;

        text-decoration: none;

        font-weight: 600;

        transition:
            background-color 0.2s ease;
    }


    .btn-nuevo-lote:hover {
        background-color: #09637e;

        color: white;
    }



    /* ========================================= */
    /* CANTIDAD                                  */
    /* ========================================= */

    .cantidad-lote {
        display: inline-block;

        min-width: 45px;

        padding: 5px 10px;

        background-color: #e7f3f7;

        color: #0d5b82;

        border-radius: 14px;

        text-align: center;

        font-weight: 600;
    }



    /* ========================================= */
    /* MENSAJES                                  */
    /* ========================================= */

    .mensaje {
        width: 100%;

        box-sizing: border-box;

        margin-top: 20px;
        margin-bottom: 20px;

        padding: 12px 15px;

        border-radius: 7px;

        text-align: center;

        font-weight: 600;

        opacity: 1;

        transition:
            opacity 0.5s ease;
    }


    .mensaje-exito {
        background-color: #d1e7dd;

        color: #0f5132;

        border:
            1px solid #badbcc;
    }


    .mensaje-error {
        background-color: #f8d7da;

        color: #842029;

        border:
            1px solid #f5c2c7;
    }



    /* ========================================= */
    /* SIN REGISTROS                             */
    /* ========================================= */

    .sin-registros {
        padding: 25px;

        margin-top: 20px;

        background-color: #f5f8fa;

        border:
            1px solid #d8e2e8;

        border-radius: 8px;

        text-align: center;

        color: #60798b;

        font-size: 16px;
    }



    /* ========================================= */
    /* NAVEGACION                                */
    /* ========================================= */

    .contenedor-navegacion {
        display: flex;

        justify-content: center;
        align-items: center;

        gap: 12px;

        margin-top: 30px;
        margin-bottom: 10px;

        flex-wrap: wrap;
    }


    .btn-listado-productos {
        display: inline-block;

        padding: 12px 22px;

        background-color: #59636b;

        color: white;

        border-radius: 7px;

        text-decoration: none;

        font-weight: 600;
    }


    .btn-listado-productos:hover {
        background-color: #474f55;

        color: white;
    }


    .btn-volver-productos {
        display: inline-block;

        padding: 12px 22px;

        background-color: #1198a5;

        color: white;

        border-radius: 7px;

        text-decoration: none;

        font-weight: 600;
    }


    .btn-volver-productos:hover {
        background-color: #0d8490;

        color: white;
    }



    /* ========================================= */
    /* CELULAR                                   */
    /* ========================================= */

    @@media (max-width: 700px) {

        .acciones-superiores {
            justify-content: center;
        }


        .contenedor-navegacion {
            flex-direction: column;
        }


        .btn-listado-productos,
        .btn-volver-productos {
            width: 90%;

            box-sizing: border-box;

            text-align: center;
        }

    }

</style>



<script>

    // =========================================
    // OCULTAR MENSAJE DESPUES DE 3 SEGUNDOS
    // =========================================

    setTimeout(
        function () {

            const mensaje =
                document.getElementById(
                    "mensajeListado"
                );


            if (mensaje) {

                mensaje.style.opacity =
                    "0";


                setTimeout(
                    function () {

                        mensaje.style.display =
                            "none";

                    },
                    500
                );
            }

        },
        3000
    );

</script>

