﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "ModuloMovimientoHistorial"; ViewData["SmFamily"] = "movements"; }
@using Microsoft.AspNetCore.Http

@{
    ViewData["Title"] = "Movimientos e Historial";

