        "Seleccione Historial";


    // =========================================================
    // OBTENER PERMISOS DEL USUARIO
    // =========================================================

    string permisosTexto =
        Context.Session.GetString("Permisos") ?? "";


    var permisos =
        permisosTexto
            .Split(
                '|',
                StringSplitOptions.RemoveEmptyEntries
            )
            .ToList();


    Func<string, bool> TienePermiso =
        permiso =>
            permisos.Any(
                p => p.Equals(
                    permiso,
                    StringComparison.OrdinalIgnoreCase
                )
            );


    // =========================================================
    // PERMISOS DE LOS HISTORIALES
    // =========================================================

    bool puedeConsultarHistorial =
        TienePermiso(
            "Consultar historial"
        );


    bool puedeGestionarUsuarios =
        TienePermiso(
            "Gestionar usuarios y permisos"
        );
}


<style>

    /* CONTENEDOR */

