<script>

    let accionPendiente = null;


    // CONFIRMAR EDICION

    function confirmarEditar(enlace) {

        accionPendiente = {
            tipo: "editar",
            url: enlace.href
        };


        document.getElementById(
            "textoConfirmacion"
        ).innerText =
            "¿Quieres editar este usuario?";


        document.getElementById(
            "modalConfirmacion"
        ).style.display = "flex";


        return false;
    }



    // CONFIRMAR DESACTIVAR

    function confirmarDesactivar(formulario) {

        accionPendiente = {
            tipo: "desactivar",
            formulario: formulario
        };


        document.getElementById(
            "textoConfirmacion"
        ).innerText =
            "¿Quieres desactivar este usuario?";


        document.getElementById(
            "modalConfirmacion"
        ).style.display = "flex";


        return false;
    }



    // REALIZAR ACCION

    function realizarAccion() {

        if (accionPendiente == null) {
            return;
        }


        if (accionPendiente.tipo === "editar") {

            window.location.href =
                accionPendiente.url;

        }


        if (accionPendiente.tipo === "desactivar") {

            accionPendiente
                .formulario
                .submit();

        }

    }



    // CERRAR CONFIRMACION

    function cerrarConfirmacion() {

        document.getElementById(
            "modalConfirmacion"
        ).style.display = "none";


        accionPendiente = null;
    }

</script>

