    }


    .alertas-item-destino span {
        font-size: 11px;
    }



    /* FLECHA */

    .alertas-item-flecha {
        align-self: center;

        padding-left: 2px;

        color: #9babb3;

        font-size: 22px;

        font-weight: 400;

        line-height: 1;

        transition:
            transform 0.16s ease,
            color 0.16s ease;
    }



    /* SIN ALERTAS */

    .alertas-vacio {
        padding:
            35px
            25px;

        display: flex;

        flex-direction: column;

        align-items: center;

        gap: 6px;

        text-align: center;
    }


    .alertas-vacio-icono {
        width: 42px;

        height: 42px;

        margin-bottom: 4px;

        display: flex;

        align-items: center;

        justify-content: center;

        border-radius: 50%;

        background: #eaf4f7;

        color: #087f8b;

        font-size: 20px;

        font-weight: 800;
    }


    .alertas-vacio strong {
        color: #244759;

        font-size: 13px;
    }


    .alertas-vacio span {
        max-width: 250px;

        color: #758791;

        font-size: 10px;

        line-height: 1.5;
    }



    /* PIE */

    .alertas-panel-pie {
        padding:
            10px
            15px;

        border-top:
            1px solid
            #e8eef1;

        background: #f7fafb;

        color: #7b8d96;

        font-size: 9px;

        text-align: center;
    }



    /* RESPONSIVE */

    @@media (max-width: 620px) {

        .alertas-panel {
            position: fixed;

            top: 78px;

            right: 10px;

            left: 10px;

            width: auto;

            max-width: none;
        }


        .alertas-panel::before {
            display: none;
        }


        .alertas-resumen {
            grid-template-columns:
                repeat(
                    3,
                    minmax(
                        0,
                        1fr
                    )
                );
        }

    }

</style>



<script>

    // ABRIR / CERRAR ALERTAS

    function alternarAlertasSarmedix(
        evento
    ) {

        if (evento) {

            evento.stopPropagation();

        }


        const panel =
            document.getElementById(
                "panelAlertasSarmedix"
            );


        const boton =
            document.getElementById(
                "botonAlertasSarmedix"
            );


        if (
            !panel
            ||
            !boton
        ) {

            return;

        }


        const abierto =
            panel.classList.contains(
                "abierto"
            );


        if (abierto) {

            panel.classList.remove(
                "abierto"
            );


            boton.setAttribute(
                "aria-expanded",
                "false"
            );

        }
        else {

            panel.classList.add(
                "abierto"
            );


            boton.setAttribute(
                "aria-expanded",
                "true"
            );

        }

    }



    // EVITAR QUE EL PANEL SE CIERRE AL HACER CLIC DENTRO

    document
        .getElementById(
            "panelAlertasSarmedix"
        )
        ?.addEventListener(
            "click",
            function (
                evento
            ) {

                evento.stopPropagation();

            }
        );



    // CERRAR AL HACER CLIC FUERA

    document.addEventListener(
        "click",
        function () {

            const panel =
                document.getElementById(
                    "panelAlertasSarmedix"
                );


            const boton =
                document.getElementById(
                    "botonAlertasSarmedix"
                );


            if (
                panel
                &&
                panel.classList.contains(
                    "abierto"
                )
            ) {

                panel.classList.remove(
                    "abierto"
                );


                boton
                    ?.setAttribute(
                        "aria-expanded",
                        "false"
                    );

            }

        }
    );



    // CERRAR CON ESC

    document.addEventListener(
        "keydown",
        function (
            evento
        ) {

            if (
                evento.key
                !==
                "Escape"
            ) {

                return;

            }


            const panel =
                document.getElementById(
                    "panelAlertasSarmedix"
                );


            const boton =
                document.getElementById(
                    "botonAlertasSarmedix"
                );


            panel
                ?.classList
                .remove(
                    "abierto"
                );


            boton
                ?.setAttribute(
                    "aria-expanded",
                    "false"
                );

        }
    );

</script>

