/* ÓRBITA / global component authority.
 * Data annotations decouple appearance from functional classes and selectors.
 * !important is restricted to shared controls that had inline/legacy !important
 * declarations. Visibility, positioning of overlays and business states remain
 * owned by the original views. All visual rules are screen-only. */
.orbit-table-caption {
    display: none;
}

@media screen {
    :root {
        --orbit-ink: #173654;
        --orbit-muted: #4d6580;
        --orbit-blue: #285ed4;
        --orbit-line: #c4d5ec;
        --orbit-paper: #fff;
        --orbit-soft: #edf3fc;
        --orbit-dark: #112e50;
        --orbit-radius: 14px;
        --orbit-shadow: 0 12px 34px #183c7012;
        --orbit-fast: 160ms;
        --orbit-ease: cubic-bezier(.2,.7,.2,1);
    }

    :is(.sm-app,.sm-standalone) {
        color: var(--orbit-ink);
        font-family: "Segoe UI",system-ui,sans-serif;
    }

        :is(.sm-app,.sm-standalone) *, :is(.sm-app,.sm-standalone) *::before, :is(.sm-app,.sm-standalone) *::after {
            box-sizing: border-box;
        }
    /* One semantic family for every annotated action, including navigation links. */
    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action]:where(:not([data-orbit-action="navigation"])) {
        --action-bg: linear-gradient(130deg,#326fe4,#2253bd);
        --action-ink: #fff;
        --action-line: #245ac7;
        background: var(--action-bg) !important;
        color: var(--action-ink) !important;
        border: 1px solid var(--action-line) !important;
        border-radius: 10px !important;
        min-height: 42px;
        max-width: 100%;
        padding: 10px 16px !important;
        font: 600 14px/1.4 "Segoe UI",system-ui,sans-serif !important;
        text-decoration: none !important;
        text-align: center;
        vertical-align: middle;
        white-space: normal;
        overflow-wrap: anywhere;
        cursor: pointer;
        box-shadow: inset 0 1px #ffffff24,0 3px 10px #183e7310 !important;
        transition: box-shadow var(--orbit-fast),filter var(--orbit-fast),border-color var(--orbit-fast) !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action="secondary"] {
        --action-bg: #f1f6ff !important;
        --action-ink: #254e85 !important;
        --action-line: #b9cdeb !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action="quiet"] {
        --action-bg: #fff !important;
        --action-ink: #3c597c !important;
        --action-line: #cedbed !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action="warning"] {
        --action-bg: #fff2d7 !important;
        --action-ink: #7a4c09 !important;
        --action-line: #dcb879 !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action="danger"] {
        --action-bg: #a82d49 !important;
        --action-ink: #fff !important;
        --action-line: #92203a !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action="icon"] {
        --action-bg: #edf4ff !important;
        --action-ink: #315e9a !important;
        --action-line: #bdd0ec !important;
        padding: 9px !important;
        min-width: 42px;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action]:hover:not(:disabled):not([aria-disabled="true"]) {
        filter: brightness(.96);
        box-shadow: 0 0 0 3px #347be71a,0 6px 14px #173f7918 !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action]:active:not(:disabled) {
        filter: brightness(.9);
        box-shadow: inset 0 2px 4px #14355925 !important;
    }

    body :is([data-orbit-action],input,select,textarea,a,[tabindex]):focus-visible {
        outline: 3px solid #3277df !important;
        outline-offset: 3px !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action]:is(:disabled,[aria-disabled="true"]) {
        opacity: .5 !important;
        cursor: not-allowed;
        filter: saturate(.5);
        box-shadow: none !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action][aria-busy="true"] {
        cursor: progress;
        border-style: dashed !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action].pagina-activa, body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action].activo {
        --action-bg: #204e98 !important;
        --action-ink: #fff !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .sidebar [data-orbit-action="navigation"] {
        border-radius: 10px;
        border: 1px solid transparent;
        transition: background var(--orbit-fast),border-color var(--orbit-fast);
    }

        body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .sidebar [data-orbit-action="navigation"]:hover {
            background: #71a1ef1c;
            border-color: #89b4f34d;
        }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .sidebar [data-orbit-action]:focus-visible {
        outline-color: #a9d8ff !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .sidebar .sidebar-cabecera.activo {
        box-shadow: inset 3px 0 #9ac8ff;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .barra-layout {
        border-bottom: 1px solid #b9cbe5;
        background: linear-gradient(105deg,#fff,#f4f8ff);
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .usuario-layout {
        padding: 6px 8px;
        border: 1px solid #d6e2f2;
        border-radius: 14px;
        background: #ffffffab;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] .footer-layout {
        border-top: 1px solid #cfdded;
        background: #eaf1fb;
        color: #526c8c;
    }
    /* Full input vocabulary: applies outside forms too (filters and scanners). */
    body.sm-app[data-sm-family][data-sm-screen] :is(input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]),select,textarea),
    body.sm-standalone :is(input,select,textarea) {
        max-width: 100%;
        min-width: 0;
        border: 1px solid #afc5e2;
        border-radius: 10px;
        background: #fbfdff;
        color: #203f63;
        font-family: inherit;
        font-size: 15px;
        line-height: 1.5;
        padding: 11px 13px;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(input,select,textarea):focus {
        border-color: #3978d9;
        box-shadow: 0 0 0 4px #3978d916;
    }
    /* Search fields with an icon and a bordered shell must not draw a second rectangle.
    Keep this specific: standalone search inputs still use the normal Orbit input style. */
    body.sm-app[data-sm-family][data-sm-screen] :is(.controlados-buscador,.buscador-con-icono,.busqueda-con-icono,.search-box) > :is(input[type="text"],input[type="search"]),
    body.sm-app[data-sm-family][data-sm-screen] :is(div,label):has(> :is(svg,i,span) ~ input:is([type="search"],[placeholder*="busc" i],[id*="busc" i])) > input:is([type="search"],[placeholder*="busc" i],[id*="busc" i]) {
        flex: 1 1 auto;
        min-width: 0;
        width: 100%;
        margin: 0;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 0 !important;
        outline: 0 !important;
        outline-offset: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.controlados-buscador,.buscador-con-icono,.busqueda-con-icono,.search-box):focus-within,
    body.sm-app[data-sm-family][data-sm-screen] :is(div,label):has(> :is(svg,i,span) ~ input:is([type="search"],[placeholder*="busc" i],[id*="busc" i])):focus-within {
        border-color: #3978d9;
        box-shadow: 0 0 0 3px #3978d916;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(input,select,textarea):disabled {
        background: #e9eef5;
        color: #536780;
        cursor: not-allowed;
    }

    body.sm-app[data-sm-family][data-sm-screen] input[readonly] {
        background: #edf3fc;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(input[type="checkbox"],input[type="radio"]) {
        accent-color: #2c67cb;
        width: 19px;
        height: 19px;
        flex: none;
    }

    body.sm-app[data-sm-family][data-sm-screen] input[type="file"]::file-selector-button {
        background: #e4edfb;
        color: #244d84;
        border: 1px solid #b9cceb;
        border-radius: 7px;
        padding: 8px 12px;
        margin-right: 10px;
        font: inherit;
        cursor: pointer;
    }

    body.sm-app[data-sm-family][data-sm-screen] textarea {
        resize: vertical;
        min-height: 110px;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.estado-activo,.badge-activo,.estado-normal) {
        background: #e2f2eb;
        color: #205d49;
        border: 1px solid #b0d6c7;
        border-radius: 6px;
        padding: 4px 8px;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.estado-inactivo,.estado-sin-stock) {
        background: #e8edf4;
        color: #465b74;
        border: 1px solid #bdcbdd;
        border-radius: 6px;
        padding: 4px 8px;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.estado-vencido,.alerta-vencido) {
        border-left: 3px solid #b13350;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.estado-proximo,.alerta-proximo,.alerta-stock) {
        border-left: 3px solid #ae741c;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.mensaje,.mensaje-error,.mensaje-exito,.validacion-caliente,.estado-codigo,.resultado) {
        border-radius: 12px;
        line-height: 1.55;
        overflow-wrap: anywhere;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.mensaje-error,.resultado.error,.mc-error-general) {
        border-left: 4px solid #b33251;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.mensaje-exito,.resultado.exito) {
        border-left: 4px solid #2b8669;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.sin-registros,.sin-usuarios,.sin-stock,.sin-programaciones,.sin-salidas,.vacio,.inventario-vacio,.ubicaciones-vacio,.controlados-sin-resultados-contenido) {
        border: 1px dashed #b0c7e5;
        background: linear-gradient(160deg,#f4f8ff,#fff);
        border-radius: 18px;
        padding: 28px;
        text-align: center;
        color: #4b6687;
    }
    /* Real structural forms. No reordering, hiding, additional steps or fields. */
    .orbit-eyebrow {
        display: block;
        font-size: 10px;
        letter-spacing: 1.8px;
        font-weight: 750;
        color: #50749e;
        line-height: 1.6;
    }

    body.sm-app[data-sm-family][data-sm-screen] main .orbit-editor-heading {
        width: 100%;
        max-width: 1180px;
        margin: 0 auto 20px;
        padding: 10px 0 18px;
        border-bottom: 1px solid #c1d3ec;
    }

    .orbit-editor-heading h1 {
        margin: 8px 0 0;
        color: #173d69;
        font-size: clamp(28px,3vw,40px);
        font-weight: 600;
        letter-spacing: -1px;
    }

    body.sm-app[data-sm-family][data-sm-screen] main form.formulario-principal:has(.orbit-identity-grid,.orbit-product-grid) {
        max-width: 1180px;
        border-radius: 22px;
        border: 1px solid #bed0e9;
        padding: 26px;
        box-shadow: var(--orbit-shadow);
    }

    .orbit-identity-grid {
        display: grid;
        grid-template-columns: 1.15fr 1fr;
        gap: 28px;
        align-items: start;
    }

    .orbit-product-grid {
        display: grid;
        grid-template-columns: 1.15fr 1fr;
        gap: 24px;
        align-items: start;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.orbit-identity-grid,.orbit-product-grid) fieldset, .orbit-role-fields {
        min-width: 0;
        border: 0;
        padding: 0;
        margin: 0;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.orbit-identity-grid,.orbit-product-grid,.orbit-role-fields) legend {
        float: none;
        width: auto;
        margin: 0 0 20px;
        font-size: 17px;
        font-weight: 650;
        color: #244e7c;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-identity-grid .orbit-credentials {
        padding: 22px;
        border: 1px solid #c2d4ee;
        border-radius: 16px;
        background: radial-gradient(ellipse at top right,#d3e2fb,transparent 70%),#eef4fd;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-product-content {
        padding: 20px !important;
        background: #e9f1fc;
        border-radius: 16px;
        border: 1px solid #bed0e9 !important;
    }

        body.sm-app[data-sm-family][data-sm-screen] .orbit-product-content .seccion-inventario {
            border: 0;
            padding: 0;
            background: none;
        }

    .orbit-product-identity > div {
        margin-bottom: 18px;
    }

    .orbit-product-grid label {
        display: block;
        margin-bottom: 6px;
    }

    .orbit-product-grid :is(input:not([type="hidden"]),select) {
        width: 100%;
    }

    .orbit-form-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        align-items: center;
        gap: 12px;
        margin-top: 22px;
        padding-top: 18px;
        border-top: 1px solid #d1dfef;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-form-actions > button {
        width: auto;
        min-width: 190px;
        margin: 0;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-form-actions .contenedor-volver {
        margin: 0;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.contenedor-crear-rol,.contenedor-editar-rol) {
        display: grid;
        grid-template-columns: minmax(220px,.7fr) minmax(0,1.3fr);
        column-gap: 30px;
        max-width: 1100px !important;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.titulo-crear-rol,.titulo-editar-rol,.descripcion-crear-rol,.descripcion-editar-rol) {
        grid-column: 1;
        text-align: left;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.tarjeta-crear-rol,.tarjeta-editar-rol) {
        grid-column: 2;
        grid-row: 1 / 5;
    }

    body.sm-app[data-sm-family][data-sm-screen] :is(.volver-rol,.volver-editar-rol) {
        grid-column: 1;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-permission-workbench {
        display: grid;
        grid-template-columns: 260px minmax(0,1fr);
        gap: 20px;
    }

    .orbit-permission-intro {
        grid-column: 1;
        padding: 22px;
        border-radius: 16px;
        background: #173b63;
        color: #e1edff;
    }

        .orbit-permission-intro h2 {
            background: none;
            box-shadow: none;
            color: #fff;
            font-size: 25px;
            margin: 12px 0;
            padding: 0;
        }

        .orbit-permission-intro .orbit-eyebrow {
            color: #aacaf2;
        }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-permission-workbench > form:first-of-type {
        grid-column: 1;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-permission-workbench > form:last-of-type:not(:first-of-type) {
        grid-column: 2;
        grid-row: 1 / 5;
    }

    body.sm-app[data-sm-family][data-sm-screen] .orbit-permission-workbench > :is(.acciones-rol,.confirmacion) {
        grid-column: 1;
    }

    body.sm-app[data-sm-family][data-sm-screen] .permisos {
        grid-template-columns: repeat(auto-fit,minmax(min(240px,100%),1fr));
        gap: 10px;
    }

    body.sm-app[data-sm-family][data-sm-screen] .permiso {
        padding: 16px;
    }
    /* Access is a split welcome portal, not a decorated legacy card. */
    body.sm-app[data-sm-family][data-sm-screen][data-sm-family="access"] main .orbit-access {
        width: min(1040px,100%);
        display: grid;
        grid-template-columns: 1fr 1fr;
        border-radius: 24px;
        background: #fff;
        border: 1px solid #5d80ae;
        box-shadow: 0 24px 70px #06162e44;
        overflow: hidden;
        margin: auto;
    }

    .orbit-access-brand {
        padding: 36px;
        background: radial-gradient(ellipse at 0 0,#3976b952,transparent 65%),#112e50;
        color: #d9e9ff;
    }

        .orbit-access-brand .orbit-eyebrow {
            color: #afd1ff;
        }

        .orbit-access-brand h1 {
            font-size: clamp(28px,3vw,39px);
            font-weight: 500;
            line-height: 1.2;
            letter-spacing: -.8px;
            color: #fff;
            margin: 20px 0 12px;
        }

        .orbit-access-brand p {
            font-size: 14px;
            color: #b9d1ef;
        }

    .orbit-access-art {
        height: 180px;
        width: 180px;
        margin: 18px auto;
        position: relative;
    }

        .orbit-access-art .sm-orbit-instrument {
            position: absolute;
            inset: 0;
            pointer-events: none;
        }

        .orbit-access-art .sm-instrument-halo {
            position: absolute;
            inset: 3%;
            border-radius: 50%;
            background: radial-gradient(circle,#578ff433,transparent 68%);
        }

        .orbit-access-art .sm-instrument-ring {
            position: absolute;
            border: 1px solid #8dbfff55;
            border-radius: 50%;
        }

        .orbit-access-art .sm-ring-outer {
            inset: 4%;
            border-style: dashed;
        }

        .orbit-access-art .sm-ring-middle {
            inset: 17%;
            border-top: 2px solid #a4d4ff;
            transform: rotate(-35deg);
        }

        .orbit-access-art .sm-ring-inner {
            inset: 28%;
            background: radial-gradient(circle at 30% 15%,#bddcff20,#1e497522);
            box-shadow: inset 0 1px #b7dbff55,0 0 35px #5597ff16;
        }

        .orbit-access-art .sm-instrument-axis {
            position: absolute;
            left: 0;
            top: 50%;
            width: 100%;
            border-top: 1px solid #91c4ff22;
            transform: rotate(-35deg);
        }

        .orbit-access-art .sm-instrument-satellite {
            position: absolute;
            left: 18%;
            top: 19%;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: #b2deff;
            box-shadow: 0 0 0 6px #69aaff16,0 0 24px #9acaff;
        }

    .orbit-access-fields {
        min-width: 0;
        padding: 32px;
        align-self: center;
    }

    body.sm-app[data-sm-family][data-sm-screen] main .orbit-access-fields h2 {
        color: #22476f;
        background: none;
        padding: 0;
        border: 0;
        box-shadow: none;
        font-size: 27px;
        margin: 0 0 16px;
    }

        body.sm-app[data-sm-family][data-sm-screen] main .orbit-access-fields h2::before, body.sm-app[data-sm-family][data-sm-screen] main .orbit-access-fields h2::after {
            content: none;
        }

    body.sm-app[data-sm-family][data-sm-screen] main .orbit-access-fields form {
        width: 100%;
        max-width: none;
        margin: 0;
        padding: 0;
        box-shadow: none;
        background: transparent;
        border: 0;
    }

    .orbit-access-fields > p {
        color: #536d8e;
        font-size: 14px;
    }

    body.sm-app[data-sm-family][data-sm-screen][data-sm-screen="NuevaContrasena"] .contenedor-recuperacion {
        display: grid;
        grid-template-columns: 1fr 1fr;
        max-width: 1040px;
        min-height: 0;
        padding: 0;
        border-radius: 24px;
        overflow: hidden;
        background: #fff;
    }

    body.sm-app[data-sm-family][data-sm-screen][data-sm-screen="NuevaContrasena"] .tarjeta-recuperacion {
        border: 0;
        box-shadow: none;
        text-align: left;
        border-radius: 0;
    }
    /* Movements: editable route on the left, review dock on the right. */
    body.sm-app[data-sm-family][data-sm-screen] :is(.salida-pagina,.extra-pagina,.traslado-pagina) :is(.grid,.traslado-grid) {
        display: grid;
        grid-template-columns: minmax(0,1.3fr) minmax(250px,.8fr);
        gap: 24px;
        align-items: start;
    }

    .orbit-movement-input {
        min-width: 0;
        padding: 10px;
    }

        .orbit-movement-input > .orbit-eyebrow {
            margin-bottom: 18px;
        }

    body.sm-app[data-sm-family][data-sm-screen] :is(.salida-pagina,.extra-pagina,.traslado-pagina) :is(.grid,.traslado-grid) > div:last-child {
        background: #173b64;
        color: #e3efff;
        border: 1px solid #547dac;
        border-radius: 18px;
        padding: 24px;
    }

        body.sm-app[data-sm-family][data-sm-screen] :is(.salida-pagina,.extra-pagina,.traslado-pagina) :is(.grid,.traslado-grid) > div:last-child :is(h2,strong) {
