        transition: none !important;
        scroll-behavior: auto !important;
    }

    body:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action] {
        transition: none !important;
    }
}

.sm-motion-paused *, .sm-motion-paused *::before, .sm-motion-paused *::after {
    animation: none !important;
    transition: none !important;
}

body.sm-motion-paused:is(.sm-app,.sm-standalone)[data-sm-family][data-sm-screen] [data-orbit-action][data-orbit-action] {
