.sm-app .contenido-app { background: radial-gradient(ellipse at 95% 0,#b8d1ff55,transparent 55%),radial-gradient(ellipse at 0 80%,#e1ecff77,transparent 50%),#f2f6fc; }
.sm-app .sidebar { width: 270px; min-width: 270px; background: radial-gradient(ellipse at 0 0,#24579a55,transparent 55%),radial-gradient(ellipse at 100% 100%,#1f4e8355,transparent 55%),#0b213d; border-right: 1px solid #386395; }
.sm-app .barra-layout { grid-template-columns: 246px minmax(80px,1fr) auto; }
.sm-app .sidebar-titulo { font-size: 20px; padding-bottom: 27px; }
.sm-nav-eyebrow { font-size: 10px; letter-spacing: 1.6px; }
.sm-app .sidebar-modulo-enlace { font-size: 14px; padding-top: 14px; padding-bottom: 14px; line-height: 1.45; }
.sm-app .sidebar-cabecera { min-height: 58px; transition: background .25s,border-color .25s,box-shadow .25s; }
.sm-app .sidebar-cabecera:hover, .sm-app .sidebar-cabecera:focus-within { background: linear-gradient(105deg,#3774c438,#5b8dde0a); border-color: #8bb8ff60; box-shadow: inset 0 1px #cbe2ff12,0 5px 20px #030f241a; }
.sm-app .sidebar-cabecera.activo { background: linear-gradient(105deg,#2b64bf9c,#28528830); box-shadow: inset 3px 0 #96dbff,0 0 20px #4a89ff12; }
