.sm-icon { width: 21px; height: 21px; transition: transform .25s var(--sm-ease),color .25s; }
.sm-app .sidebar-subopcion { font-size: 13px; min-height: 44px; }
.sm-app .sidebar-grupo.abierto .sidebar-submenu { animation: sm-panel-in .3s var(--sm-ease); }
.sm-sidebar-signature { font-size: 12px; }
.sm-sidebar-signature small { font-size: 8px; line-height: 1.6; letter-spacing: .7px; }
.sm-app .footer-layout { font-size: 12px; }
.sm-app :is(a,button,input,select,textarea,[tabindex]):focus-visible { outline-color: var(--sm-focus) !important; }
