/* Shared surfaces: existing open/close and submission handlers remain owners. */
/* Órbita 2 refinement: one semantic icon family and unmistakable location.
   .activo remains owned by existing Razor; .abierto by the original menu JS. */
.sm-icon-library { position: absolute; width: 0; height: 0; overflow: hidden; pointer-events: none; }
.sm-module-icon .sm-icon, .sm-table-symbol .sm-icon { width: 27px; height: 27px; stroke-width: 1.65; }
.sm-app .sidebar-icono { filter: none; }
