}
.sm-app .sidebar-subopcion.activo .sidebar-subicono { color: #174c8c; opacity: 1; }
.sm-app .sidebar .sidebar-subopcion.activo:focus-visible { outline-color: white !important; }

.sm-app .alertas-boton { width: 44px; height: 44px; box-shadow: inset 0 1px white,0 4px 12px #2d64bc14; transition: background .2s,box-shadow .2s,transform .2s; }
.sm-app .alertas-boton:hover { background: #dfeaff; box-shadow: 0 0 0 5px #3279e512; }
.sm-app .alertas-panel { border-radius: 20px; box-shadow: 0 26px 70px #112d4c36,0 0 0 5px #ffffff40; transform-origin: top right; animation: sm-panel-in .3s var(--sm-ease); }
.sm-app .alertas-item { transition: background .2s,border-color .2s; }
.sm-app .alertas-item:hover { background: #edf4ff; }
.sm-app .alertas-item-titulo { font-size: 14px; }
.sm-app .alertas-item-detalle { font-size: 13px; line-height: 1.65; }
.sm-app .modal-contenido-sesion { border-radius: 25px; border-top: 3px solid #5594f5; background: radial-gradient(ellipse at 50% 0,#e0ecff,transparent 65%),#fff; animation: sm-panel-in .3s var(--sm-ease); }
.sm-app .modal-botones-sesion button { min-height: 44px; transition: box-shadow .2s,filter .2s; }
.sm-app .modal-botones-sesion button:hover { box-shadow: 0 5px 16px #245ee626; filter: brightness(1.04); }

/* Welcome: layered aurora, optical rings and dimensional cards. */
.sm-app .contenido-modulos { padding: 32px clamp(22px,3vw,48px); }
.sm-eyebrow { font-size: 11px; letter-spacing: 1.6px; color: #496382; }
.sm-context-label { font-size: 13px; color: #4f6682; }
.sm-hero { min-height: 415px; border-radius: 26px; grid-template-columns: 1.15fr 1fr; background: linear-gradient(115deg,#081f40,#10396e); border-color: #436ba2; box-shadow: 0 24px 55px #153e7526,inset 0 1px #c6e4ff30; }
.sm-hero-copy { padding: 43px 0 38px 40px; }
.sm-hero-label { font-size: 12px; color: #d1e3ff; }
.sm-hero h1 { font-size: clamp(39px,3.9vw,66px); line-height: 1.06; letter-spacing: -2.5px; margin-top: 28px; }
.sm-hero h1 em { background: linear-gradient(105deg,#e0f6ff,#90c6ff 55%,#bbbcff); background-clip: text; -webkit-background-clip: text; color: transparent; }
.sm-hero p { font-size: 15px; line-height: 1.8; color: #d0def2; }
.sm-hero-foot { font-size: 12px; margin-top: 25px; }
.sm-principles { display: flex; flex-wrap: wrap; gap: 22px; margin-top: 27px; padding-top: 20px; border-top: 1px solid #a6c7f326; color: #9abbe6; font-size: 10px; }
.sm-principles strong { color: #dfedff; font-size: 12px; font-weight: 500; margin-left: 5px; }
.sm-aurora { position: absolute; inset: 0; z-index: -1; overflow: hidden; pointer-events: none; }
.sm-aurora i { position: absolute; width: 65%; height: 95%; border-radius: 50%; right: -5%; top: -15%; background: radial-gradient(ellipse,#5e98ff44,transparent 68%); animation: sm-aurora-flow 16s ease-in-out infinite alternate; }
.sm-aurora i:nth-child(2) { top: 25%; right: 5%; background: radial-gradient(ellipse,#3978f84d,transparent 65%); animation-delay: -7s; }
.sm-aurora i:nth-child(3) { top: 0; right: 30%; width: 40%; background: radial-gradient(ellipse,#80d4ff21,transparent 70%); animation-delay: -11s; }
.sm-orbital { width: 124%; margin-left: -12%; filter: drop-shadow(0 0 24px #8fc4ff20); }
.sm-orbital svg { max-height: 430px; }
.sm-orbit-lines { transform-origin: 260px 215px; animation: sm-ring-breathe 12s ease-in-out infinite alternate; }
.sm-motion-toggle { font-size: 11px; padding: 7px 11px; }
.sm-section-heading { margin-top: 36px; }
.sm-section-heading h2 { font-size: 27px; }
.sm-section-heading p { font-size: 14px; }
.sm-app .modulos { gap: 20px; perspective: 1200px; }
.sm-app .modulo { min-height: 210px; padding: 27px 28px; border-radius: 20px; border-color: #cedcf0; background: linear-gradient(130deg,#fff 20%,#f5f9ff); box-shadow: inset 0 1px #fff,0 8px 22px #163e7509; animation: sm-card-arrive .55s var(--sm-ease) backwards; }
.sm-app .modulo:nth-child(2) { animation-delay: .05s; }
.sm-app .modulo:nth-child(3) { animation-delay: .1s; }
.sm-app .modulo:nth-child(4) { animation-delay: .15s; }
.sm-app .modulo::after { content: ''; position: absolute; width: 130px; height: 130px; right: -55px; bottom: -60px; border: 1px solid #9fc0ef55; border-radius: 50%; box-shadow: 0 0 0 16px #dceaff33,0 0 0 32px #e5efff30; pointer-events: none; transition: transform .5s var(--sm-ease); z-index: -1; }
.sm-app .modulo.habilitado:hover { transform: perspective(1000px) translateY(-5px) rotateX(var(--sm-tilt-x,0deg)) rotateY(var(--sm-tilt-y,0deg)); box-shadow: 0 20px 38px #173d781c,inset 0 1px white; border-color: #77a7ec; }
.sm-app .modulo:hover::after { transform: scale(1.5); }
.sm-app .modulo-titulo { font-size: 22px; margin-top: 22px; line-height: 1.3; }
.sm-module-description { font-size: 14px; line-height: 1.6; color: #4b6380; }
.sm-module-top { font-size: 10px; letter-spacing: 1.3px; color: #4d6788; }
.sm-module-icon { width: 44px; height: 44px; border-radius: 13px; background: linear-gradient(145deg,#f2f8ff,#dce9ff); box-shadow: inset 0 1px white,0 5px 10px #2359a514; transition: transform .35s var(--sm-ease),box-shadow .35s; }
.sm-app .modulo:hover .sm-module-icon { transform: rotate(-6deg) scale(1.08); box-shadow: 0 6px 16px #2359a52b; }
.sm-module-arrow { font-size: 25px; }
