/* Operational language: light stays at the periphery; data stays still. */
.sm-inventory .usuarios-titulo { min-height: 190px; padding: 40px; border: 1px solid #4779b1; border-radius: 24px; background: radial-gradient(ellipse at 85% 30%,#2869b877,transparent 60%),linear-gradient(115deg,#0c2547,#123d70); box-shadow: 0 18px 40px #19477d22,inset 0 1px #b4d9ff33; }
.sm-inventory .usuarios-titulo::after { display: none; }
.sm-inventory .usuarios-titulo h1 { font-size: 43px; letter-spacing: -1.6px; }
.sm-inventory .usuarios-titulo p { font-size: 15px; max-width: 65%; color: #d1e3fc; }
.sm-inventory-orbit { position: absolute; right: 38px; top: 50%; width: 180px; height: 180px; transform: translateY(-50%); pointer-events: none; z-index: -1; }
.sm-inventory-orbit span { position: absolute; inset: 0; border: 1px solid #9bd3ff66; border-radius: 50%; transform: rotate(-30deg) scaleY(.62); box-shadow: 0 0 30px #6aafff15; }
.sm-inventory-orbit span:nth-child(2) { inset: 22px; transform: rotate(35deg) scaleY(.72); border-color: #c2dcff44; }
.sm-inventory-orbit span:first-child::after { content:''; position: absolute; top: 24px; left: 20px; width: 9px; height: 9px; border-radius: 50%; background: #c2efff; box-shadow: 0 0 15px #73bfff; }
.sm-inventory-orbit i { display: grid; place-items: center; position: absolute; inset: 44px; border: 1px solid #b7d9ff66; border-radius: 22px; background: linear-gradient(140deg,#a4d7ff55,#386ed222); box-shadow: inset 0 1px #d3efffaa,0 12px 24px #0003; font-style: normal; color: #d9f1ff; font-size: 60px; font-weight: 200; transform: rotate(-12deg); animation: sm-float 8s ease-in-out infinite; }
.sm-inventory .btn-nuevo-lote { font-size: 14px; min-height: 46px; padding: 12px 22px; background: linear-gradient(110deg,#245de2,#367dec); box-shadow: 0 7px 18px #245ee62b,inset 0 1px #9dc4ff; }
.sm-inventory .btn-nuevo-lote:hover { background: linear-gradient(110deg,#1d50cb,#286adc); box-shadow: 0 8px 24px #245ee642,0 0 0 4px #2d74e512; }
.sm-inventory .tabla-contenedor { border-radius: 20px; border-color: #c8d8ee; box-shadow: 0 14px 40px #163e7512; }
.sm-table-heading { display: flex; align-items: center; gap: 14px; padding: 23px 25px; border-bottom: 1px solid #d7e3f3; background: linear-gradient(100deg,#fff,#edf4ff); min-width: 720px; }
.sm-table-heading strong { display: block; font-size: 16px; font-weight: 600; color: #173d68; }
.sm-table-heading div > span { display: block; margin-top: 4px; font-size: 12px; color: #526b8b; }
.sm-table-symbol { display: grid; place-items: center; width: 42px; height: 42px; border: 1px solid #c1d4f2; background: #e4eeff; border-radius: 12px; color: #3269bc; font-size: 26px; }
.sm-inventory .tabla-usuarios th { font-size: 12px; padding: 18px 22px; background: #e8f0fb; color: #3b577b; }
.sm-inventory .tabla-usuarios td { font-size: 14px; line-height: 1.5; padding: 23px 22px; color: #405b79; }
.sm-inventory .tabla-usuarios td:first-child { font-size: 15px; border-left: 3px solid transparent; transition: border-color .2s,background .2s; }
.sm-inventory .tabla-usuarios tbody tr:nth-child(even) { background: #f9fbff; }
.sm-inventory .tabla-usuarios tbody tr:hover, .sm-inventory .tabla-usuarios tbody tr:focus-within { background: #edf4ff; }
.sm-inventory .tabla-usuarios tbody tr:hover td:first-child, .sm-inventory .tabla-usuarios tbody tr:focus-within td:first-child { border-left-color: #4386ed; }
.sm-inventory .cantidad-lote { font-size: 14px; min-width: 56px; padding: 6px 12px; border-radius: 9px; background: linear-gradient(145deg,#eff6ff,#e0ecff); }
.sm-inventory .btn-editar { font-size: 13px !important; padding: 10px 14px !important; min-height: 40px; transition: background .2s,box-shadow .2s; }
.sm-inventory .btn-editar:hover { box-shadow: 0 0 0 3px #326fe510; }
.sm-inventory :is(.btn-listado-productos,.btn-volver-productos) { font-size: 14px; }
.sm-inventory .sin-registros { padding: 58px 30px; font-size: 16px; background: radial-gradient(ellipse at top,#e6f0ff,transparent 75%),white; border-color: #9ebeea; }

/* Reusable tokens for the next pilot components; no blanket restyling of forms. */
.sm-field { border: 1px solid #b5c9e5; border-radius: 11px; padding: 12px 15px; min-height: 46px; background: #fbfdff; color: #193d66; font: inherit; transition: border-color .2s,box-shadow .2s; }
.sm-field:focus { border-color: #397be4; box-shadow: 0 0 0 4px #397be418; }
.sm-button { border: 1px solid #235bd8; border-radius: 11px; min-height: 46px; padding: 11px 20px; color: white; background: linear-gradient(110deg,#245de2,#367dec); font: inherit; }
@keyframes sm-aurora-flow { from { transform: translate(-4%,-5%) rotate(-10deg); } to { transform: translate(9%,8%) rotate(15deg); } }
@keyframes sm-ring-breathe { from { transform: rotate(-7deg) scale(.97); } to { transform: rotate(7deg) scale(1.03); } }
@keyframes sm-panel-in { from { opacity: .7; transform: translateY(-5px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes sm-card-arrive { from { opacity: .8; transform: translateY(12px); } to { opacity: 1; transform: none; } }

@media (max-width: 1250px) {
    .sm-app .sidebar { width: 235px; min-width: 235px; }
    .sm-app .barra-layout { grid-template-columns: 211px minmax(70px,1fr) auto; }
    .sm-app .usuario-datos-layout { display: none; }
    .sm-app .sidebar-modulo-enlace { font-size: 13px; }
    .sm-app .contenido-modulos { padding: 26px; }
    .sm-hero-copy { padding-left: 30px; }
    .sm-hero h1 { font-size: 44px; }
    .sm-principles { gap: 12px; }
}
@media (max-width: 1000px) {
    .sm-app .titulo-layout { display: none; }
    .sm-app .barra-layout { grid-template-columns: 1fr auto; }
    .sm-hero { grid-template-columns: 1fr; }
    .sm-hero-copy { padding-right: 28px; }
    .sm-orbital { position: absolute; width: 340px; right: -100px; bottom: -75px; opacity: .22; z-index: -1; }
    .sm-app .modulos { grid-template-columns: 1fr; }
    .sm-inventory .usuarios-titulo p { max-width: 75%; }
    .sm-inventory-orbit { right: -30px; opacity: .5; }
}
@media (max-width: 700px) {
    .sm-app .sidebar { width: 100%; min-width: 0; }
    .sm-app .sidebar-menu { grid-template-columns: repeat(2,minmax(0,1fr)); }
    .sm-app .sidebar-modulo-enlace { font-size: 12px; }
    .sm-app .contenido-modulos { padding: 22px 16px; }
    .sm-hero { min-height: 410px; border-radius: 22px; }
    .sm-hero-copy { padding: 30px 23px 54px; }
    .sm-hero h1 { font-size: clamp(33px,9vw,46px); letter-spacing: -1.6px; }
    .sm-hero p { font-size: 14px; }
    .sm-hero-label { font-size: 11px; }
    .sm-section-heading h2 { font-size: 25px; }
    .sm-app .modulo { padding: 24px; }
    .sm-app .modulo-titulo { font-size: 21px; }
    .sm-app .barra-layout { padding: 14px; gap: 10px; }
    .sm-app .usuario-circulo-layout { display: none; }
    .sm-motion-control { padding: 7px; min-width: 38px; min-height: 38px; }
    .sm-motion-control > span:first-child { margin: 0; font-size: 21px; }
    .sm-motion-control [data-sm-motion-label] { display: none; }
    .sm-app .btn-cerrar-layout { font-size: 12px !important; padding: 10px !important; }
    .sm-inventory .usuarios-titulo { padding: 30px 25px; }
    .sm-inventory .usuarios-titulo h1 { font-size: 37px; }
    .sm-inventory .usuarios-titulo p { max-width: 100%; font-size: 14px; }
    .sm-inventory-orbit { opacity: .2; }
    .sm-app .alertas-panel { top: 96px; }
}
@media (max-width: 380px) {
    .sm-app .logo-texto-layout { font-size: 22px; }
    .sm-app .logo-texto-layout small { font-size: 8px; }
    .sm-app .usuario-layout { gap: 6px; }
    .sm-principles { gap: 10px; }
}
@media (max-width: 480px) {
    .sm-app .barra-layout { grid-template-columns: 1fr; gap: 14px; }
    .sm-app .usuario-layout { justify-self: stretch; justify-content: space-between; width: 100%; }
    .sm-motion-control [data-sm-motion-label] { display: inline; margin-left: 5px; }
    .sm-app .alertas-panel { top: 145px; max-height: calc(100dvh - 165px); }
}
/* Both the manual switch and the OS preference disable *all* phase-two motion,
   including hover transformations and staged entrance effects. */
.sm-motion-paused *, .sm-motion-paused *::before, .sm-motion-paused *::after { animation: none !important; transition: none !important; }
.sm-motion-paused .modulo.habilitado:hover, .sm-motion-paused .modulo:hover .sm-module-icon, .sm-motion-paused .sidebar-cabecera:hover .sm-icon { transform: none !important; }
@media (prefers-reduced-motion: reduce) {
    .sm-app *, .sm-app *::before, .sm-app *::after { animation: none !important; transition: none !important; }
    .sm-app .modulo.habilitado:hover, .sm-app .modulo:hover .sm-module-icon, .sm-app .sidebar-cabecera:hover .sm-icon { transform: none !important; }
    .sm-motion-control { display: none; }
}
@media print {
    .sm-app *, .sm-app *::before, .sm-app *::after { animation: none !important; transition: none !important; }
    .sm-aurora, .sm-inventory-orbit, .sm-motion-control { display: none; }
}

LoginSARMedix/wwwroot/css/sarmedix-refin.text:
/* =========================================================
   SARMedix - ORBITA 2.0
   SCROLL GLOBAL PARA TABLAS PRINCIPALES

   - Scroll independiente de la pagina
   - Scroll vertical dentro de las tablas
   - Encabezados fijos
   - Conserva el diseño original
   - No afecta modales ni formularios
   ========================================================= */

:root {
    --sm-tabla-altura-maxima: 62vh;
    --sm-tabla-altura-minima: 280px;
    --sm-tabla-altura-limite: 680px;
}


/* =========================================================
   CONTENEDORES DE TABLAS DEL SISTEMA
   ========================================================= */

body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll ):not(:is( .modal *, [role="dialog"] *, form *, .informe-imprimible *, .reporte-imprimible * )) {
    display: block;
    position: relative;
    width: 100%;
    height: auto;
    max-height: clamp( var(--sm-tabla-altura-minima), var(--sm-tabla-altura-maxima), var(--sm-tabla-altura-limite) ) !important;
    overflow-y: auto !important;
    overflow-x: auto !important;
    overscroll-behavior-y: contain;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: #8baed8 #edf3fb;
    -webkit-overflow-scrolling: touch;
}


/* =========================================================
   ENCABEZADOS FIJOS EN TODAS LAS TABLAS INCLUIDAS
   ========================================================= */

body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll ) table thead th {
    position: sticky !important;
    top: 0 !important;
    z-index: 5 !important;
    background-clip: padding-box;
    box-shadow: inset 0 -1px 0 rgba(50, 85, 130, 0.12);
}


/* =========================================================
   SCROLL PERSONALIZADO
   ========================================================= */

body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll )::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll )::-webkit-scrollbar-track {
    background: #edf3fb;
    border-radius: 10px;
}

body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll )::-webkit-scrollbar-thumb {
    background: #8baed8;
    border-radius: 10px;
    border: 2px solid #edf3fb;
}

    body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll )::-webkit-scrollbar-thumb:hover {
        background: #4b7fc2;
    }


/* =========================================================
   HISTORIALES: FILTROS VISIBLES EN ESCRITORIO
   ========================================================= */

body.sm-app[data-sm-family="history"]
.historial-card.sm-history-workspace {
    overflow: visible !important;
}

    body.sm-app[data-sm-family="history"]
    .historial-card.sm-history-workspace
    .sm-history-grid > .sm-history-console {
        position: sticky !important;
        top: 16px !important;
        z-index: 30 !important;
        box-shadow: 0 8px 25px rgba(25, 64, 110, 0.12) !important;
    }


/* =========================================================
   CELULARES Y PANTALLAS PEQUEÑAS
   ========================================================= */

@media screen and (max-width: 700px) {

    body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll ) {
        max-height: 55vh !important;
        scrollbar-gutter: auto;
    }

    body.sm-app[data-sm-family="history"]
    .historial-card.sm-history-workspace
    .sm-history-grid > .sm-history-console {
        position: static !important;
    }
}


/* =========================================================
   IMPRESION: SIN LIMITACION DE ALTURA
   ========================================================= */

@media print {

    body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll ) {
        max-height: none !important;
        height: auto !important;
        overflow: visible !important;
    }

        body.sm-app main :is( .tabla-contenedor, .controlados-tabla-contenedor, .inventario-tabla-contenedor, .tabla-wrap, .sm-tabla-scroll ) table thead th {
            position: static !important;
        }
}

