/* Órbita — three distinct workspaces. Only presentation, no visibility states
   owned by the operational JavaScript. No dependencies or remote resources. */
@media screen {
    body.sm-app:is([data-sm-screen="Lotes"],[data-sm-screen="Dosificaciones"],[data-sm-screen="Historial"]) .sm-screen-identity { display: none; }
    body.sm-app[data-sm-screen] main .sm-reimagined { --orbit-ink: #173d68; --orbit-muted: #4b6585; --orbit-line: #c9d9ef; --orbit-blue: #2b66dc; width: 100%; max-width: 1500px; margin: 0; padding: 0; background: transparent; box-shadow: none; min-width: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined * { box-sizing: border-box; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-overline { display: block; color: #4a6a93; font-size: 11px; font-weight: 650; letter-spacing: 1.6px; line-height: 1.6; }
    body.sm-app[data-sm-screen] main .sm-reimagined h1 { font-size: clamp(32px,3.2vw,49px); font-weight: 550; letter-spacing: -1.8px; line-height: 1.14; margin: 22px 0; color: var(--orbit-ink); }
    body.sm-app[data-sm-screen] main .sm-reimagined h1 em { font-style: normal; color: #88bdff; }
    body.sm-app[data-sm-screen] main .sm-reimagined h2 { color: var(--orbit-ink); font-size: clamp(23px,2vw,30px); font-weight: 550; letter-spacing: -.7px; line-height: 1.3; margin: 6px 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined p { font-size: 15px; line-height: 1.75; }
    body.sm-app[data-sm-screen] main .sm-reimagined :is(a,button,input,select):focus-visible { outline: 3px solid #5394f1; outline-offset: 4px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-workspace-symbol { display: grid; place-items: center; width: 62px; height: 62px; flex-shrink: 0; border-radius: 20px; color: #3975d0; border: 1px solid #bbd3f1; background: linear-gradient(135deg,#fff,#dfecff); box-shadow: inset 0 1px #fff,0 8px 22px #1e4c8810; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-workspace-symbol .sm-icon { width: 32px; height: 32px; }

    /* Orbital instrument: an atmospheric object, never a fake chart. */
    .sm-orbit-instrument { position: absolute; inset: 0; pointer-events: none; isolation: isolate; }
    .sm-instrument-halo { position: absolute; inset: 3%; border-radius: 50%; background: radial-gradient(circle,#578ff433,transparent 68%); }
    .sm-instrument-ring { position: absolute; border: 1px solid #8dbfff55; border-radius: 50%; box-shadow: inset 0 0 18px #679aff0a; }
    .sm-ring-outer { inset: 4%; border-style: dashed; animation: sm-instrument-turn 80s linear infinite; }
    .sm-ring-middle { inset: 17%; border-top: 2px solid #a4d4ff; border-bottom-color: #3264a8; transform: rotate(-35deg); }
    .sm-ring-inner { inset: 28%; border-color: #9bc6ff55; background: radial-gradient(circle at 30% 15%,#bddcff20,#1e497522); box-shadow: inset 0 1px #b7dbff55,0 0 35px #5597ff16; }
    .sm-instrument-axis { position: absolute; left: 0; top: 50%; width: 100%; border-top: 1px solid #91c4ff22; transform: rotate(-35deg); }
    .sm-instrument-satellite { position: absolute; left: 18%; top: 19%; width: 8px; height: 8px; border-radius: 50%; background: #b2deff; box-shadow: 0 0 0 6px #69aaff16,0 0 24px #9acaff; }

    /* INVENTORY — asymmetric observatory and records, instead of a wide table. */
    body.sm-app[data-sm-screen] main .sm-stock-workspace { display: grid; grid-template-columns: minmax(250px,.8fr) minmax(0,2fr); gap: 28px; align-items: start; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-rail { position: relative; padding: 32px 28px; overflow: hidden; border-radius: 28px 28px 90px 28px; border: 1px solid #396aa6; background: radial-gradient(ellipse at 0 0,#447ccb55,transparent 65%),linear-gradient(155deg,#102d51,#0b203f 80%); box-shadow: 0 22px 45px #14376322,inset 0 1px #a0caff30; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-rail .sm-overline { color: #adc9ee; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-rail h1 { color: #f1f6ff; font-size: clamp(30px,2.7vw,42px); }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-lead { color: #c1d5f1; margin-bottom: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-instrument { position: relative; width: min(100%,280px); aspect-ratio: 1; margin: 18px auto; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-instrument-reading { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-instrument-reading strong { color: #eff7ff; font-size: 54px; font-weight: 450; line-height: 1; font-variant-numeric: tabular-nums; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-instrument-reading span { color: #bed6f6; font-size: 12px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-actions .acciones-superiores { margin: 0; display: block; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-actions .btn-nuevo-lote { width: 100%; text-align: center; min-height: 50px; background: linear-gradient(110deg,#3a79ec,#508eec); border-color: #80b0fa; box-shadow: 0 8px 25px #06172b40,inset 0 1px #d4e7ff55; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-navigation .contenedor-navegacion { display: flex; flex-direction: column; align-items: stretch; gap: 9px; margin: 22px 0 12px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-navigation a { background: transparent; border: 1px solid #52759c66; color: #d7e7fc; padding: 12px; font-size: 13px; box-shadow: none; text-align: left; border-radius: 10px; white-space: normal; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-navigation a:hover { background: #8ab8ff16; border-color: #82a9df; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-content { min-width: 0; padding-top: 10px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-workspace-heading { display: flex; justify-content: space-between; gap: 20px; align-items: center; margin: 0 0 28px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-key { display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between; color: #516d90; font-size: 12px; padding: 0 5px 15px; border-bottom: 1px solid #c7d8ee; margin-bottom: 18px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 16px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-record { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 20px; padding: 24px; border: 1px solid #c9d9ee; border-radius: 20px; background: linear-gradient(125deg,#fff,#f8fbff); box-shadow: 0 5px 18px #1d4e8110; transition: border-color .22s,box-shadow .22s; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-record:hover { border-color: #83a9df; box-shadow: 0 10px 28px #21549517; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-product { display: flex; align-items: center; gap: 15px; min-width: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-record-icon { display: grid; place-items: center; width: 46px; height: 50px; flex-shrink: 0; border: 1px solid #c6daf5; border-radius: 12px; color: #3972c4; background: #eef5ff; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-record-icon svg { width: 27px; height: 27px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-product h3 { font-size: 20px; font-weight: 600; color: #21476f; line-height: 1.4; margin: 0 0 5px; overflow-wrap: anywhere; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-lot { color: #516d8d; font-size: 13px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-record > .btn-editar { grid-column: 2; grid-row: 1; align-self: center; border: 1px solid #bacfeb; padding: 9px 16px; white-space: nowrap; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-facts { grid-row: 2; grid-column: 1 / -1; display: grid; grid-template-columns: 1fr .8fr 1.3fr; gap: 20px; margin: 0; padding-top: 18px; border-top: 1px solid #dfE8f4; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-facts dt { color: #536b88; font-size: 12px; font-weight: 500; margin-bottom: 7px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-facts dd { margin: 0; color: #24496f; font-size: 15px; font-weight: 600; overflow-wrap: anywhere; }
    body.sm-app[data-sm-screen] main .sm-reimagined .cantidad-lote { padding: 0; border: none; background: transparent; color: #245dc4; font-size: 23px; line-height: 1.1; font-variant-numeric: tabular-nums; }

    /* DOSING — an open preparation desk, then a reusable label library. */
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-heading { display: grid; grid-template-columns: minmax(0,1fr) 230px; gap: 25px; align-items: center; padding: 12px 26px 20px 4px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-heading h1 { margin: 15px 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-heading h1 em { color: #4376bd; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-heading p { color: #4b6585; max-width: 600px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-orbit { position: relative; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle,#173e6b 35%,#305b8c 65%,#a2c5f010 66%); box-shadow: 0 20px 45px #2c599517; }
    body.sm-app[data-sm-screen] main .sm-reimagined .dosif-aviso { margin: 0 0 26px; background: #e8f1ff; border: 1px solid #b4cdec; border-left: 4px solid #578bd6; color: #325a86; padding: 16px 22px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-studio { display: flex; flex-direction: column; gap: 38px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-composer { width: 100%; padding: 0; border: 1px solid #b8ceec; border-radius: 24px; background: #fff; box-shadow: 0 16px 40px #204b8110; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-composer-title { display: flex; gap: 18px; align-items: center; padding: 24px 28px; border-bottom: 1px solid #d7e3f3; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-step-number { font-size: 28px; font-weight: 350; color: #4c80c7; padding-right: 18px; border-right: 1px solid #ccdcf1; }
    body.sm-app[data-sm-screen] main .sm-reimagined #formDosificacion { display: grid; grid-template-columns: minmax(0,1fr) 290px; margin: 0; padding: 0; background: none; border: none; border-radius: 0 0 24px 24px; box-shadow: none; max-width: none; width: 100%; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-fields { display: grid; grid-template-columns: 1.2fr 1fr; gap: 28px; padding: 30px; }
    body.sm-app[data-sm-screen] main .sm-reimagined fieldset { min-width: 0; border: 0; padding: 0; margin: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined legend { float: none; width: auto; font-size: 16px; font-weight: 600; color: #2d5687; margin: 0 0 24px; padding: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-proof { background: radial-gradient(ellipse at top right,#396da455,transparent 80%),#123357; padding: 30px 25px; color: #eaf3ff; border-radius: 0 0 23px 0; display: flex; flex-direction: column; gap: 22px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-proof-heading { display: flex; gap: 12px; align-items: center; color: #c8e0ff; font-size: 15px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-proof-heading svg { width: 27px; height: 27px; }
    body.sm-app[data-sm-screen] main .sm-reimagined #resumenDosif { background: #ffffff09; border: 1px dashed #88b6ed80; border-radius: 12px; padding: 20px; color: #e7f2ff; font-size: 14px; line-height: 1.85; box-shadow: none; margin: 0; overflow-wrap: anywhere; }
    body.sm-app[data-sm-screen] main .sm-reimagined #resumenDosif strong { color: #fff; }
    body.sm-app[data-sm-screen] main .sm-reimagined #btnCrearDosif { margin-top: auto; min-height: 54px; white-space: normal; background: #4385ee; border-color: #80b0f7; line-height: 1.5; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-library { width: 100%; border: none; border-radius: 0; background: transparent; box-shadow: none; padding: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-library-heading { display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: wrap; padding: 0 0 22px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-library-heading h2 { margin: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .btn-scan { padding: 12px 18px; border: 1px solid #abc6eb; border-radius: 10px; background: #e6effd; color: #2b598f; font-size: 14px; text-decoration: none; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-program-library { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(310px,100%),1fr)); gap: 20px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .programacion { display: flex; flex-direction: column; align-items: stretch; gap: 22px; margin: 0; padding: 24px; border-radius: 19px; border: 1px solid #c3d6ef; background: #fff; box-shadow: 0 7px 20px #173e7110; position: relative; transition: border-color .2s,box-shadow .2s; }
    body.sm-app[data-sm-screen] main .sm-reimagined .programacion::before { content: ""; height: 3px; position: absolute; top: -1px; left: 25px; right: 65%; border-radius: 3px; background: linear-gradient(90deg,#7ea8ef,#3e77cf); }
    body.sm-app[data-sm-screen] main .sm-reimagined .programacion:hover { border-color: #7da8e2; box-shadow: 0 12px 28px #173e711a; }
    body.sm-app[data-sm-screen] main .sm-reimagined .programacion > div > strong { display: block; color: #234973; font-size: 18px; line-height: 1.5; margin-bottom: 12px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .programacion-codigo { display: block; border: 0; border-top: 1px dashed #afc8ea; border-radius: 0; padding: 16px 0 0; margin-top: 18px; background: transparent; font-size: 14px; letter-spacing: .8px; color: #2b5d9f; }
    body.sm-app[data-sm-screen] main .sm-reimagined .reimpresion { display: flex; gap: 10px; margin-top: auto; align-items: center; padding: 0; box-shadow: none; background: transparent; border: none; }
    body.sm-app[data-sm-screen] main .sm-reimagined .reimpresion input[type="number"] { width: 85px; margin: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .btn-reimprimir { flex: 1; min-height: 46px; margin: 0; }

    /* HISTORY — a query console beside a semantic event stream. */
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-heading { display: flex; align-items: center; gap: 24px; margin: 10px 0 34px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-heading h1 { margin: 9px 0 12px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-heading p { color: #4b6585; margin: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-grid { display: grid; grid-template-columns: 280px minmax(0,1fr); gap: 30px; align-items: start; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-console { padding: 26px; border: 1px solid #bdcfe9; border-radius: 24px; background: linear-gradient(155deg,#e3edfc,#f6f9ff); box-shadow: inset 0 1px #fff,0 9px 26px #193f7310; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-console-heading h2 { font-size: 24px; margin-top: 12px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-console-heading p { font-size: 14px; color: #4f688a; }
    body.sm-app[data-sm-screen] main .sm-reimagined .historial-herramientas { display: flex; flex-direction: column; padding: 0; gap: 24px; border: 0; border-radius: 0; background: transparent; box-shadow: none; margin: 24px 0 0; align-items: stretch; }
    body.sm-app[data-sm-screen] main .sm-reimagined :is(.form-busqueda,.form-filtros) { display: flex; flex-direction: column; align-items: stretch; gap: 12px; min-width: 0; width: 100%; max-width: none; padding: 0; background: transparent; box-shadow: none; border: none; }
    body.sm-app[data-sm-screen] main .sm-reimagined .form-filtros { border-top: 1px solid #bed1ec; padding-top: 24px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .filtro-campo { min-width: 0; width: 100%; }
    body.sm-app[data-sm-screen] main .sm-reimagined .filtro-busqueda { min-width: 0; width: 100%; }
    body.sm-app[data-sm-screen] main .sm-reimagined .filtro-busqueda input { font-size: 14px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .btn-limpiar { text-align: center; padding: 12px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-ledger { min-width: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .historial-resumen-filtros { padding: 18px 22px; border: 1px solid #3c6caa; border-radius: 15px; background: radial-gradient(ellipse at top right,#3c70ac88,transparent 65%),#15385e; color: #d9e9fc; margin-bottom: 24px; display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
    body.sm-app[data-sm-screen] main .sm-reimagined .historial-resumen-filtros strong { color: #fff; font-size: 22px; font-weight: 500; margin-left: 5px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .filtro-activo { color: #e0edff; background: #7fa9e522; border: 1px solid #8db1e755; padding: 6px 10px; border-radius: 7px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-stream { position: relative; padding-left: 20px; border-left: 1px solid #aac6ec; margin-left: 7px; display: grid; gap: 20px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-event { display: grid; grid-template-columns: 80px minmax(0,1fr) auto; gap: 16px 20px; position: relative; padding: 23px; background: #fff; border: 1px solid #cbdaf0; border-radius: 18px; box-shadow: 0 6px 20px #183f700a; transition: border-color .2s,box-shadow .2s; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-event::before { content: ""; width: 9px; height: 9px; border: 2px solid #7ba5df; background: #edf4ff; border-radius: 50%; position: absolute; left: -26px; top: 30px; box-shadow: 0 0 0 5px #edf3fc; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-event:hover { border-color: #90b3e3; box-shadow: 0 9px 24px #1b477e12; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-event > div { min-width: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-id { grid-column: 1; grid-row: 1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-person { grid-column: 2; grid-row: 1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-date { grid-column: 3; grid-row: 1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-detail { grid-column: 1 / -1; border-top: 1px solid #e0e9f6; padding-top: 16px; font-size: 14px; line-height: 1.7; overflow-wrap: anywhere; }
    body.sm-app[data-sm-screen] main .sm-reimagined .historial-id { display: inline-block; margin-top: 6px; padding: 4px 8px; border-radius: 6px; background: #edf4ff; color: #315d98; font-size: 13px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .responsable-historial { margin-top: 6px; color: #2d5077; font-size: 14px; overflow-wrap: anywhere; }
    body.sm-app[data-sm-screen] main .sm-reimagined .fecha-historial { margin-top: 6px; display: flex; flex-direction: column; gap: 2px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .fecha-dia { font-size: 14px; color: #32567c; }
    body.sm-app[data-sm-screen] main .sm-reimagined .fecha-hora { font-size: 13px; color: #547095; }
    body.sm-app[data-sm-screen] main .sm-reimagined :is(.descripcion-movimiento,.evento-card) { background: #f5f8fe; padding: 18px; border-color: #d9e4f3; }
    body.sm-app[data-sm-screen] main .sm-reimagined .paginacion { gap: 8px; flex-wrap: wrap; padding: 24px 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .contenedor-volver { text-align: left; margin-top: 28px; }

    /* One short entrance for structural sections; controls never await motion. */
    body.sm-app[data-sm-screen] main .sm-reimagined :is(.sm-stock-content,.sm-dose-composer,.sm-dose-library,.sm-history-ledger) { animation: sm-workspace-enter .42s cubic-bezier(.2,.65,.25,1) both; }
}
@keyframes sm-instrument-turn { to { transform: rotate(360deg); } }
@keyframes sm-workspace-enter { from { opacity: .75; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@media screen and (max-width: 1200px) {
    body.sm-app[data-sm-screen] main .sm-reimagined #formDosificacion { grid-template-columns: minmax(0,1fr); }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-proof { border-radius: 0 0 23px 23px; display: grid; grid-template-columns: 1fr 1.5fr; align-items: center; }
