    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-id { grid-column: 1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-date { grid-column: 2; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-event-person { grid-column: 1 / -1; grid-row: 2; }
}
@media screen and (max-width: 900px) {
