    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-instrument { grid-column: 2; grid-row: 1 / 4; max-width: 230px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-rail > :is(h1,.sm-overline,.sm-lead) { grid-column: 1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-actions { grid-column: 1 / -1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-navigation { grid-column: 1 / -1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-rail-navigation .contenedor-navegacion { flex-direction: row; flex-wrap: wrap; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-grid { grid-template-columns: minmax(0,1fr); }
    body.sm-app[data-sm-screen] main .sm-reimagined .historial-herramientas { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .form-filtros { border: 0; padding: 0; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-heading { grid-template-columns: minmax(0,1fr) 160px; padding-right: 0; }
}
@media screen and (max-width: 600px) {
    body.sm-app[data-sm-screen] main .sm-reimagined h1 { font-size: 32px; letter-spacing: -1px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-rail { padding: 25px; display: block; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-instrument { width: 190px; margin: 12px auto; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-record { padding: 18px; gap: 16px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-product { grid-column: 1 / -1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-record > .btn-editar { grid-row: 3; grid-column: 1 / -1; text-align: center; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-facts { grid-template-columns: 1fr 1fr; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-stock-facts > div:last-child { grid-column: 1 / -1; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-heading { grid-template-columns: minmax(0,1fr); }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-orbit { display: none; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-fields { grid-template-columns: minmax(0,1fr); gap: 12px; padding: 24px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-dose-proof { display: flex; align-items: stretch; padding: 24px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-composer-title { padding: 22px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-heading { align-items: start; gap: 15px; }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-heading .sm-workspace-symbol { display: none; }
    body.sm-app[data-sm-screen] main .sm-reimagined .historial-herramientas { grid-template-columns: minmax(0,1fr); }
    body.sm-app[data-sm-screen] main .sm-reimagined .sm-history-event { padding: 18px; }
}
@media (prefers-reduced-motion: reduce) {
