}
.sm-motion-paused .sm-reimagined *, .sm-motion-paused .sm-reimagined *::before, .sm-motion-paused .sm-reimagined *::after { animation: none !important; transition: none !important; }
@media print {
    .sm-orbit-instrument { display: none; }
    .sm-reimagined *, .sm-reimagined *::before, .sm-reimagined *::after { animation: none !important; transition: none !important; }
}

