/* SARMedix · Órbita 2 — real Razor screens.
   Scope is explicit per rendered VIEW, including POST error redisplays.
   All legacy styles, DOM relationships, handlers and visibility states remain.
   Screen-only styling deliberately leaves labels and reports unchanged in print. */
@media screen {
    :root { --sm-surface: #fff; --sm-surface-soft: #f2f7ff; --sm-outline: #ccdbef; --sm-title: #173b64; --sm-secondary: #4b6380; --sm-round: 20px; }
    .sm-screen-identity { width: 100%; max-width: 1400px; display: flex; justify-content: space-between; align-items: center; gap: 16px; margin: 0 auto 24px; color: #496382; }
    .sm-screen-family { display: inline-flex; align-items: center; gap: 12px; font-size: 11px; letter-spacing: 1.6px; font-weight: 650; }
    .sm-screen-family .sm-icon { width: 25px; height: 25px; color: #356fc6; }
    .sm-screen-edition { display: inline-flex; align-items: center; gap: 8px; font-size: 10px; letter-spacing: 2px; color: #587294; }
    .sm-screen-edition > span { padding: 4px 7px; border: 1px solid #b6cceb; border-radius: 7px; color: #265493; background: #edf4ff; }

    /* Screen frame, without moving any form children. */
    body.sm-app[data-sm-family]:not([data-sm-family="home"]) main[role="main"] { justify-content: flex-start; align-items: center; padding: 32px clamp(18px,3vw,44px) !important; gap: 0; }
    body.sm-app[data-sm-family] main > :is(.usuarios-card,.historial-card,.productos-contenedor,.submenu-contenedor,.contenedor,.contenedor-roles-inactivos,.contenedor-crear-rol,.contenedor-editar-rol,.entrada-pagina,.ubicaciones-pagina,.inventario-ubicacion-pagina,.traslado-pagina,.salida-pagina,.extra-pagina,.dosif-pagina,.scan-pagina,.turno-pagina,.hist-pagina,.controlados-pagina,.print-pagina) { width: 100%; max-width: 1400px; margin: 0 auto; min-width: 0; box-sizing: border-box; }
    body.sm-app[data-sm-family] main > :is(.usuarios-card,.historial-card,.productos-contenedor,.submenu-contenedor) { padding: 0; background: transparent; box-shadow: none; overflow: visible; }
    body.sm-app[data-sm-family] main > :is(.contenedor-crear-rol,.contenedor-editar-rol) { max-width: 820px; }
    body.sm-app[data-sm-family] :is(.usuarios-titulo,.historial-titulo,.productos-titulo,.submenu-titulo,.entrada-encabezado,.ubicaciones-encabezado,.inventario-encabezado,.traslado-encabezado,.salida-titulo,.extra-titulo,.dosif-encabezado,.scan-encabezado,.turno-encabezado,.hist-titulo,.controlados-encabezado) {
        position: relative; isolation: isolate; padding: 30px 34px; border-radius: 22px; margin: 0 0 25px; text-align: left;
        background: radial-gradient(ellipse at 95% 0,#4d8fdb4d,transparent 60%),linear-gradient(115deg,#0d284c,#19477c);
        border: 1px solid #4776ac; box-shadow: inset 0 1px #b7d8ff30,0 14px 32px #163e7517; color: #e4f0ff;
    }
    body.sm-app[data-sm-family] :is(.usuarios-titulo,.historial-titulo,.productos-titulo,.submenu-titulo,.entrada-encabezado,.ubicaciones-encabezado,.inventario-encabezado,.traslado-encabezado,.salida-titulo,.extra-titulo,.dosif-encabezado,.scan-encabezado,.turno-encabezado,.hist-titulo,.controlados-encabezado) :is(h1,h2) { color: #f1f7ff; text-align: left; font-size: clamp(27px,2.8vw,40px); letter-spacing: -1px; font-weight: 550; line-height: 1.2; margin: 0 0 10px; }
    body.sm-app[data-sm-family] :is(.usuarios-titulo,.historial-titulo,.productos-titulo,.submenu-titulo,.entrada-encabezado,.ubicaciones-encabezado,.inventario-encabezado,.traslado-encabezado,.salida-titulo,.extra-titulo,.dosif-encabezado,.scan-encabezado,.turno-encabezado,.hist-titulo,.controlados-encabezado) p { color: #d1e2fa; font-size: 15px; line-height: 1.7; margin: 0; }
    body.sm-app[data-sm-family] :is(.titulo-crear-rol,.titulo-editar-rol,.titulo-roles-inactivos,.contenedor > .titulo) { color: var(--sm-title); font-size: 32px; font-weight: 600; letter-spacing: -.8px; text-align: left; margin: 0 0 25px; }

    /* Reusable surfaces and readable forms; no display/visibility overrides. */
    body.sm-app[data-sm-family] :is(.tarjeta-crear-rol,.tarjeta-editar-rol,.tarjeta-roles-inactivos,.contenedor > .tarjeta,.entrada-seccion,.traslado-panel,.salida-pagina .panel,.extra-pagina .panel,.dosif-panel,.scan-panel,.controlados-panel,.tabla-panel,.filtro-turno) { background: #fff; border: 1px solid var(--sm-outline); border-radius: var(--sm-round); box-shadow: 0 10px 28px #163e750d; padding: 26px; }
    body.sm-app[data-sm-family] :is(.tarjeta-crear-rol,.tarjeta-editar-rol) { padding: 32px; }
    body.sm-app[data-sm-family] main form :is(input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]),select,textarea),
    body.sm-app[data-sm-family] main :is(.ubicaciones-buscador,.controlados-buscador,.controlados-filtro-campo,.selector-productos) :is(input,select) {
        box-sizing: border-box; max-width: 100%; min-height: 46px; border: 1px solid #b6c9e4; border-radius: 10px; background-color: #fbfdff; color: #1d3c61; font-family: inherit; font-size: 15px; padding: 11px 14px;
        transition: border-color .18s,box-shadow .18s,background-color .18s;
    }
    body.sm-app[data-sm-family] main form :is(input,select,textarea):focus { border-color: #397be4; box-shadow: 0 0 0 4px #397be418; background-color: #fff; }
    body.sm-app[data-sm-family] main form :is(input,select,textarea):disabled { background-color: #edf1f7; color: #52647a; border-color: #ccd6e3; cursor: not-allowed; }
    body.sm-app[data-sm-family] main form input[readonly] { background-color: #edf3fb; }
    body.sm-app[data-sm-family] main form :is(input[type="checkbox"],input[type="radio"]) { accent-color: #2864d4; width: 19px; height: 19px; min-height: 0; box-shadow: none; flex-shrink: 0; }
    body.sm-app[data-sm-family] main label { font-size: 14px; line-height: 1.5; font-weight: 600; color: #264565; }
    body.sm-app[data-sm-family] main textarea { min-height: 110px; line-height: 1.6; }
    body.sm-app[data-sm-family] :is(.campo-ayuda,.ayuda-codigo,.ayuda-stock,.subtitulo,.seccion-descripcion,.grupo-campo small,.campo small,.mc-contador,.permiso-descripcion) { color: #4f6681; font-size: 13px; line-height: 1.65; }

    /* Semantic actions are now defined once in sarmedix-global.css. */
    /* Data tables retain all columns, row toggles, actions and semantic tables. */
    body.sm-app[data-sm-family] :is(.tabla-contenedor,.tabla-wrap,.inventario-tabla-contenedor,.controlados-tabla-contenedor,.controlados-subtabla-contenedor,.controlados-historial-tabla-contenedor) { width: 100%; max-width: 100%; min-width: 0; overflow-x: auto; border: 1px solid #cbdaf0; border-radius: 15px; background: #fff; box-shadow: 0 9px 25px #153b6e0b; overscroll-behavior-x: contain; }
    body.sm-app[data-sm-family] main table { width: 100%; min-width: 720px; table-layout: auto; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; }
    body.sm-app[data-sm-family] main table th { background: #e8f0fb; color: #355478; border-bottom: 1px solid #ccdaed; font-size: 12px; line-height: 1.5; padding: 16px 18px; text-align: left; white-space: nowrap; }
    body.sm-app[data-sm-family] main table td { border-bottom: 1px solid #e1eaf6; color: #36516f; font-size: 14px; line-height: 1.55; padding: 18px; vertical-align: middle; white-space: normal; overflow: visible; text-overflow: clip; }
    body.sm-app[data-sm-family] main table tbody tr:hover > td { background-color: #f1f6ff; }
    body.sm-app[data-sm-family] main table tbody tr:focus-within > td { background-color: #edf4ff; }
    body.sm-app[data-sm-family] main table td :is(.acciones-contenido,.acciones-usuario,.controlados-acciones-movimiento) { flex-wrap: wrap; gap: 8px; }
    body.sm-app[data-sm-family] :is(.paginacion,.historial-paginacion) a { border-radius: 9px; min-height: 40px; font-size: 14px; }

    /* Modal surface, not its display, z-index, visibility or confirmation logic. */
    body.sm-app[data-sm-family] :is(.modal-fondo,.ubicacion-modal-fondo,.mc-overlay,.mcc-overlay) { background-color: #071b3894; backdrop-filter: blur(5px); padding: 18px; overflow-y: auto; }
    body.sm-app[data-sm-family] :is(.modal-contenido,.ubicacion-modal,.mc-modal,.mcc-modal) { border: 1px solid #bcd4f5; border-top: 3px solid #5e9af0; border-radius: 22px; background-color: #fff; box-shadow: 0 25px 75px #051b3c50; max-width: calc(100vw - 36px); max-height: calc(100dvh - 36px); overflow-y: auto; animation: sm-system-panel .2s ease-out; }
    body.sm-app[data-sm-family] :is(.modal-icono,.ubicacion-confirmacion-icono,.mc-icono,.mcc-icono) { border-radius: 16px; }
    body.sm-app[data-sm-family] :is(.modal-contenido,.ubicacion-modal,.mc-modal,.mcc-modal) :is(h2,.modal-titulo) { font-size: 24px; letter-spacing: -.5px; line-height: 1.3; }
    body.sm-app[data-sm-family] :is(.modal-contenido,.ubicacion-modal,.mc-modal,.mcc-modal) p { font-size: 15px; line-height: 1.7; }
    body.sm-app[data-sm-family] :is(.modal-botones,.ubicacion-confirmacion-pie,.ubicacion-modal-pie,.mc-botones,.mcc-botones) { flex-wrap: wrap; gap: 12px; }
    body.sm-app[data-sm-family] :is(.mensaje,.mensaje-error,.mensaje-exito,.mensaje-validacion-campo,.ubicaciones-mensaje,.controlados-mensaje,.dosif-mensaje,.traslado-mensaje,.mc-error-general) { border-radius: 11px; font-size: 14px; line-height: 1.6; }
    /* Error borders still belong to site.css and its .campo-error !important rule. */
    body.sm-app[data-sm-family] :is(.aviso,.traslado-aviso,.dosif-aviso,.nota,.controlados-info,.ubicaciones-info,.entrada-aviso) { border-radius: 13px; line-height: 1.7; font-size: 14px; }
    body.sm-app[data-sm-family] :is(.sin-registros,.sin-usuarios,.sin-stock,.sin-programaciones,.sin-salidas,.vacio,.inventario-vacio,.ubicaciones-vacio) { padding: 35px 24px; border: 1px dashed #aac4e7; border-radius: 16px; color: #496383; background: radial-gradient(ellipse at top,#e8f1ff,transparent 80%),#fff; font-size: 15px; }

    /* Access: quieter orbital environment, single-column, readable messages. */
    body.sm-app[data-sm-family="access"] { background: radial-gradient(ellipse at 15% 25%,#356eb55c,transparent 45%),radial-gradient(ellipse at 90% 75%,#2c659e66,transparent 55%),#0d2545; }
    body.sm-app[data-sm-family="access"] main[role="main"] { padding-top: 38px !important; padding-bottom: 48px !important; }
    body.sm-app[data-sm-family="access"] .sm-screen-identity { max-width: 560px; color: #d7e7fc; }
    body.sm-app[data-sm-family="access"] .sm-screen-family .sm-icon { color: #a3cfff; }
    body.sm-app[data-sm-family="access"] .sm-screen-edition { color: #b5cceb; }
    body.sm-app[data-sm-family="access"] main > h2 { max-width: 560px; padding: 32px 32px 22px; background: #fff; border-radius: 22px 22px 0 0; box-shadow: none; color: #173b64; font-size: 30px; letter-spacing: -.6px; }
    body.sm-app[data-sm-family="access"] main > h2::before { width: 54px; height: 54px; font-size: 34px; border-radius: 15px; background: linear-gradient(135deg,#2d67d9,#6c9ff0); margin-bottom: 20px; }
    body.sm-app[data-sm-family="access"] main > h2::after { font-size: 13px; letter-spacing: 1px; color: #536b88; }
    body.sm-app[data-sm-family="access"] main > form { width: 100%; max-width: 560px; padding: 26px 32px 32px; box-sizing: border-box; background: #fff; border-radius: 0 0 22px 22px; box-shadow: 0 22px 45px #04152c35; }
    body.sm-app[data-sm-family="access"] main > p { width: 100%; max-width: 560px; margin: 0; padding: 10px 32px; background: #fff; color: #405c7b; font-size: 15px; line-height: 1.6; box-sizing: border-box; }
    body.sm-app[data-sm-family="access"] main > a { color: #d5e7ff; font-size: 14px; margin-top: 20px; }
    body.sm-app[data-sm-family="access"] main form :is(input,select) { width: 100%; margin: 7px 0 18px; }
    body.sm-app[data-sm-family="access"] main form button[type="submit"] { width: 100%; min-height: 48px; padding: 12px 16px; border: 1px solid #2159ce; border-radius: 11px; background: linear-gradient(110deg,#245de2,#397dea); color: white; font: inherit; font-weight: 600; cursor: pointer; }
    body.sm-app[data-sm-family="access"] .contenedor-recuperacion { width: 100%; max-width: 560px; padding: 0; }
    body.sm-app[data-sm-family="access"] .tarjeta-recuperacion { width: 100%; max-width: none; border: 1px solid #c5d8f2; border-radius: 22px; padding: 32px; background: white; box-shadow: 0 22px 45px #04152c35; }

    /* Administration and catalog forms keep their original order and IDs. */
    body.sm-app[data-sm-family]:not([data-sm-family="access"]) main > h2 { width: 100%; max-width: 820px; text-align: left; padding: 28px 32px; background: linear-gradient(115deg,#102d53,#23558f); color: #f1f7ff; border: 1px solid #426da4; border-radius: 20px 20px 0 0; box-shadow: none; font-size: 30px; margin: 0; }
