    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .acciones-informe { gap: 12px; flex-wrap: wrap; margin-bottom: 22px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .acciones-informe :is(a,button) { font-family: inherit; font-size: 14px; border-radius: 10px; padding: 12px 18px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .btn-imprimir { background: #285fd6; color: #fff; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .documento { padding: 36px; border: 1px solid #c5d8f0; border-radius: 22px; box-shadow: 0 18px 50px #173f7514; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .cabecera { border-bottom: 2px solid #91b6e8; padding-bottom: 25px; flex-wrap: wrap; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .marca { color: #2a63b3; font-size: 15px; letter-spacing: 1px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] h1 { color: #1a3c66; font-size: clamp(26px,3vw,34px); letter-spacing: -.8px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] :is(.subtitulo,.folio,.seccion-titulo p,.conc) { color: #4e6786; font-size: 13px; line-height: 1.7; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .datos-corte { gap: 14px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .dato { padding: 18px; background: #f0f6ff; border: 1px solid #cbdcf2; border-radius: 12px; overflow-wrap: anywhere; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .dato small { color: #4c688a; font-size: 11px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .dato strong { color: #224d80; font-size: 15px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .seccion-titulo h2 { color: #214972; font-size: 23px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .tabla-wrap { border: 1px solid #cbdaf0; border-radius: 12px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] table { min-width: 680px; font-variant-numeric: tabular-nums; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] th { padding: 15px; background: #e8f0fb; color: #355478; font-size: 12px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] td { padding: 15px; font-size: 14px; line-height: 1.6; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] :is(.resumen-nota,.pie) { font-size: 12px; line-height: 1.7; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] :is(.controlado,.normal) { font-size: 11px; padding: 4px 8px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .resumen-nota { border-left-color: #407ed7; border-radius: 8px; background: #eef5ff; }

    body.sm-app[data-sm-family="error"] main > :is(h1,h2,h3,p) { width: 100%; max-width: 820px; text-align: left; line-height: 1.7; }
    body.sm-app[data-sm-family="error"] main > h1 { font-size: 38px; margin-bottom: 15px; }
    body.sm-app[data-sm-family="error"] main > h2 { font-size: 23px; border-radius: 18px; margin-bottom: 24px; }
    body.sm-app[data-sm-family="error"] main > p { font-size: 15px; color: #405d7e; overflow-wrap: anywhere; }
    body.sm-app[data-sm-family="error"] main > h3 { color: #244a77; font-size: 21px; margin-top: 24px; }
}
@keyframes sm-system-panel { from { opacity: .85; } to { opacity: 1; } }
body.sm-app.sm-motion-paused[data-sm-family] .submenu-card:hover { transform: none; }
@media screen and (max-width: 760px) {
    body.sm-app[data-sm-family]:not([data-sm-family="home"]) main[role="main"] { padding: 24px 16px !important; }
    .sm-screen-edition { display: none; }
    .sm-screen-family { font-size: 10px; letter-spacing: 1px; }
    body.sm-app[data-sm-family] :is(.usuarios-titulo,.historial-titulo,.productos-titulo,.submenu-titulo,.entrada-encabezado,.ubicaciones-encabezado,.inventario-encabezado,.traslado-encabezado,.salida-titulo,.extra-titulo,.dosif-encabezado,.scan-encabezado,.turno-encabezado,.hist-titulo,.controlados-encabezado) { padding: 25px; border-radius: 18px; }
    body.sm-app[data-sm-family] :is(.tarjeta-crear-rol,.tarjeta-editar-rol,.tarjeta-roles-inactivos,.contenedor > .tarjeta,.entrada-seccion,.traslado-panel,.salida-pagina .panel,.extra-pagina .panel,.dosif-panel,.scan-panel,.controlados-panel,.tabla-panel,.filtro-turno) { padding: 19px; }
    body.sm-app[data-sm-family] main > form.formulario-principal, body.sm-app[data-sm-family] main > h2 { padding-left: 24px !important; padding-right: 24px !important; }
    body.sm-app[data-sm-family] :is(.form-busqueda,.form-filtros,.historial-herramientas,.acciones-rol,.controlados-form-filtros) { flex-wrap: wrap; max-width: 100%; min-width: 0; }
    body.sm-app[data-sm-family="movements"] :is(.traslado-grid,.grid), body.sm-app[data-sm-family="dosing"] .dosif-grid { grid-template-columns: minmax(0,1fr); }
    body.sm-app[data-sm-family="controlled"] .controlados-detalle { padding: 14px; }
    body.sm-app[data-sm-family="history"] .hist-pagina .filtro { flex-wrap: wrap; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] { padding: 18px 12px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .documento { padding: 22px 18px; }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .datos-corte { grid-template-columns: repeat(2,minmax(0,1fr)); }
    body.sm-standalone[data-sm-screen="InformeSalidasTurno"] .folio { text-align: left; min-width: 0; }
}
@media (prefers-reduced-motion: reduce) {
    body.sm-app[data-sm-family] *, body.sm-app[data-sm-family] *::before, body.sm-app[data-sm-family] *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
    body.sm-app[data-sm-family] .submenu-card:hover { transform: none; }
}
@media print { .sm-screen-identity { display: none !important; } }

LoginSARMedix/wwwroot/css/sarmedix-ui.cs.text:
/* SARMedix / Órbita. Phase one.
   Existing business selectors and scripts remain intact. Page styles are scoped
   to .pagina-modulos and .sm-inventory; shared styles target only the app shell.
   No remote assets or font requests. */
:root {
    --sm-ink: #142b49;
    --sm-muted: #586b82;
    --sm-blue: #245ee6;
    --sm-night: #0c203d;
    --sm-paper: #f3f6fb;
    --sm-line: #dce5f0;
    --sm-ease: cubic-bezier(.2,.75,.25,1);
    --sm-shadow: 0 12px 36px #163e7510;
}
body.sm-app {
    background: var(--sm-paper);
    color: var(--sm-ink);
    font-family: "Segoe UI", system-ui, sans-serif;
    -webkit-font-smoothing: antialiased;
}
.sm-app *, .sm-app *::before, .sm-app *::after { box-sizing: border-box; }
.sm-app :is(a, button, input, select, textarea, [tabindex]):focus-visible {
    outline: 3px solid #3e83ed !important;
    outline-offset: 4px;
}
.sm-visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.sm-skip { position: fixed; left: 20px; top: -100px; z-index: 100000; padding: 12px 20px; background: white; color: #153f8c; border-radius: 8px; }
.sm-skip:focus { top: 12px; }

/* Application frame */
.sm-app .barra-layout {
    height: 88px; padding: 0 32px 0 24px;
    grid-template-columns: 232px minmax(100px,1fr) auto; gap: 24px;
    background: #ffffffed; color: var(--sm-ink);
    border-bottom: 1px solid var(--sm-line); box-shadow: none;
    position: relative; z-index: 50;
}
.sm-app .logo-layout { gap: 11px; }
.sm-app .logo-texto-layout { color: var(--sm-ink); font-size: 25px; letter-spacing: -1px; line-height: 1; }
.sm-brand-light { font-weight: 400; }
.sm-brand-dot { color: #3279ee; }
.sm-app .logo-texto-layout small { display: block; margin-top: 8px; font-size: 8px; font-weight: 600; letter-spacing: 2.7px; color: #5e7591; }
.sm-app .logo-cruz-layout { width: 36px; height: 40px; border-radius: 11px; background: linear-gradient(145deg,#548df7,#1747b6); box-shadow: 0 5px 12px #2057c527, inset 0 1px 0 #a6c7ff; transform: rotate(-5deg); }
.sm-app .logo-cruz-layout::before { width: 20px; height: 6px; top: 17px; left: 8px; }
.sm-app .logo-cruz-layout::after { width: 6px; height: 20px; top: 10px; left: 15px; }
.sm-app .titulo-layout { justify-self: start; color: #536981; font-size: 13px; font-weight: 500; white-space: normal; border-left: 1px solid var(--sm-line); padding-left: 24px; text-align: left; }
.sm-app .usuario-layout { gap: 16px; }
.sm-app .usuario-nombre-layout { color: var(--sm-ink); font-size: 13px; }
.sm-app .usuario-rol-layout { color: var(--sm-muted); font-size: 11px; }
.sm-app .usuario-circulo-layout { width: 36px; height: 36px; border: 1px solid #d0dff6; border-radius: 12px; color: #2254aa; background: #eaf1ff; font-size: 14px; }
.sm-app .btn-cerrar-layout { color: #4b6280 !important; border-color: #dce5ef !important; font-size: 12px !important; border-radius: 8px !important; font-weight: 500 !important; }
.sm-app .btn-cerrar-layout:hover { background: #edf3ff !important; border-color: #9bb9ee !important; }
.sm-app .estructura-app { align-items: stretch; }
.sm-app .contenido-app { background: radial-gradient(ellipse at 90% 0,#e6edfc80,transparent 55%),var(--sm-paper); }
.sm-app .footer-layout { min-height: 46px; border-top: 1px solid var(--sm-line); color: #64768c; background: #f9fbff; font-size: 10px; letter-spacing: .5px; padding: 12px 20px; }

/* Navigation: quiet ink surface, luminous edge on interaction */
.sm-app .sidebar { width: 256px; min-width: 256px; padding: 32px 15px 24px; background: radial-gradient(ellipse at 0 100%,#183c69,transparent 65%),#0d2341; box-shadow: none; display: flex; flex-direction: column; }
.sm-app .sidebar-titulo { display: flex; flex-direction: column; gap: 10px; padding: 0 16px 25px; margin-bottom: 19px; font-size: 17px; letter-spacing: -.3px; border-bottom: 1px solid #ffffff12; }
.sm-nav-eyebrow { color: #98b1d4; font-size: 8px; font-weight: 500; letter-spacing: 2px; }
.sm-app .sidebar-menu { gap: 7px; }
.sm-app .sidebar-cabecera { min-height: 52px; border-radius: 10px; }
.sm-app .sidebar-cabecera:hover { background: #ffffff09; border-color: #8aaff024; box-shadow: none; transform: none; }
.sm-app .sidebar-cabecera.activo, .sm-app .sidebar-cabecera.activo:hover { background: linear-gradient(105deg,#2457ad77,#31547a30); border-color: #6d9ce34a; box-shadow: inset 3px 0 #70b8ff; }
.sm-app .sidebar-modulo-enlace { gap: 10px; font-size: 12px; font-weight: 500; color: #d0dff2; padding: 12px 4px 12px 11px; }
.sm-app .sidebar-icono { font-size: 17px; width: 25px; min-width: 25px; filter: grayscale(1); }
.sm-icon { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.sm-app .sidebar-toggle { width: 32px; min-width: 32px; color: #91add0; }
.sm-app .sidebar-flecha { font-size: 8px; }
.sm-app .sidebar-subopcion { font-size: 11px; line-height: 1.5; color: #c3d4eb; padding: 9px 10px; }
.sm-app .sidebar-subopcion:hover { background: #3b6bb62e; padding-left: 10px; transform: translateX(2px); }
.sm-app .sidebar-subopcion.activo { background: #3664a347; box-shadow: inset 2px 0 #8ccaff; }
.sm-app .sidebar-submenu { visibility: hidden; transition: max-height .24s var(--sm-ease),opacity .2s,visibility .24s; }
.sm-app .sidebar-grupo.abierto .sidebar-submenu { visibility: visible; max-height: 1200px; }
.sm-sidebar-signature { margin: auto 12px 0; padding-top: 60px; display: flex; gap: 10px; color: #b1c7e3; font-size: 10px; align-items: center; }
.sm-sidebar-signature small { display: block; font-size: 6px; letter-spacing: 1.1px; margin-top: 7px; color: #91acca; }
.sm-signature-cross { font-size: 29px; font-weight: 200; color: #84bafa; }

/* Shared notification and confirmation surfaces. Preserve visibility logic. */
.sm-app .alertas-boton { background: #edf3ff; border: 1px solid #dce6f8; color: #285db2; border-radius: 12px; box-shadow: none; }
.sm-app .alertas-panel { border: 1px solid #d8e3f5; border-radius: 18px; box-shadow: 0 22px 60px #122d5330; }
.sm-app .alertas-panel-cabecera { background: linear-gradient(115deg,#102d53,#255db2); }
.sm-app .alertas-panel-cabecera h3 { color: #f1f7ff; }
.sm-app .alertas-panel-etiqueta { color: #c0d7fa; }
.sm-app .alertas-contador { border-color: white; }
.sm-app .modal-fondo-sesion { background: #081c3b94; backdrop-filter: blur(6px); padding: 20px; }
.sm-app .modal-contenido-sesion { padding: 36px; border: 1px solid #dce7fa; border-radius: 22px; box-shadow: 0 28px 90px #06132950; }
.sm-app .modal-icono-sesion { background: #e9f1ff; color: #265bb5; border: 1px solid #d8e5ff; border-radius: 18px; }
.sm-app .modal-botones-sesion .btn-sesion-si { background: #245ee6 !important; }
.sm-app .modal-botones-sesion .btn-sesion-no { background: #e9eff9 !important; color: #25466f !important; }

/* Welcome: editorial composition and an original orbital glass mark */
.sm-app .pagina-modulos { min-height: calc(100vh - 134px); background: transparent; }
.sm-app .contenido-modulos { max-width: 1440px; padding: 30px 40px 26px; }
.sm-intro-line, .sm-inventory-kicker { display: flex; align-items: center; justify-content: space-between; gap: 15px; margin-bottom: 22px; }
.sm-eyebrow { font-size: 9px; font-weight: 650; letter-spacing: 2.2px; color: #59718f; }
.sm-context-label { color: #61758c; font-size: 11px; }
.sm-hero { position: relative; isolation: isolate; display: grid; grid-template-columns: 1.15fr 1fr; min-height: 340px; overflow: hidden; border-radius: 22px; background: #102b53; box-shadow: 0 15px 36px #123d7620; color: white; border: 1px solid #1f4781; }
.sm-hero::before { content: ""; position: absolute; inset: -25%; z-index: -1; background: radial-gradient(ellipse at 75% 45%,#2873d775,transparent 40%),radial-gradient(ellipse at 15% 100%,#3470d037,transparent 40%); animation: sm-light 14s ease-in-out infinite alternate; pointer-events: none; }
.sm-hero::after { content: ""; position: absolute; inset: 0; z-index: -1; opacity: .15; background-image: linear-gradient(#78a9f125 1px,transparent 1px),linear-gradient(90deg,#78a9f125 1px,transparent 1px); background-size: 48px 48px; mask-image: linear-gradient(90deg,transparent,black); pointer-events: none; }
.sm-hero-copy { padding: 40px 0 38px 38px; z-index: 2; }
.sm-hero-label { display: inline-flex; align-items: center; gap: 9px; color: #b7d2fa; font-size: 10px; letter-spacing: .6px; }
.sm-hero-label > span { width: 5px; height: 5px; border-radius: 50%; background: #a4d7ff; box-shadow: 0 0 12px #74baff; }
.sm-hero h1 { font-size: clamp(32px,3.35vw,54px); font-weight: 500; letter-spacing: -2.2px; line-height: 1.1; margin: 24px 0 18px; color: #f4f9ff; }
.sm-hero h1 em { font-style: normal; color: #a4ccff; }
.sm-hero p { font-size: 12px; line-height: 1.8; color: #bdd0ed; margin: 0; }
.sm-hero-foot { display: flex; align-items: center; gap: 12px; font-size: 10px; color: #adc4e5; margin-top: 30px; }
.sm-line { width: 28px; height: 1px; background: #7cabed; }
.sm-orbital { align-self: center; width: 112%; margin-left: -6%; pointer-events: none; }
.sm-orbital svg { display: block; width: 100%; height: auto; max-height: 360px; }
.sm-crystal { animation: sm-float 7s ease-in-out infinite; }
.sm-orbit-satellite { transform-origin: 260px 215px; animation: sm-orbit 28s linear infinite; }
.sm-motion-toggle { position: absolute; right: 18px; bottom: 14px; font-size: 9px; border: 1px solid #87afe648; padding: 5px 9px; border-radius: 20px; background: #112f55; color: #c1d8f6; z-index: 3; cursor: pointer; }
.sm-motion-toggle:hover { background: #234a7c; }
.sm-section-heading { display: flex; justify-content: space-between; align-items: end; gap: 20px; margin: 33px 0 20px; }
.sm-section-heading h2 { font-size: 22px; font-weight: 600; letter-spacing: -.7px; margin: 7px 0 0; color: var(--sm-ink); }
.sm-section-heading p { margin: 0 0 2px; font-size: 11px; color: var(--sm-muted); }
.sm-app .modulos { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 16px; }
.sm-app .modulo { height: auto; min-height: 172px; padding: 23px 26px; border: 1px solid #dce5f2; border-radius: 15px; background: linear-gradient(125deg,#fff,#f9fbff); box-shadow: 0 3px 4px #123c7303; transition: border-color .2s,box-shadow .24s,transform .24s var(--sm-ease); isolation: isolate; }
.sm-app .modulo::before { content: ""; position: absolute; inset: 0; z-index: -1; background: radial-gradient(350px circle at var(--sm-pointer-x,80%) var(--sm-pointer-y,0%),#dbeaff90,transparent 75%); opacity: 0; transition: opacity .3s; pointer-events: none; }
.sm-app .modulo.habilitado:hover { transform: translateY(-3px); border-color: #9bbff3; box-shadow: 0 15px 30px #1c4d9212; z-index: 1; }
.sm-app .modulo:hover::before, .sm-app .modulo:focus-visible::before { opacity: 1; }
.sm-app .modulo-titulo { display: block; color: #193653; font-size: 18px; font-weight: 600; letter-spacing: -.4px; margin-top: 17px; }
.sm-module-description { display: block; font-size: 11px; color: #60738a; font-weight: 400; letter-spacing: 0; margin-top: 7px; line-height: 1.6; }
.sm-module-top { display: flex; align-items: center; gap: 12px; color: #657c9a; font-size: 8px; letter-spacing: 1.6px; }
.sm-module-icon { display: grid; place-items: center; width: 35px; height: 35px; background: #edf3ff; border: 1px solid #dae6fc; border-radius: 10px; font-size: 25px; line-height: 1; color: #3569c7; }
.sm-module-arrow { margin-left: auto; color: #4f6f99; font-size: 20px; transition: transform .25s var(--sm-ease); }
.sm-app .modulo:hover .sm-module-arrow { transform: translate(3px,-3px); color: #245ee6; }
.sm-app .modulo .modulo-imagen { display: none; }
.sm-workspace-note { display: flex; gap: 9px; align-items: center; justify-content: center; margin-top: 24px; font-size: 10px; color: #61758f; }
.sm-workspace-note > span { font-size: 18px; color: #5282cc; }

/* Operational pilot: inventory. No business calculations or table restructuring. */
.sm-app .contenido-app main:has(.sm-inventory) { justify-content: flex-start; padding-top: 30px !important; }
.sm-app .sm-inventory { width: calc(100% - 32px); max-width: 1360px; margin: 0 auto; padding: 0; background: transparent; border-radius: 0; box-shadow: none; overflow: visible; }
.sm-inventory .usuarios-titulo { position: relative; overflow: hidden; isolation: isolate; padding: 32px 34px; border-radius: 18px; text-align: left; background: linear-gradient(115deg,#102b50,#1e4d8b); margin: 0; }
.sm-inventory .usuarios-titulo::after { content: "+"; position: absolute; right: 50px; top: -68px; z-index: -1; font-size: 240px; font-weight: 200; color: #a6ccff14; transform: rotate(-15deg); }
.sm-inventory .usuarios-titulo h1 { color: #f4f8ff; font-size: 35px; font-weight: 500; letter-spacing: -1.2px; }
.sm-inventory .usuarios-titulo p { color: #bed3f1; font-size: 12px; margin: 8px 0 0; max-width: 75%; line-height: 1.7; }
.sm-inventory .acciones-superiores { margin: 22px 0; }
.sm-inventory .btn-nuevo-lote { background: #245ee6; border: 1px solid #245ee6; border-radius: 10px; padding: 12px 19px; font-size: 12px; box-shadow: 0 5px 14px #245ee626; transition: box-shadow .2s,background .2s; }
.sm-inventory .btn-nuevo-lote:hover { background: #194dc6; box-shadow: 0 7px 20px #245ee63d; }
.sm-inventory .tabla-contenedor { background: white; border: 1px solid #dae4f1; border-radius: 14px; box-shadow: var(--sm-shadow); margin-top: 22px; }
.sm-inventory .tabla-usuarios { margin: 0; border-collapse: separate; border-spacing: 0; min-width: 720px; }
.sm-inventory .tabla-usuarios th { background: #eaf0f8; color: #47617f; text-align: left; padding: 17px 20px; font-size: 10px; font-weight: 650; white-space: nowrap; border-bottom: 1px solid #dae4f1; }
.sm-inventory .tabla-usuarios td { padding: 22px 20px; text-align: left; border-bottom: 1px solid #eaf0f7; font-size: 12px; color: #536981; transition: background .16s; }
.sm-inventory .tabla-usuarios td:first-child { color: #203f61; font-weight: 600; }
.sm-inventory .tabla-usuarios td:nth-child(2), .sm-inventory .tabla-usuarios td:nth-child(3) { font-variant-numeric: tabular-nums; }
.sm-inventory .tabla-usuarios tbody tr:hover { background: #f2f7ff; }
.sm-inventory .tabla-usuarios tbody tr:last-child td { border-bottom: 0; }
.sm-inventory .cantidad-lote { background: #eaf2ff; color: #2459ae; border: 1px solid #dce8fc; border-radius: 7px; min-width: 48px; padding: 5px 10px; font-variant-numeric: tabular-nums; }
.sm-inventory .btn-editar { background: transparent; color: #2459b0; border: 1px solid #d8e4f4; border-radius: 7px; font-size: 11px !important; }
.sm-inventory .btn-editar:hover { background: #e7efff; }
.sm-inventory .contenedor-navegacion { justify-content: space-between; margin-top: 22px; }
.sm-inventory :is(.btn-listado-productos,.btn-volver-productos) { background: transparent; color: #426080; font-size: 11px; font-weight: 500; padding: 10px 0; }
.sm-inventory :is(.btn-listado-productos,.btn-volver-productos):hover { color: #205dcc; background: transparent; }
.sm-inventory .mensaje { border-radius: 10px; font-size: 13px; }
.sm-inventory .sin-registros { background: white; border: 1px dashed #b9cce5; border-radius: 15px; padding: 48px 24px; }

@keyframes sm-float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
@keyframes sm-orbit { to { transform: rotate(360deg); } }
@keyframes sm-light { from { transform: translate(-2%,-2%) scale(1); } to { transform: translate(2%,3%) scale(1.06); } }
.sm-motion-paused .sm-hero::before, .sm-motion-paused :is(.sm-crystal,.sm-orbit-satellite) { animation-play-state: paused; }

@media (min-width: 1700px) { .sm-hero { min-height: 390px; } .sm-hero-copy { padding-top: 54px; } }
@media (max-width: 1150px) {
    .sm-app .sidebar { width: 215px; min-width: 215px; padding-left: 10px; padding-right: 10px; }
    .sm-app .barra-layout { grid-template-columns: 191px 1fr auto; padding-left: 20px; gap: 18px; }
    .sm-app .contenido-modulos { padding: 24px; }
    .sm-hero-copy { padding-left: 26px; }
    .sm-hero h1 { font-size: 37px; }
    .sm-app .modulo { padding: 20px; }
    .sm-app .usuario-datos-layout { display: none; }
}
@media (max-width: 850px) {
    .sm-app .barra-layout { grid-template-columns: 1fr auto; height: auto; min-height: 80px; padding: 15px 20px; }
    .sm-app .titulo-layout { display: none; }
    .sm-app .sidebar { width: 185px; min-width: 185px; }
    .sm-app .sidebar-modulo-enlace { font-size: 11px; gap: 6px; }
    .sm-app .modulos { grid-template-columns: 1fr; }
    .sm-hero { grid-template-columns: 1fr; min-height: 340px; }
    .sm-hero-copy { padding-right: 24px; }
    .sm-orbital { position: absolute; right: -100px; bottom: -75px; width: 300px; opacity: .25; z-index: -1; }
    .sm-section-heading { display: block; }
    .sm-section-heading p { margin-top: 10px; }
    .sm-context-label { display: none; }
}
@media (max-width: 700px) {
    .sm-app .estructura-app { flex-direction: column; }
    .sm-app .sidebar { width: 100%; min-width: 0; min-height: auto; padding: 12px; }
    .sm-app .sidebar-titulo { display: none; }
    .sm-app .sidebar-menu { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 5px; align-items: start; }
    .sm-app .sidebar-modulo-enlace { font-size: 11px; }
    .sm-app .sidebar-cabecera { min-height: 48px; }
    .sm-sidebar-signature { display: none; }
    .sm-app .contenido-modulos { padding: 22px 18px; }
    .sm-hero h1 { font-size: 37px; letter-spacing: -1.7px; }
    .sm-hero-copy { padding: 30px 23px 48px; }
    .sm-hero-label { font-size: 9px; }
    .sm-hero { border-radius: 17px; min-height: 320px; }
    .sm-workspace-note { font-size: 9px; text-align: center; }
    .sm-app .sm-inventory { width: 100%; }
    .sm-inventory .usuarios-titulo { padding: 26px; }
    .sm-inventory .usuarios-titulo p { max-width: 100%; }
    .sm-inventory .contenedor-navegacion { align-items: start; gap: 0; }
    .sm-inventory :is(.btn-listado-productos,.btn-volver-productos) { width: auto; text-align: left; }
    .sm-app .alertas-panel { position: fixed; top: 80px; right: 12px; width: calc(100vw - 24px); max-width: 440px; max-height: calc(100dvh - 100px); overflow-y: auto; }
}
@media (max-width: 430px) {
    .sm-app .barra-layout { padding: 14px 12px; gap: 10px; }
    .sm-app .usuario-layout { gap: 8px; }
    .sm-app .usuario-circulo-layout { display: none; }
    .sm-app .logo-texto-layout { font-size: 22px; }
    .sm-app .logo-cruz-layout { display: none; }
    .sm-app .btn-cerrar-layout { padding: 8px 9px !important; font-size: 10px !important; }
}
@media (prefers-reduced-motion: reduce) {
    .sm-app *, .sm-app *::before, .sm-app *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
    .sm-motion-toggle { display: none; }
    .sm-app .modulo.habilitado:hover { transform: none; }
}
@media print {
    body.sm-app { background: white; }
    .sm-app .sm-skip, .sm-app .sm-motion-toggle { display: none; }
    .sm-app *, .sm-app *::before, .sm-app *::after { animation: none !important; transition: none !important; box-shadow: none !important; }
}

