/* =========================================================
   ESTRUCTURA GENERAL
   ========================================================= */

.estructura-app {
    width: 100%;
    flex: 1;
    display: flex;
    align-items: stretch;
}


.contenido-app {
    min-width: 0;
    flex: 1;
}


    .contenido-app main {
        width: 100%;
    }



/* =========================================================
   BARRA LATERAL
   ========================================================= */

.sidebar {
    width: 245px;
    min-width: 245px;
    min-height: calc(100vh - 144px);
    padding: 25px 14px;
    background: linear-gradient( 180deg, #073b64, #0d5278 );
    color: white;
    box-shadow: 4px 0 14px rgba(0, 0, 0, 0.10);
}



/* =========================================================
   TITULO
   ========================================================= */

.sidebar-titulo {
    margin-bottom: 24px;
    padding: 0 14px 18px;
    border-bottom: 1px solid rgba( 255, 255, 255, 0.18 );
    color: white;
    font-size: 20px;
    font-weight: 700;
}



/* =========================================================
   MENU
   ========================================================= */

.sidebar-menu {
    display: flex;
    flex-direction: column;
    gap: 8px;
}



/* =========================================================
   GRUPO DEL MODULO
   ========================================================= */

.sidebar-grupo {
    width: 100%;
    border-radius: 10px;
}



/* =========================================================
   CABECERA DEL MODULO
   ========================================================= */

.sidebar-cabecera {
    width: 100%;
    min-height: 58px;
    position: relative;
    display: flex;
    align-items: stretch;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid transparent;
    transition: background-color 0.20s ease, transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;
}



    /* =========================================================
   HOVER FUERTE DEL MODULO
   ========================================================= */

    /*
   AHORA EL MODULO RESALTA MUCHO MAS:

   - fondo turquesa
   - borde claro
   - sombra
   - linea lateral
   - pequeño movimiento
*/

    .sidebar-cabecera:hover {
        background: linear-gradient( 90deg, rgba(17, 152, 165, 0.95), rgba(20, 126, 157, 0.85) );
        border-color: rgba( 255, 255, 255, 0.30 );
        box-shadow: 0 5px 14px rgba( 0, 0, 0, 0.20 ), inset 5px 0 0 #69f0ff;
        transform: translateX( 5px );
    }



        /*
   HACER EL TEXTO COMPLETAMENTE BLANCO
   CUANDO PASAMOS SOBRE EL MODULO
*/

        .sidebar-cabecera:hover
        .sidebar-modulo-enlace {
            color: white;
        }



        /*
   AGRANDAR LIGERAMENTE EL ICONO
   AL PASAR EL MOUSE
*/

        .sidebar-cabecera:hover
        .sidebar-icono {
            transform: scale( 1.10 );
        }



    /* =========================================================
   MODULO ACTUAL
   ========================================================= */

    /*
   EL MODULO EN EL QUE ESTAMOS QUEDA
   MARCADO DE FORMA MAS EVIDENTE,
   PERO NO ABRE EL SUBMENU.
*/

    .sidebar-cabecera.activo {
        background: linear-gradient( 90deg, rgba(31, 115, 157, 0.95), rgba(25, 101, 143, 0.85) );
        border-color: rgba( 255, 255, 255, 0.18 );
        box-shadow: inset 5px 0 0 #40d9e6;
    }



        /* SI EL MODULO ACTIVO RECIBE HOVER */

        .sidebar-cabecera.activo:hover {
            background: linear-gradient( 90deg, #1198a5, #1581a4 );
            border-color: rgba( 255, 255, 255, 0.40 );
            box-shadow: 0 5px 15px rgba( 0, 0, 0, 0.22 ), inset 5px 0 0 #7cf4ff;
        }



/* =========================================================
   ENLACE DEL MODULO
   ========================================================= */

.sidebar-modulo-enlace {
    min-width: 0;
    flex: 1;
    padding: 11px 5px 11px 14px;
    display: flex;
    align-items: center;
    gap: 13px;
    color: #eaf6fb;
    text-decoration: none;
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
    transition: color 0.20s ease;
}


    .sidebar-modulo-enlace:hover {
        color: white;
        text-decoration: none;
    }


    .sidebar-modulo-enlace:focus {
        color: white;
        text-decoration: none;
        outline: none;
    }



/* =========================================================
   ICONO PRINCIPAL
   ========================================================= */

.sidebar-icono {
    width: 31px;
    min-width: 31px;
    height: 31px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    transition: transform 0.20s ease;
}



/* =========================================================
   TEXTO
   ========================================================= */

.sidebar-texto {
    min-width: 0;
    flex: 1;
    line-height: 1.25;
}



/* =========================================================
   BOTON DE LA FLECHA
   ========================================================= */

.sidebar-toggle {
    width: 43px;
    min-width: 43px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-left: 1px solid transparent;
    background-color: transparent;
    color: #d9eef7;
    cursor: pointer;
    transition: background-color 0.20s ease, color 0.20s ease, border-color 0.20s ease;
}



    /*
   CUANDO PASAMOS SOBRE LA FLECHA
   SE NOTA QUE ES UNA ZONA DISTINTA
*/

    .sidebar-toggle:hover {
        background-color: rgba( 0, 0, 0, 0.16 );
        border-left-color: rgba( 255, 255, 255, 0.25 );
        color: white;
    }


    .sidebar-toggle:focus {
        outline: none;
        box-shadow: inset 0 0 0 2px rgba( 255, 255, 255, 0.30 );
    }



/* =========================================================
   FLECHA
   ========================================================= */

.sidebar-flecha {
    display: inline-block;
    font-size: 11px;
    transition: transform 0.25s ease;
}



/*
   GIRAR FLECHA SOLAMENTE
   CUANDO EL USUARIO LA PRESIONA
*/

.sidebar-grupo.abierto
.sidebar-flecha {
    transform: rotate( 180deg );
}



/* =========================================================
   SUBMENU
   ========================================================= */

.sidebar-submenu {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    margin-left: 12px;
    margin-right: 5px;
    border-left: 1px solid rgba( 255, 255, 255, 0.20 );
    transition: max-height 0.30s ease, opacity 0.20s ease, padding 0.30s ease;
}



/*
   SOLAMENTE SE ABRE SI JAVASCRIPT
   AGREGA LA CLASE "abierto"
*/

.sidebar-grupo.abierto
.sidebar-submenu {
    max-height: 500px;
    opacity: 1;
    padding: 4px 0 8px;
}



/* =========================================================
   OPCIONES DEL SUBMENU
   ========================================================= */

.sidebar-subopcion {
    min-height: 42px;
    margin: 2px 0 2px 8px;
    padding: 9px 10px;
    display: flex;
    align-items: center;
    gap: 9px;
    border-radius: 7px;
    color: #dceef7;
    text-decoration: none;
    font-size: 13.5px;
    font-weight: 500;
    line-height: 1.2;
    transition: background-color 0.20s ease, color 0.20s ease, padding-left 0.20s ease, transform 0.20s ease;
}



    /* HOVER SUBMODULO */

    .sidebar-subopcion:hover {
        background-color: rgba( 46, 199, 213, 0.28 );
        color: white;
        text-decoration: none;
        padding-left: 15px;
        transform: translateX( 2px );
    }



    /* SUBMODULO ACTIVO */

    .sidebar-subopcion.activo {
        background: linear-gradient( 90deg, rgba(17, 152, 165, 0.90), rgba(15, 135, 160, 0.75) );
        color: white;
        font-weight: 700;
        box-shadow: inset 3px 0 0 #7cf4ff;
    }



/* =========================================================
   ICONO DEL SUBMENU
   ========================================================= */

.sidebar-subicono {
    width: 20px;
    min-width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    opacity: 0.95;
}



/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

    .sidebar {
        width: 205px;
        min-width: 205px;
    }


    .sidebar-modulo-enlace {
        font-size: 14px;
    }


    .sidebar-subopcion {
        font-size: 13px;
    }
}



/* =========================================================
   CELULARES
   ========================================================= */

@media (max-width: 700px) {

    .estructura-app {
        flex-direction: column;
    }


    .sidebar {
        width: 100%;
        min-width: 100%;
        min-height: auto;
        padding: 10px;
    }


    .sidebar-titulo {
        display: none;
    }


    .sidebar-menu {
        flex-direction: column;
        gap: 5px;
        overflow: visible;
    }


    .sidebar-cabecera {
        min-height: 48px;
    }


        .sidebar-cabecera:hover {
            transform: none;
        }


    .sidebar-modulo-enlace {
        padding: 8px 6px 8px 12px;
    }


    .sidebar-icono {
        width: 25px;
        min-width: 25px;
        height: 25px;
        font-size: 17px;
    }


    .sidebar-toggle {
        width: 42px;
        min-width: 42px;
    }


    .sidebar-submenu {
        margin-left: 15px;
    }


    .sidebar-subopcion {
        min-height: 40px;
        font-size: 13px;
    }
}

LoginSARMedix/wwwroot/css/site.css.text:
html {
    font-size: 16px;
    min-height: 100%;
}


/* ================================================== */
/* BODY                                               */
/* ================================================== */

body {
    min-height: 100vh;
    margin: 0;
    display: flex;
    flex-direction: column;
    font-family: "Segoe UI", Arial, Helvetica, sans-serif;
    color: #17324d;
    background: linear-gradient( rgba(225, 242, 247, 0.50), rgba(225, 242, 247, 0.50) ), url('/images/fondo-clinico.png');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
}



/* ================================================== */
/* BARRA SUPERIOR GENERAL                             */
/* ================================================== */

.barra-layout {
    width: 100%;
    height: 82px;
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    align-items: center;
    padding: 0 55px;
    background: #0f5278;
    color: white;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.15);
    flex-shrink: 0;
}



/* ================================================== */
/* LOGO                                               */
/* ================================================== */

.logo-layout {
    display: flex;
    align-items: center;
    gap: 13px;
    color: white;
    text-decoration: none;
    justify-self: start;
}


    .logo-layout:hover {
        color: white;
        text-decoration: none;
    }


.logo-cruz-layout {
    position: relative;
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    border-radius: 10px;
    background: linear-gradient( 135deg, #0d7898, #12a594 );
    box-shadow: 0 5px 12px rgba(0, 0, 0, 0.18);
}


    .logo-cruz-layout::before {
        content: "";
        position: absolute;
        width: 22px;
        height: 7px;
        top: 17px;
        left: 10px;
        border-radius: 2px;
        background-color: white;
    }


    .logo-cruz-layout::after {
        content: "";
        position: absolute;
        width: 7px;
        height: 22px;
        top: 10px;
        left: 17px;
        border-radius: 2px;
        background-color: white;
    }


.logo-texto-layout {
    color: white;
    font-size: 25px;
    font-weight: 700;
    letter-spacing: 0.2px;
    white-space: nowrap;
}



/* ================================================== */
/* TITULO CENTRAL                                     */
/* ================================================== */

.titulo-layout {
    justify-self: center;
    color: white;
    text-align: center;
    font-size: 25px;
    font-weight: 600;
    white-space: nowrap;
}



/* ================================================== */
/* USUARIO                                            */
/* ================================================== */

.usuario-layout {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    justify-self: end;
    gap: 12px;
    min-width: 0;
}


.usuario-datos-layout {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    line-height: 1.2;
}


.usuario-nombre-layout {
    max-width: 190px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: white;
    font-size: 15px;
    font-weight: 600;
}


.usuario-rol-layout {
    margin-top: 4px;
    color: #cfe7f3;
    font-size: 13px;
    font-weight: 400;
}


.usuario-circulo-layout {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid rgba(255, 255, 255, 0.72);
    border-radius: 50%;
    background-color: rgba(255, 255, 255, 0.14);
    color: white;
    font-size: 18px;
    font-weight: 700;
}



/* ================================================== */
/* BOTON CERRAR SESION                                */
/* ================================================== */

.form-cerrar-layout {
    margin: 0;
    padding: 0;
}


.btn-cerrar-layout {
    width: auto !important;
    height: auto !important;
    margin: 0 !important;
    padding: 9px 16px !important;
    border: 1px solid rgba(255, 255, 255, 0.70) !important;
    border-radius: 7px !important;
    background-color: transparent !important;
    color: white !important;
    font-family: inherit;
    font-size: 14px !important;
    font-weight: 600 !important;
    cursor: pointer;
    transition: background-color 0.2s ease, border-color 0.2s ease;
}


    .btn-cerrar-layout:hover {
        background-color: rgba(255, 255, 255, 0.18) !important;
        border-color: white !important;
    }



/* ================================================== */
/* CONTENEDOR DEL LAYOUT                              */
/* ================================================== */

.contenedor-layout {
    width: 100%;
    max-width: 100% !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    flex: 1;
}


main {
    min-height: calc( 100vh - 144px );
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px 20px !important;
}



    /* ================================================== */
    /* CABECERA FORMULARIO                                */
    /* ================================================== */

    main > h2 {
        width: 100%;
        max-width: 520px;
        margin: 0;
        padding: 42px 48px 18px;
        box-sizing: border-box;
        background: rgba(255, 255, 255, 0.97);
        text-align: center;
        color: #093b62;
        font-size: 31px;
        font-weight: 700;
        border-radius: 20px 20px 0 0;
        box-shadow: 0 18px 45px rgba(16, 65, 95, 0.18);
    }



        /* LOGO CLINICO FORMULARIO */

        main > h2::before {
            content: "+";
            display: flex;
            align-items: center;
            justify-content: center;
            width: 76px;
            height: 76px;
            margin: 0 auto 22px;
            border-radius: 20px;
            background: linear-gradient( 135deg, #075985, #12a594 );
            color: white;
            font-size: 48px;
            font-weight: 600;
            line-height: 1;
            box-shadow: 0 8px 18px rgba(0, 93, 125, 0.20);
        }



        /* SAR DE CHIGUAY */

        main > h2::after {
            content: "SAR de Chiguay";
            display: block;
            margin-top: 10px;
            font-size: 17px;
            font-weight: 400;
            color: #657d90;
        }



    /* ================================================== */
    /* FORMULARIO PRINCIPAL                               */
    /* ================================================== */

    main form.formulario-principal {
        width: 100%;
        max-width: 520px;
        box-sizing: border-box;
        padding: 24px 48px 42px;
        background: rgba(255, 255, 255, 0.97);
        border-radius: 0 0 20px 20px;
        box-shadow: 0 22px 45px rgba(16, 65, 95, 0.18);
    }


        main form.formulario-principal > div {
            margin-bottom: 22px;
        }


        main form.formulario-principal label {
            display: block;
            margin-bottom: 8px;
            font-size: 15px;
            font-weight: 600;
            color: #173d5c;
        }


        main form.formulario-principal input[type="text"],
        main form.formulario-principal input[type="email"],
        main form.formulario-principal input[type="password"],
        main form.formulario-principal input[type="number"],
        main form.formulario-principal input[type="date"],
        main form.formulario-principal select {
            width: 100%;
            height: 55px;
            box-sizing: border-box;
            padding: 0 18px;
            border: 1px solid #bacdd9;
            border-radius: 10px;
            background: #fafdff;
            font-size: 16px;
            color: #17324d;
            outline: none;
            transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
        }


        main form.formulario-principal textarea {
            width: 100%;
            min-height: 110px;
            box-sizing: border-box;
            padding: 14px 18px;
            border: 1px solid #bacdd9;
            border-radius: 10px;
            background: #fafdff;
            font-size: 16px;
            color: #17324d;
            font-family: inherit;
            resize: vertical;
            outline: none;
        }


            main form.formulario-principal input:focus,
            main form.formulario-principal select:focus,
            main form.formulario-principal textarea:focus {
                background: white;
                border-color: #1187a5;
                box-shadow: 0 0 0 4px rgba(17, 135, 165, 0.12);
            }



/* ================================================== */
/* VALIDACION GLOBAL SARMedix                         */
/* ================================================== */

/*
    ESTA ES LA REGLA OFICIAL PARA CAMPOS CON ERROR.

    La repetición ".campo-error.campo-error"
    es intencional.

    Algunas vistas antiguas poseen estilos
    con !important.

    Al aumentar la especificidad conseguimos
    que este borde rojo gane sin tener que
    modificar cada vista.
*/

html body input.campo-error.campo-error,
html body select.campo-error.campo-error,
html body textarea.campo-error.campo-error {
    border: 1px solid #dc3545 !important;
    border-color: #dc3545 !important;
    background-color: #fff8f8 !important;
    box-shadow: 0 0 0 3px rgba(220, 53, 69, 0.10) !important;
    outline: none !important;
}


    /*
    Mientras el campo incorrecto tenga el foco,
    continúa rojo.

    Solamente desaparece cuando el usuario
